window.JPG=window.JPG||{};JPG.N3=[{"id":"g3_073","t":"～など","ko":"~등, ~같은 것","cat":"조사","conn":[{"w":"명사","f":"肉 + など"},{"w":"명사や명사","f":"肉や魚 + など"},{"w":"동사 보통형","f":"手伝う + など"}],"rule":["1. 예로 들 명사 바로 뒤에 など를 붙인다(활용 변화 없음).","2. 여러 개를 들 때는 명사 や 명사 など 처럼 마지막 예 뒤에 한 번만 붙인다.","3. 뒤에 조사 を・が・に・の 등을 그대로 이어 쓸 수 있다(などを, などの).","4. 이것 말고도 더 있다는 뜻이 남는다."],"why":"","nu":"회화와 문장 모두에 쓰는 중립적인 말이다. 자신을 낮추거나 남을 깎아내릴 때도 쓴다(私などには無理です). 회화에서 더 가볍게 말하면 なんか가 된다. 한국어 '등'처럼 문장 끝에 덧붙이는 것이 아니라 명사 바로 뒤에 붙이고 조사를 이어야 한다.","cmp":[{"g":"～なんか","d":"など의 회화체. 깎아내리는 느낌이 더 강하다."},{"g":"～とか","d":"회화에서 예를 하나하나 나열(肉とか魚とか). など는 마지막에 한 번 붙여 묶는다."}],"ex":[{"jp":"スーパーで肉[にく]や魚[さかな]などを買[か]った。","ko":"슈퍼에서 고기와 생선 등을 샀다."},{"jp":"京都[きょうと]や奈良[なら]などの古[ふる]い町[まち]が好[す]きです。","ko":"교토나 나라 같은 오래된 도시를 좋아합니다."},{"jp":"私[わたし]などにはとてもできません。","ko":"저 같은 사람은 도저히 못 합니다."}],"dr":[{"t":"make","q":"りんご・バナナ → ～などを買った","a":"りんごやバナナなどを買った","hint":"명사 や 명사 + など + を"},{"t":"make","q":"ペン・ノート → ～などが必要だ","a":"ペンやノートなどが必要だ","hint":"마지막 명사 뒤에 など, 그 뒤에 が"},{"t":"fill","q":"テニスやサッカー（　）のスポーツが好[す]きです。","a":"など","opts":["など","ばかり","だけに","さえ"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%AA%E3%81%A9","https://jlptsensei.com/learn-japanese-grammar/など-nado-meaning"],"vf":1,"u":1,"g":1,"gp":"gg_N3_00"},{"id":"g3_074","t":"～なんか","ko":"~따위, ~같은 거","cat":"조사","conn":[{"w":"명사","f":"お金 + なんか"},{"w":"동사 て형","f":"泣いて + なんか + いない"}],"rule":["1. 명사 바로 뒤에 なんか를 붙인다(활용 변화 없음).","2. 뒤에는 조사 を・が를 생략하고 바로 술어를 잇는 일이 많다(お金なんかいらない).","3. 동사를 부정할 때는 て형 뒤에 なんか를 넣고 いない로 받는다(泣いてなんかいない)."],"why":"","nu":"회화체 전용으로, など를 가볍게 말한 형태다. 예를 들 때(お茶なんかどう?), 자신을 낮출 때(私なんか), 대상을 깎아내릴 때(お金なんかいらない) 쓴다. 윗사람이나 상대의 물건에 쓰면 무례하게 들릴 수 있다. 문장 앞에 혼자 오는 なんか(なんか疲れた, '왠지')는 다른 용법이다.","cmp":[{"g":"～など","d":"중립적이고 문장에도 쓴다. なんか는 회화체."},{"g":"～なんて","d":"놀람·경시를 나타내며 문장 전체에도 붙는다(会えるなんて)."}],"ex":[{"jp":"お金[かね]なんかいらない。","ko":"돈 따위 필요 없어."},{"jp":"私[わたし]なんかまだまだです。","ko":"저 같은 건 아직 멀었어요."},{"jp":"泣[な]いてなんかいないよ。","ko":"울고 있는 거 아니야."}],"dr":[{"t":"make","q":"あの人を信じない → ～なんか","a":"あの人なんか信じない","hint":"명사 + なんか, を를 빼고 술어로"},{"t":"make","q":"怒っていない → ～なんか（강한 부정）","a":"怒ってなんかいない","hint":"て형 + なんか + いない"},{"t":"fill","q":"宿題[しゅくだい]（　）やりたくない。","a":"なんか","opts":["なんか","ばかりか","について","だけに"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AA%E3%82%93%E3%81%8B-%E3%81%AA%E3%82%93%E3%81%A6","https://www.kanshudo.com/grammar/なんか"],"vf":1,"u":1,"g":1,"gp":"gg_N3_00"},{"id":"g3_086","t":"～の～","ko":"~의 (명사와 명사를 잇는 の)","cat":"조사","conn":[{"w":"명사 + 명사(소유)","f":"私 + の + 傘"},{"w":"명사 + 명사(소속)","f":"会社 + の + 人"},{"w":"명사 + 명사(장소·때)","f":"東京 + の + 店 / 夏 + の + 夜"}],"rule":["1. 명사1과 명사2 사이에 の를 넣어 명사1이 명사2를 꾸미게 한다(私の傘).","2. 소유, 소속, 내용·종류, 장소, 때 등 여러 관계를 나타낸다.","3. 형용사가 명사를 꾸밀 때는 の를 쓰지 않는다: い형용사는 그대로(大きい家), な형용사는 な(静かな町)."],"why":"","nu":"회화와 문장 모두에 쓰는 가장 기본적인 조사다. 한국어는 '일본어 선생님'처럼 '의'를 자주 생략하지만 일본어에서는 명사끼리 이을 때 대부분 の가 필요하다(日本語の先生). 반대로 형용사 뒤에 の를 넣는 실수(大きいの家 ×)도 흔하다. 앞에 나온 명사 대신 쓰는 の(これは私のです)도 있다.","cmp":[{"g":"な (な형용사)","d":"な형용사가 명사를 꾸밀 때는 な(きれいな花). 명사 + 명사일 때만 の."}],"ex":[{"jp":"これは私[わたし]の傘[かさ]です。","ko":"이것은 제 우산입니다."},{"jp":"日本語[にほんご]の先生[せんせい]はとても優[やさ]しい。","ko":"일본어 선생님은 아주 상냥하다."},{"jp":"駅[えき]の前[まえ]の店[みせ]で待[ま]っています。","ko":"역 앞 가게에서 기다리고 있겠습니다."}],"dr":[{"t":"make","q":"兄 + 車（소유）","a":"兄の車","hint":"명사1 + の + 명사2"},{"t":"make","q":"英語 + 本（내용）","a":"英語の本","hint":"한국어 '영어 책'이어도 の가 필요"},{"t":"fill","q":"これは田中[たなか]さん（　）かばんですか。","a":"の","opts":["の","な","が","を"]}],"src":["https://bunpro.jp/ja/grammar_points/particle-%E3%81%AE","https://bunpro.jp/ja/grammar_points/%E3%81%AE"],"vf":1,"u":1,"g":1,"gp":"gg_N3_00"},{"id":"g3_099","t":"～まで","ko":"~까지","cat":"조사","conn":[{"w":"명사(시간)","f":"10時 + まで"},{"w":"명사(장소)","f":"駅 + まで"},{"w":"동사 사전형","f":"雨が止む + まで"}],"rule":["1. 시간·장소 명사에 그대로 まで를 붙인다(10時まで, 駅まで).","2. 동사는 사전형에 まで를 붙인다(止む→止むまで).","3. 시작점은 から로 나타내 짝을 이룬다(9時から6時まで).","4. 뒤에는 그때까지 계속되는 동작·상태가 온다(待つ, 働く)."],"why":"","nu":"まで 뒤에는 그 시점까지 계속되는 동작이 온다. 기한(그때까지 한 번 끝내는 일)은 までに를 쓴다. 한국어 '까지'는 두 경우를 다 나타내므로 혼동하기 쉽다. まで에는 '~조차, ~까지도'(子供まで知っている)라는 용법도 있다.","cmp":[{"g":"～までに","d":"기한. 뒤에 한 번 일어나는 동작이 온다(5時までに帰る)."}],"ex":[{"jp":"毎日[まいにち]9時[くじ]から6時[ろくじ]まで働[はたら]いています。","ko":"매일 9시부터 6시까지 일하고 있습니다."},{"jp":"駅[えき]まで歩[ある]いて10分[じゅっぷん]です。","ko":"역까지 걸어서 10분입니다."},{"jp":"雨[あめ]が止[や]むまで、ここで待[ま]ちましょう。","ko":"비가 그칠 때까지 여기서 기다립시다."}],"dr":[{"t":"make","q":"止む／待つ → ～まで","a":"止むまで待つ","hint":"사전형 + まで + 계속되는 동작"},{"t":"make","q":"東京／行く → ～まで","a":"東京まで行く","hint":"장소 명사 + まで"},{"t":"fill","q":"母[はは]が帰[かえ]ってくる（　）、テレビを見[み]ていた。","a":"まで","opts":["まで","までに","ので","より"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/200911.html"],"vf":1,"u":1,"g":1,"gp":"gg_N3_00"},{"id":"g3_003","t":"～（よ）うとした","ko":"~하려고 했다","cat":"활용","conn":[{"w":"1그룹 동사","f":"話す → 話そう + とした"},{"w":"2그룹 동사","f":"食べる → 食べよう + とした"},{"w":"する","f":"する → しよう + とした"},{"w":"来る","f":"来る → 来よう(こよう) + とした"}],"rule":["1. 동사를 의향형으로 바꾼다: 1그룹은 어미 う단을 お단으로 바꾸고 う를 붙인다(話す → 話そう).","2. 2그룹은 る를 떼고 よう를 붙인다(食べる → 食べよう). する → しよう, 来る → 来よう(こよう).","3. 의향형 뒤에 とした(とする의 과거)를 붙인다(話そうとした).","4. 뒤에 が・けど가 와서 '하려 했지만 못 했다'로 이어지는 일이 많다."],"why":"의향형(~하자/~하겠다) + と(인용) + する(하다)로, '~하려고 마음먹고 움직였다'는 뜻이 된다.","nu":"의지 동사에 붙으면 '시도했다'(실현 여부는 뒤 문맥으로), 의지가 없는 동사·무생물 주어에 붙으면 '막 ~하려던 참'(ドアが閉まろうとした)을 뜻한다. 「～ようとしない」는 '~하려 하지 않는다'(거부). 한국어 '~려고 했다'를 직역해 사전형+とした(話すとした)로 쓰는 실수에 주의.","cmp":[{"g":"～てみた","d":"てみた는 실제로 해 보았다(실행함). ようとした는 하려고 했을 뿐 실행·성공하지 못한 경우가 많다."}],"ex":[{"jp":"電話[でんわ]に出[で]ようとしたら、切[き]れてしまった。","ko":"전화를 받으려고 했더니 끊겨 버렸다."},{"jp":"何[なに]か話[はな]そうとしたが、言葉[ことば]が出[で]なかった。","ko":"뭔가 말하려고 했지만 말이 나오지 않았다."},{"jp":"家[いえ]を出[で]ようとした時[とき]、雨[あめ]が降[ふ]り始[はじ]めた。","ko":"집을 나서려던 때 비가 내리기 시작했다."}],"dr":[{"t":"make","q":"書く → ～ようとした","a":"書こうとした","hint":"く를 お단 こ로 바꾸고 う + とした"},{"t":"make","q":"寝る → ～ようとした","a":"寝ようとした","hint":"2그룹은 る를 떼고 よう + とした"},{"t":"fill","q":"ドアを開[あ]け（　）が、鍵[かぎ]がかかっていた。","a":"ようとした","opts":["ようとした","てしまった","たばかりだ","ながら"]}],"src":["https://nihongokyoshi-net.com/2019/07/25/jlptn2-grammar-youtoshiteiru/","https://bunpro.jp/grammar_points/verb-volitional%E3%81%A8%E3%81%99%E3%82%8B"],"vf":1,"u":2,"g":1,"gp":"gg_N3_00"},{"id":"g3_005","t":"～かけ","ko":"~하다 만, ~하던 도중","cat":"활용","conn":[{"w":"1그룹 동사","f":"読む → 読み + かけ"},{"w":"2그룹 동사","f":"食べる → 食べ + かけ"},{"w":"する","f":"する → し + かけ"},{"w":"뒤에 오는 꼴","f":"読みかけの本 / 読みかけだ / 読みかける"}],"rule":["1. 동사를 ます형(ます를 뗀 꼴)으로 바꾼다: 1그룹은 어미 う단을 い단으로(読む → 読み), 2그룹은 る를 뗀다(食べる → 食べ).","2. ます형 뒤에 かけ를 붙인다(読みかけ).","3. 명사를 꾸밀 때는 の를 넣고(読みかけの本), 문장 끝에서는 だ・です를 붙인다(読みかけだ).","4. 동사로 쓸 때는 かける로 활용한다(言いかけてやめた)."],"why":"동사 かける(막 ~하기 시작하다)의 ます형 명사꼴 かけ가 다른 동사 ます형에 붙은 것이다.","nu":"시작은 했지만 끝내지 않은 상태를 말한다(読みかけの本, 食べかけのパン). 「死にかける」「忘れかける」처럼 '막 ~할 뻔하다·되려 하다'의 뜻도 있다. 회화·문장 모두 쓴다. 사전형에 붙이는 실수(読むかけ)에 주의.","cmp":[{"g":"～途中","d":"途中는 '도중'이라는 명사로 진행 중인 과정을 넓게 말한다(読んでいる途中). かけ는 하다가 멈춰 둔 상태가 중심."}],"ex":[{"jp":"机[つくえ]の上[うえ]に読[よ]みかけの本[ほん]がある。","ko":"책상 위에 읽다 만 책이 있다."},{"jp":"食[た]べかけのパンを冷蔵庫[れいぞうこ]に入[い]れた。","ko":"먹다 만 빵을 냉장고에 넣었다."},{"jp":"彼[かれ]は何[なに]か言[い]いかけて、やめた。","ko":"그는 뭔가 말하려다가 그만두었다."}],"dr":[{"t":"make","q":"飲む → ～かけの","a":"飲みかけの","hint":"む를 い단 み로 바꾸고 かけの"},{"t":"make","q":"書く → ～かけだ","a":"書きかけだ","hint":"く를 い단 き로 바꾸고 かけだ"},{"t":"fill","q":"テーブルに飲[の]み（　）のコーヒーが置[お]いてある。","a":"かけ","opts":["かけ","たて","ながら","すぎ"]}],"src":["https://cotoacademy.com/?p=97729","https://bunpro.jp/grammar_points/307"],"vf":1,"u":2,"g":1,"gp":"gg_N3_00"},{"id":"g3_007","t":"～ないで","ko":"~하지 않고, ~하지 말고","cat":"활용","conn":[{"w":"1그룹 동사","f":"聞く → 聞かない + で"},{"w":"2그룹 동사","f":"食べる → 食べない + で"},{"w":"する","f":"する → しない + で"},{"w":"来る","f":"来る → 来ない(こない) + で"}],"rule":["1. 동사를 ない형으로 바꾼다: 1그룹은 어미 う단을 あ단으로 바꾸고 ない(聞く → 聞かない, 단 う로 끝나면 わ: 買う → 買わない).","2. 2그룹은 る를 떼고 ない를 붙인다(食べる → 食べない). する → しない, 来る → 来ない(こない).","3. ない 뒤에 で를 붙인다(食べないで).","4. 뒤에 주된 동작이 이어져 '~하지 않은 채로 …하다'가 된다."],"why":"부정 조동사 ない에 접속 조사 で가 붙은 꼴로, 동사의 て형처럼 다음 동작으로 이어 준다.","nu":"'A하지 않고(그 대신·그 상태로) B하다'라는 부대 상황을 말한다(朝ご飯を食べないで出かけた). 「～ないでください」는 '~하지 마세요'. 원인·이유(~하지 않아서)에는 「～なくて」를 쓴다(雨が降らなくて困る). 회화에서는 「～ずに」보다 ないで가 더 흔하다.","cmp":[{"g":"～なくて","d":"なくて는 원인(~하지 않아서)이나 대비. ないで는 '~하지 않은 채로'의 동작 방식."},{"g":"～ずに","d":"ずに는 ないで와 같은 뜻의 문어적 표현. する는 せずに."}],"ex":[{"jp":"今朝[けさ]は朝[あさ]ご飯[はん]を食[た]べないで学校[がっこう]へ行[い]った。","ko":"오늘 아침은 아침밥을 먹지 않고 학교에 갔다."},{"jp":"誰[だれ]にも聞[き]かないで、一人[ひとり]で調[しら]べた。","ko":"아무에게도 묻지 않고 혼자 조사했다."},{"jp":"昨日[きのう]は勉強[べんきょう]しないで寝[ね]てしまった。","ko":"어제는 공부하지 않고 자 버렸다."}],"dr":[{"t":"make","q":"待つ → ～ないで","a":"待たないで","hint":"つ를 あ단 た로 바꾸고 ない + で"},{"t":"make","q":"見る → ～ないで","a":"見ないで","hint":"2그룹은 る를 떼고 ない + で"},{"t":"fill","q":"傘[かさ]を持[も]た（　）出[で]かけたら、雨[あめ]に降[ふ]られた。","a":"ないで","opts":["ないで","なくて","ないと","なければ"]}],"src":["https://laits.utexas.edu/japanese/joshu/grammar/glist/y2/ch3/gl_y2_ch3_wonaide.php","https://bunpro.jp/grammar_points/96"],"vf":1,"u":2,"g":1,"gp":"gg_N3_00"},{"id":"g3_025","t":"～ずに","ko":"~하지 않고","cat":"활용","conn":[{"w":"1그룹 동사","f":"飲む → 飲まない → 飲まずに"},{"w":"2그룹 동사","f":"食べる → 食べない → 食べずに"},{"w":"する","f":"する → せずに"},{"w":"来る","f":"来る → 来ずに(こずに)"}],"rule":["1. 동사를 ない형으로 바꾼다: 1그룹은 어미 う단을 あ단으로(飲む → 飲まない).","2. ない를 뗀다(飲ま).","3. 남은 부분에 ずに를 붙인다(飲まずに).","4. 2그룹은 る를 떼고 ずに(食べずに). する는 せずに, 来る는 来ずに(こずに)."],"why":"옛 부정 조동사 ず에 に가 붙은 꼴로, 뜻은 ～ないで와 같다.","nu":"'~하지 않은 채로 …하다'. ～ないで보다 약간 딱딱하고 글에서 많이 쓰지만 회화에도 쓴다. する를 しずに로 만드는 실수가 많다(정답은 せずに).","cmp":[{"g":"～ないで","d":"뜻은 같고 더 회화적이다. ないでください(~하지 마세요)는 ずに로 바꿀 수 없다."}],"ex":[{"jp":"今朝[けさ]はコーヒーを飲[の]まずに家[いえ]を出[で]た。","ko":"오늘 아침에는 커피를 마시지 않고 집을 나섰다."},{"jp":"昨日[きのう]は勉強[べんきょう]せずに寝[ね]てしまった。","ko":"어제는 공부하지 않고 자 버렸다."},{"jp":"彼[かれ]は何[なに]も言[い]わずに帰[かえ]った。","ko":"그는 아무 말도 하지 않고 돌아갔다."}],"dr":[{"t":"make","q":"書く → ～ずに","a":"書かずに","hint":"く를 あ단 か로 바꾸고 ずに"},{"t":"make","q":"勉強する → ～ずに","a":"勉強せずに","hint":"する는 せずに"},{"t":"fill","q":"傘[かさ]を持[も]た（　）出[で]かけた。","a":"ずに","opts":["ずに","なくて","ないと","なければ"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%9A%E3%81%AB"],"vf":1,"u":3,"g":1,"gp":"gg_N3_00"},{"id":"g3_040","t":"～ちゃった／～じゃった","ko":"~해 버렸다","cat":"활용","conn":[{"w":"동사 て형(～て)","f":"食べて → 食べちゃった"},{"w":"동사 て형(～で)","f":"飲んで → 飲んじゃった"},{"w":"する","f":"して → しちゃった"}],"rule":["1. 동사를 て형으로 바꾼다(食べる → 食べて).","2. ～てしまった의 て + しま 부분이 ちゃ로 줄어든다(食べてしまった → 食べちゃった).","3. て형이 で로 끝나면 で + しま가 じゃ로 줄어든다(飲んでしまった → 飲んじゃった).","4. 현재형은 ～ちゃう／～じゃう(食べちゃう)."],"why":"～てしまった를 빨리 말하면서 てしま → ちゃ, でしま → じゃ로 줄어든 회화 축약형이다.","nu":"친한 사이의 회화체. 실수나 아쉬움(~해 버렸다) 또는 완전히 끝냄을 나타낸다. 글이나 윗사람에게는 ～てしまいました를 쓴다.","cmp":[{"g":"～てしまった","d":"같은 뜻의 원래 형태. 글이나 정중체(～てしまいました)에도 쓸 수 있다."}],"ex":[{"jp":"ケーキを全部[ぜんぶ]食[た]べちゃった。","ko":"케이크를 전부 먹어 버렸다."},{"jp":"弟[おとうと]のジュースを飲[の]んじゃった。","ko":"남동생 주스를 마셔 버렸다."},{"jp":"また失敗[しっぱい]しちゃった。","ko":"또 실수해 버렸다."}],"dr":[{"t":"make","q":"食べてしまった → ～ちゃった","a":"食べちゃった","hint":"てしま → ちゃ"},{"t":"make","q":"読んでしまった → ～じゃった","a":"読んじゃった","hint":"でしま → じゃ"},{"t":"fill","q":"電車[でんしゃ]に傘[かさ]を忘[わす]れ（　）。","a":"ちゃった","opts":["ちゃった","じゃった","ついでに","たびに"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/てしまう-te-shimau-ちゃう-meaning","https://bunpro.jp/grammar_points/172"],"vf":1,"u":3,"g":1,"gp":"gg_N3_00"},{"id":"g3_044","t":"～っぱなし","ko":"~한 채로 내버려 둠, 계속 ~함","cat":"활용","conn":[{"w":"1그룹 동사 ます형","f":"出し(ます) + っぱなし"},{"w":"2그룹 동사 ます형","f":"開け(ます) + っぱなし"},{"w":"する","f":"し(ます) + っぱなし"}],"rule":["1. 동사를 ます형으로 바꾸고 ます를 뗀다(出す → 出し, 開ける → 開け).","2. 그 뒤에 っぱなし를 붙인다(出しっぱなし).","3. 뒤에 ～にする, ～だ, ～で 등을 이어 쓴다(水を出しっぱなしにする)."],"why":"","nu":"회화체. 해야 할 마무리(끄기, 닫기, 치우기)를 하지 않고 그대로 둔 것을 비판하는 느낌이 강하다. 立ちっぱなし, 負けっぱなし처럼 같은 상태가 계속되는 뜻으로도 쓴다.","cmp":[{"g":"～たまま","d":"어떤 상태가 그대로인 것을 중립적으로 말한다(眼鏡をかけたまま寝た). っぱなし는 방치에 대한 불만이 더 강하다."}],"ex":[{"jp":"電気[でんき]をつけっぱなしで寝[ね]てしまった。","ko":"불을 켜 놓은 채로 잠들어 버렸다."},{"jp":"水[みず]を出[だ]しっぱなしにしないでください。","ko":"물을 틀어 놓은 채로 두지 마세요."},{"jp":"今日[きょう]は一日中[いちにちじゅう]立[た]ちっぱなしで疲[つか]れた。","ko":"오늘은 하루 종일 서 있기만 해서 지쳤다."}],"dr":[{"t":"make","q":"開ける → ～っぱなし","a":"開けっぱなし","hint":"ます형 開け + っぱなし"},{"t":"make","q":"出す → ～っぱなし","a":"出しっぱなし","hint":"す → し(ます형) + っぱなし"},{"t":"fill","q":"窓[まど]を開[あ]け（　）にして出[で]かけた。","a":"っぱなし","opts":["っぱなし","ながら","たびに","とたん"]}],"src":["https://cotoacademy.com/jlpt-n3-grammar-point-っぱなし/"],"vf":1,"u":3,"g":1,"gp":"gg_N3_00"},{"id":"g3_062","t":"～とく","ko":"~해 둘게, ~해 놓다 (ておく의 회화체)","cat":"활용","conn":[{"w":"동사(て로 끝나는 て형)","f":"買っておく → 買っとく"},{"w":"동사(で로 끝나는 て형)","f":"読んでおく → 読んどく"},{"w":"する","f":"しておく → しとく"}],"rule":["1. 동사를 て형으로 바꾼 뒤 おく를 붙인다(買っておく).","2. て형 끝의 て와 おく의 お가 합쳐져 と가 된다(買っとく).","3. て형이 で로 끝나면 で+お가 ど가 된다(読んでおく → 読んどく).","4. 그 뒤는 おく처럼 활용한다: とこう(의지), といて(て형), といた(た형)."],"why":"～ておく의 te+o가 발음상 to로 줄어든 축약형이다.","nu":"친한 사이의 회화에서 쓰는 말. 글이나 윗사람에게는 ～ておきます를 쓴다. 뜻은 ておく와 같아서 '미리 해 두다', '그대로 놔두다'를 나타낸다.","cmp":[{"g":"～ておく","d":"원래 형태. 정중한 말이나 글에서는 이쪽을 쓴다."},{"g":"～ちゃう","d":"てしまう의 회화 축약(食べちゃう). 뜻이 '~해 버리다'로 다르다."}],"ex":[{"jp":"飲[の]み物[もの]は私[わたし]が買[か]っとくね。","ko":"음료는 내가 사 둘게."},{"jp":"明日[あした]までにこの本[ほん]、読[よ]んどいて。","ko":"내일까지 이 책 읽어 둬."},{"jp":"試験[しけん]が近[ちか]いから、今[いま]から勉強[べんきょう]しとこう。","ko":"시험이 가까우니까 지금부터 공부해 두자."}],"dr":[{"t":"make","q":"買っておく → ～とく","a":"買っとく","hint":"て + お → と"},{"t":"make","q":"読んでおく → ～どく","a":"読んどく","hint":"で + お → ど"},{"t":"fill","q":"パーティーの前[まえ]に、ビールを冷蔵庫[れいぞうこ]に入[い]れ（　）ね。","a":"とく","opts":["とく","ちゃう","てる","たら"]}],"src":["https://www.weblio.jp/content/…とく"],"vf":1,"u":4,"g":1,"gp":"gg_N3_00"},{"id":"g3_120","t":"～ている","ko":"~하고 있다, ~해 있다","cat":"활용","conn":[{"w":"1그룹 동사","f":"読む → 読んで + いる"},{"w":"1그룹 동사(行く)","f":"行く → 行って + いる"},{"w":"2그룹 동사","f":"寝る → 寝て + いる"},{"w":"する","f":"勉強する → 勉強して + いる"},{"w":"来る","f":"来る → 来て(きて) + いる"}],"rule":["1. 동사를 て형으로 만든다. 1그룹의 む·ぶ·ぬ는 んで가 된다(読む → 読んで).","2. 2그룹 동사는 る를 て로 바꾼다(寝る → 寝て).","3. て형 뒤에 いる를 붙인다(読んでいる).","4. 회화에서는 い가 빠져 読んでる처럼 말하기도 한다."],"why":"","nu":"계속되는 동작에 붙으면 진행(本を読んでいる), 순간에 끝나는 변화 동사(結婚する, 開く, 死ぬ)에 붙으면 그 결과가 남아 있는 상태(結婚している = 결혼한 상태)를 나타낸다. 습관(毎朝走っている)에도 쓴다. 한국어 '결혼하고 있다'처럼 진행으로 오해하기 쉽다. 수동형에도 붙는다(窓が開けられている).","cmp":[{"g":"～てある","d":"누군가 의도적으로 해 둔 결과 상태. 타동사에 붙는다(窓が開けてある). 窓が開いている는 단순히 열려 있는 상태."}],"ex":[{"jp":"弟[おとうと]は部屋[へや]で本[ほん]を読[よ]んでいる。","ko":"남동생은 방에서 책을 읽고 있다."},{"jp":"姉[あね]はもう結婚[けっこん]している。","ko":"언니는 이미 결혼했다."},{"jp":"窓[まど]が開[あ]いているから、少[すこ]し寒[さむ]い。","ko":"창문이 열려 있어서 조금 춥다."}],"dr":[{"t":"make","q":"飲む → ～ている","a":"飲んでいる","hint":"む를 んで로 + いる"},{"t":"make","q":"待つ → ～ている","a":"待っている","hint":"つ를 って로 + いる"},{"t":"fill","q":"兄[あに]は五年前[ごねんまえ]から東京[とうきょう]に住[す]んで（　）。","a":"いる","opts":["いる","ある","みる","おく"]}],"src":[],"vf":0,"u":4,"g":1,"gp":"gg_N3_00"},{"id":"g3_128","t":"～上げる","ko":"다 ~하다, ~해 내다(완성)","cat":"활용","conn":[{"w":"1그룹 동사 ます형","f":"書き + 上げる"},{"w":"1그룹 동사 ます형","f":"作り + 上げる"},{"w":"2그룹 동사 ます형","f":"育て + 上げる"}],"rule":["1. 1그룹 동사는 어미 う단을 い단으로 바꿔 ます형을 만든다(書く → 書き).","2. 2그룹 동사는 る를 떼어 ます형을 만든다(育てる → 育て).","3. ます형 뒤에 上げる를 붙인다(書き上げる). 上げる는 2그룹 동사로 활용한다(書き上げた)."],"why":"","nu":"시간과 노력을 들여 무언가를 끝까지 완성했다는 뜻으로, 書く·作る·育てる·編む처럼 무언가를 만들어 내는 동사와 주로 어울린다. 아무 동사에나 붙는 것은 아니다. 持ち上げる처럼 '위로 올리다'라는 뜻의 복합동사도 있으니 문맥으로 구별한다.","cmp":[{"g":"～終わる","d":"終わる는 동작이 끝났다는 사실만 말한다(食べ終わる). 上げる는 노력해서 작품·결과물을 완성했다는 느낌이 있다."}],"ex":[{"jp":"レポートを一晩[ひとばん]で書[か]き上[あ]げた。","ko":"리포트를 하룻밤에 다 써냈다."},{"jp":"みんなで一[ひと]つの作品[さくひん]を作[つく]り上[あ]げた。","ko":"다 함께 하나의 작품을 만들어 냈다."},{"jp":"母[はは]は一人[ひとり]で三人[さんにん]の子[こ]どもを育[そだ]て上[あ]げた。","ko":"어머니는 혼자서 세 아이를 길러 냈다."}],"dr":[{"t":"make","q":"書く → ～上げる","a":"書き上げる","hint":"く를 き로 바꾼 ます형 + 上げる"},{"t":"make","q":"作る → ～上げる","a":"作り上げる","hint":"る를 り로 바꾼 ます형 + 上げる"},{"t":"fill","q":"徹夜[てつや]して、レポートを朝[あさ]までに書[か]き（　）。","a":"上げた","opts":["上げた","すぎた","やすかった","にくかった"]}],"src":[],"vf":0,"u":4,"g":1,"gp":"gg_N3_01"},{"id":"g3_006","t":"～かなあ","ko":"~일까, ~려나 (혼잣말)","cat":"문말표현","conn":[{"w":"동사 보통형","f":"晴れる + かなあ"},{"w":"い형용사","f":"辛い + かなあ"},{"w":"な형용사","f":"静か + かなあ"},{"w":"명사","f":"雨 + かなあ"},{"w":"ない형 (바람)","f":"来ない + かなあ"}],"rule":["1. 글자가 바뀌는 활용은 없고, 보통형 문장 끝에 かな를 붙인다(晴れるかな).","2. な형용사와 명사는 だ를 빼고 바로 붙인다(静かかな, 雨かな). 「静かだかな」는 틀린 꼴.","3. 느낌을 길게 끌 때 な를 늘여 かなあ라고 한다.","4. ない형 + かなあ는 '~하면 좋겠다'는 바람을 나타낸다(早く来ないかなあ)."],"why":"의문 조사 か + 감동 조사 な가 합쳐진 종조사이다.","nu":"혼잣말이나 친한 사이의 회화체. 윗사람에게 직접 물을 때는 쓰지 않는다(「～でしょうか」를 씀). 여성은 「かしら」도 쓴다. 「～てもいいかな」처럼 가볍게 허락을 구할 때도 쓴다.","cmp":[{"g":"～だろうか","d":"だろうか는 문어적·딱딱한 자문. かなあ는 가볍고 회화적."}],"ex":[{"jp":"明日[あした]は晴[は]れるかなあ。","ko":"내일은 맑으려나."},{"jp":"このスープ、ちょっと辛[から]いかな。","ko":"이 수프 좀 매운가."},{"jp":"早[はや]く夏休[なつやす]みにならないかなあ。","ko":"빨리 여름방학이 됐으면 좋겠다."}],"dr":[{"t":"make","q":"大丈夫だ → ～かな","a":"大丈夫かな","hint":"な형용사는 だ를 빼고 かな"},{"t":"make","q":"バスが来ない → ～かなあ (바람)","a":"バスが来ないかなあ","hint":"ない형 뒤에 かなあ를 붙이면 바람"},{"t":"fill","q":"早[はや]く週末[しゅうまつ]にならない（　）。","a":"かなあ","opts":["かなあ","ことだ","わけだ","ばかりだ"]}],"src":["https://www.weblio.jp/content/%E3%81%8B%E3%81%AA","https://bunpro.jp/ja/grammar_points/%E3%81%8B%E3%81%AA"],"vf":1,"u":5,"g":1,"gp":"gg_N3_01"},{"id":"g3_016","t":"～ことだ","ko":"~하는 것이 가장 좋다, ~해야 한다 (충고)","cat":"문말표현","conn":[{"w":"동사 사전형","f":"休む + ことだ"},{"w":"동사 ない형","f":"無理しない + ことだ"}],"rule":["1. 동사 사전형 뒤에 ことだ를 붙인다(休む → 休むことだ).","2. '~하지 않는 게 좋다'는 ない형 뒤에 붙인다(無理しない → 無理しないことだ).","3. 동사의 형태 자체는 바뀌지 않고, ことだ 부분만 정중하게 ことです로 바꿀 수 있다."],"why":"","nu":"윗사람이 아랫사람에게 '~하는 게 제일이다'라고 충고・조언할 때 쓰는 말이다. 상대를 가르치는 느낌이 있어 손윗사람에게는 쓰지 않는다. 자기 자신에 대해서는 잘 쓰지 않는다. 형용사에 붙은 残念なことだ 등은 감탄을 나타내는 다른 용법이다.","cmp":[{"g":"～ほうがいい","d":"좀 더 일반적인 권고로 누구에게나 쓸 수 있다. ことだ는 위에서 내리는 충고 느낌이 강하다."}],"ex":[{"jp":"風邪[かぜ]を引[ひ]いたら、ゆっくり休[やす]むことだ。","ko":"감기에 걸리면 푹 쉬는 게 제일이다."},{"jp":"日本語[にほんご]が上手[じょうず]になりたければ、毎日[まいにち]話[はな]すことだ。","ko":"일본어를 잘하고 싶다면 매일 말하는 것이 중요하다."},{"jp":"疲[つか]れているときは、無理[むり]しないことです。","ko":"피곤할 때는 무리하지 않는 게 좋습니다."}],"dr":[{"t":"make","q":"早く寝る → ～ことだ","a":"早く寝ることだ","hint":"동사 사전형 뒤에 ことだ."},{"t":"make","q":"心配しない → ～ことだ","a":"心配しないことだ","hint":"'~하지 않는 게 좋다'는 ない형＋ことだ."},{"t":"fill","q":"試験[しけん]に合格[ごうかく]したいなら、毎日[まいにち]復習[ふくしゅう]する（　）。","a":"ことだ","opts":["ことだ","ながら","までに","しか"]}],"src":["https://bunpro.jp/grammar_points/ことだ","https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201203.html"],"vf":1,"u":5,"g":1,"gp":"gg_N3_01"},{"id":"g3_017","t":"～ことにしている","ko":"~하기로 하고 있다 (자신의 습관・규칙)","cat":"문말표현","conn":[{"w":"동사 사전형","f":"歩く + ことにしている"},{"w":"동사 ない형","f":"食べない + ことにしている"}],"rule":["1. 동사 사전형 뒤에 ことに를 붙인다(歩く → 歩くことに).","2. 그 뒤에 する의 진행형 している를 붙여 '정해서 계속 지키고 있음'을 나타낸다(歩くことにしている).","3. '~하지 않기로 하고 있다'는 ない형을 쓴다(食べないことにしている)."],"why":"ことにする(~하기로 정하다)의 する가 ている형이 된 것으로, 정한 결과를 지금도 계속 지키고 있다는 뜻이다.","nu":"말하는 사람이 스스로 정해서 습관처럼 지키는 일에 쓴다. 남이나 사회가 정한 규칙에는 ことになっている를 쓴다. 한 번 정한 순간을 말할 때는 ことにした(~하기로 했다)를 쓴다.","cmp":[{"g":"～ことになっている","d":"회사・학교・법 등 외부에서 정해진 규칙・예정. ことにしている는 자기가 정한 습관."}],"ex":[{"jp":"毎朝[まいあさ]30分[さんじゅっぷん]歩[ある]くことにしている。","ko":"매일 아침 30분 걷기로 하고 있다."},{"jp":"夜[よる]9時[くじ]以降[いこう]は何[なに]も食[た]べないことにしています。","ko":"밤 9시 이후에는 아무것도 먹지 않기로 하고 있습니다."},{"jp":"寝[ね]る前[まえ]に日記[にっき]を書[か]くことにしている。","ko":"자기 전에 일기를 쓰기로 하고 있다."}],"dr":[{"t":"make","q":"毎日野菜を食べる → ～ことにしている","a":"毎日野菜を食べることにしている","hint":"사전형＋ことに＋している."},{"t":"make","q":"お酒を飲まない → ～ことにしている","a":"お酒を飲まないことにしている","hint":"ない형 뒤에 ことにしている."},{"t":"fill","q":"健康[けんこう]のために、エレベーターは使[つか]わない（　）。","a":"ことにしている","opts":["ことにしている","ながら","までに","しか"]}],"src":["https://laits.utexas.edu/japanese/joshu/grammar/glist/y2/ch1/gl_y2_ch1_deciding.php","https://bunpro.jp/ja/grammar_points/%E3%81%93%E3%81%A8%E3%81%AB%E3%81%99%E3%82%8B"],"vf":1,"u":5,"g":1,"gp":"gg_N3_01"},{"id":"g3_018","t":"～ことになっている","ko":"~하기로 되어 있다 (정해진 규칙・예정)","cat":"문말표현","conn":[{"w":"동사 사전형","f":"脱ぐ + ことになっている"},{"w":"동사 ない형","f":"入らない + ことになっている"}],"rule":["1. 동사 사전형 뒤에 ことに를 붙인다(脱ぐ → 脱ぐことに).","2. 그 뒤에 なる의 ている형 なっている를 붙여 '이미 정해져 있는 상태'를 나타낸다(脱ぐことになっている).","3. 금지 규칙은 ない형을 쓴다(入らないことになっている)."],"why":"ことになる(~하게 되다, 결정되다)의 なる가 ている형이 된 것으로, 정해진 결과가 지금 유지되고 있다는 뜻이다.","nu":"회사・학교・법・관습 등 말하는 사람 이외의 곳에서 정해진 규칙이나 예정을 말할 때 쓴다(明日会議をすることになっている: 내일 회의하기로 되어 있다). 자기가 정한 습관에는 ことにしている를 쓴다.","cmp":[{"g":"～ことにしている","d":"자기 의지로 정한 습관. ことになっている는 남이나 사회가 정한 규칙."}],"ex":[{"jp":"日本[にほん]の家[いえ]では、玄関[げんかん]で靴[くつ]を脱[ぬ]ぐことになっている。","ko":"일본 집에서는 현관에서 신발을 벗기로 되어 있다."},{"jp":"この部屋[へや]には関係者[かんけいしゃ]以外[いがい]入[はい]らないことになっています。","ko":"이 방에는 관계자 외에는 들어가지 않게 되어 있습니다."},{"jp":"明日[あした]の午後[ごご]、社長[しゃちょう]に会[あ]うことになっている。","ko":"내일 오후에 사장님을 만나기로 되어 있다."}],"dr":[{"t":"make","q":"会議は10時に始まる → ～ことになっている","a":"会議は10時に始まることになっている","hint":"사전형＋ことに＋なっている."},{"t":"make","q":"ここでたばこを吸わない → ～ことになっている","a":"ここでたばこを吸わないことになっている","hint":"금지 규칙은 ない형＋ことになっている."},{"t":"fill","q":"この学校[がっこう]では、制服[せいふく]を着[き]る（　）。","a":"ことになっている","opts":["ことになっている","ながら","までに","しか"]}],"src":["https://nihongokyoshi-net.com/2018/11/28/jlptn3-grammar-kotoninatteiru/"],"vf":1,"u":6,"g":1,"gp":"gg_N3_01"},{"id":"g3_042","t":"～っけ","ko":"~였더라?, ~였지?","cat":"문말표현","conn":[{"w":"동사 과거형","f":"置いた + っけ"},{"w":"동사(んだ)","f":"行くんだ + っけ"},{"w":"い형용사 과거형","f":"寒かった + っけ"},{"w":"な형용사","f":"静かだ + っけ"},{"w":"명사","f":"休みだ + っけ"},{"w":"정중체","f":"何時でした + っけ"}],"rule":["1. 떠올리려는 내용을 보통형으로 말하고 끝에 っけ를 붙인다(置いたっけ).","2. 명사·な형용사는 だ를 넣어 だっけ로 한다(休みだっけ).","3. い형용사는 い를 かった로 바꾼 과거형에 붙인다(寒い → 寒かったっけ).","4. 정중하게는 でしたっけ, ましたっけ로 한다."],"why":"","nu":"잊어버린 것을 떠올리려 할 때 혼잣말로, 또는 상대에게 다시 확인할 때 쓰는 회화체. 정중한 자리에서도 でしたっけ 형태는 쓸 수 있다. い형용사 현재형에 바로 붙이지 않는다(寒いっけ ×).","cmp":[{"g":"～かな","d":"'~일까?' 하고 모르는 것을 궁금해함. っけ는 한 번 알았던 것을 잊어서 다시 떠올리는 느낌."}],"ex":[{"jp":"鍵[かぎ]、どこに置[お]いたっけ？","ko":"열쇠를 어디에 뒀더라?"},{"jp":"明日[あした]って休[やす]みだっけ？","ko":"내일 쉬는 날이었나?"},{"jp":"去年[きょねん]の冬[ふゆ]、こんなに寒[さむ]かったっけ？","ko":"작년 겨울이 이렇게 추웠던가?"}],"dr":[{"t":"make","q":"休み → ～っけ","a":"休みだっけ","hint":"명사 + だ + っけ"},{"t":"make","q":"寒い → ～っけ","a":"寒かったっけ","hint":"い → かった, 그 뒤에 っけ"},{"t":"fill","q":"すみません、お名前[なまえ]は何[なん]（　）？","a":"でしたっけ","opts":["でしたっけ","のに","ばかり","ながら"]}],"src":["https://bunpro.jp/grammar_points/308","https://jlptsensei.com/learn-japanese-grammar/っけ-kke-meaning/"],"vf":1,"u":6,"g":1,"gp":"gg_N3_01"},{"id":"g3_046","t":"～つもりでした","ko":"~할 생각이었습니다","cat":"문말표현","conn":[{"w":"동사 사전형","f":"行く + つもりでした"},{"w":"동사 ない형","f":"言わない + つもりでした"},{"w":"보통체","f":"行く + つもりだった"}],"rule":["1. 동사 사전형(또는 ない형) 뒤에 つもり를 붙인다(行くつもり).","2. つもりです의 です를 과거 でした로 바꾼다(行くつもりでした).","3. 보통체는 つもりだった로 한다.","4. 뒤에 が・けど를 붙여 실제로는 그렇게 되지 않았음을 이어 말하는 일이 많다."],"why":"","nu":"과거의 계획·의도를 말하며, 그 계획이 이루어지지 않았을 때 자주 쓴다. 주어는 보통 말하는 사람 자신이다. 남의 의도를 단정하는 데는 쓰기 어렵다. た형 + つもり(勉強したつもり)는 '(실제와 달리) ~했다고 생각함'이라는 다른 용법이다.","cmp":[{"g":"～ようと思っていました","d":"'~하려고 생각하고 있었다'. 비슷하지만 つもりでした가 더 굳은 계획의 느낌."}],"ex":[{"jp":"昨日[きのう]は早[はや]く寝[ね]るつもりでしたが、ゲームをしてしまいました。","ko":"어제는 일찍 잘 생각이었는데 게임을 해 버렸습니다."},{"jp":"このことは誰[だれ]にも言[い]わないつもりでした。","ko":"이 일은 아무에게도 말하지 않을 생각이었습니다."},{"jp":"今日[きょう]は買[か]い物[もの]に行[い]くつもりだったけど、雨[あめ]でやめた。","ko":"오늘은 장 보러 갈 생각이었는데 비 때문에 그만뒀다."}],"dr":[{"t":"make","q":"行く → ～つもりでした","a":"行くつもりでした","hint":"사전형 + つもり + でした"},{"t":"make","q":"言わない → ～つもりでした","a":"言わないつもりでした","hint":"ない형 + つもり + でした"},{"t":"fill","q":"今朝[けさ]は公園[こうえん]を走[はし]る（　）が、雨[あめ]でやめました。","a":"つもりでした","opts":["つもりでした","たびに","ついでに","とたん"]}],"src":["https://www.tofugu.com/japanese-grammar/tsumori/","https://jlptsensei.com/learn-japanese-grammar/つもりだった-tsumori-datta-meaning/"],"vf":1,"u":6,"g":1,"gp":"gg_N3_01"},{"id":"g3_048","t":"～てごらん","ko":"~해 봐","cat":"문말표현","conn":[{"w":"동사 て형","f":"見て + ごらん"},{"w":"1그룹 동사 て형","f":"書いて + ごらん"},{"w":"する","f":"して + ごらん"}],"rule":["1. 동사를 て형으로 바꾼다(見る → 見て, 書く → 書いて).","2. 그 뒤에 ごらん을 붙인다(見てごらん).","3. 조금 더 격식 있게 지시할 때는 ～てごらんなさい로 한다."],"why":"ごらん은 見る의 존경어 ご覧(보심)이며, ～てごらん은 ～てみなさい(~해 보렴)와 같은 뜻으로 쓰인다.","nu":"부모가 아이에게, 선생님이 학생에게처럼 윗사람이 아랫사람에게 부드럽게 권할 때 쓴다. 존경어가 들어 있어도 윗사람에게 쓰면 실례가 되는 점이 한국어 화자가 자주 하는 실수이다. 윗사람에게는 ～てみてください를 쓴다.","cmp":[{"g":"～てみて","d":"'~해 봐'. 친구 사이 등에 두루 쓴다. ～てごらん은 아랫사람에게 다정하게 권하는 느낌."}],"ex":[{"jp":"これ、おいしいよ。食[た]べてごらん。","ko":"이거 맛있어. 먹어 봐."},{"jp":"窓[まど]の外[そと]を見[み]てごらん。雪[ゆき]が降[ふ]っているよ。","ko":"창밖을 봐 봐. 눈이 오고 있어."},{"jp":"もう一度[いちど]、ゆっくり読[よ]んでごらん。","ko":"한 번 더 천천히 읽어 보렴."}],"dr":[{"t":"make","q":"食べる → ～てごらん","a":"食べてごらん","hint":"る를 떼고 て + ごらん"},{"t":"make","q":"書く → ～てごらん","a":"書いてごらん","hint":"く → いて, 그 뒤에 ごらん"},{"t":"fill","q":"お母[かあ]さんが子供[こども]に「自分[じぶん]でやって（　）。」と言[い]った。","a":"ごらん","opts":["ごらん","たびに","ついでに","とたん"]}],"src":["https://bunpro.jp/grammar_points/314","https://jlptsensei.com/learn-japanese-grammar/%E3%81%A6%E3%81%94%E3%82%89%E3%82%93-te-goran-meaning/"],"vf":1,"u":7,"g":1,"gp":"gg_N3_01"},{"id":"g3_051","t":"～てほしい","ko":"(남이) ~해 주었으면 좋겠다","cat":"문말표현","conn":[{"w":"동사 て형","f":"手伝って + ほしい"},{"w":"동사 ない형","f":"行かないで + ほしい"},{"w":"자연 현상·사물","f":"雨がやんで + ほしい"}],"rule":["1. 바라는 행동을 て형으로 바꾼다(手伝う → 手伝って).","2. 그 뒤에 ほしい를 붙인다(手伝ってほしい).","3. 해 주기를 바라는 사람은 に로 나타낸다(友達に手伝ってほしい).","4. 하지 않기를 바랄 때는 ない + で + ほしい(行かないでほしい)."],"why":"","nu":"다른 사람이나 사물이 어떻게 되기를 바랄 때 쓴다. 자기 자신의 행동에는 ～たい를 쓴다. 윗사람에게 직접 쓰면 요구처럼 들리므로 ～ていただきたい, ～てもらえませんか가 무난하다. 사람이 아닌 것(雨など)은 が로 나타낸다.","cmp":[{"g":"～たい","d":"내가 하고 싶은 것(行きたい). ～てほしい는 남이 해 주기를 바라는 것."},{"g":"～てもらいたい","d":"뜻은 거의 같고, 약간 더 정중하게 들린다."}],"ex":[{"jp":"友達[ともだち]に引[ひ]っ越[こ]しを手伝[てつだ]ってほしい。","ko":"친구가 이사를 도와줬으면 좋겠다."},{"jp":"早[はや]く雨[あめ]がやんでほしい。","ko":"빨리 비가 그쳤으면 좋겠다."},{"jp":"このことは誰[だれ]にも言[い]わないでほしい。","ko":"이 일은 아무에게도 말하지 않았으면 해."}],"dr":[{"t":"make","q":"手伝う → ～てほしい","a":"手伝ってほしい","hint":"う → って, 그 뒤에 ほしい"},{"t":"make","q":"行く → ～ないでほしい","a":"行かないでほしい","hint":"ない형 行かない + で + ほしい"},{"t":"fill","q":"母[はは]は子供[こども]（　）野菜[やさい]を食[た]べてほしいと思[おも]っている。","a":"に","opts":["に","を","で","へ"]}],"src":["https://www.tofugu.com/japanese-grammar/tehoshii/"],"vf":1,"u":7,"g":1,"gp":"gg_N3_01"},{"id":"g3_053","t":"～といいなあ","ko":"~하면 좋겠다","cat":"문말표현","conn":[{"w":"동사 사전형","f":"晴れる + といいなあ"},{"w":"동사 ない형","f":"降らない + といいなあ"},{"w":"い형용사","f":"優しい + といいなあ"},{"w":"な형용사","f":"簡単だ + といいなあ"},{"w":"명사","f":"晴れだ + といいなあ"}],"rule":["1. 바라는 내용을 보통형 현재로 말한다(晴れる, 降らない).","2. 명사·な형용사는 だ를 붙인다(簡単だ).","3. 그 뒤에 と + いい + なあ를 붙인다(晴れるといいなあ)."],"why":"조건을 나타내는 と에 いい(좋다), 감탄의 なあ가 붙어 '~하면 좋겠구나'라는 뜻이 된다.","nu":"혼잣말처럼 희망을 말하는 회화체이다. 날씨나 결과처럼 자기 힘으로 정할 수 없는 일에 주로 쓴다. 상대를 위해 바랄 때는 ～といいですね(합격하면 좋겠네요)를 쓴다. 비슷한 표현으로 ～ばいいなあ, ～たらいいなあ도 있다.","cmp":[{"g":"～たい","d":"내가 하고 싶은 행동. ～といいなあ는 어떤 일이 그렇게 되기를 바라는 것."},{"g":"～てほしい","d":"남이나 사물에 대한 바람을 더 직접적으로 말한다."}],"ex":[{"jp":"明日[あした]、晴[は]れるといいなあ。","ko":"내일 맑으면 좋겠다."},{"jp":"試験[しけん]が簡単[かんたん]だといいなあ。","ko":"시험이 쉬우면 좋겠다."},{"jp":"新[あたら]しい先生[せんせい]が優[やさ]しいといいなあ。","ko":"새 선생님이 다정하면 좋겠다."}],"dr":[{"t":"make","q":"晴れる → ～といいなあ","a":"晴れるといいなあ","hint":"사전형 + と + いいなあ"},{"t":"make","q":"元気 → ～といいなあ","a":"元気だといいなあ","hint":"な형용사 + だ + といいなあ"},{"t":"fill","q":"週末[しゅうまつ]は雨[あめ]が降[ふ]らない（　）いいなあ。","a":"と","opts":["と","を","が","で"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%84%E3%81%84","https://www.vnjpclub.com/en/n3-grammar/to-iinaa.html"],"vf":1,"u":7,"g":1,"gp":"gg_N3_01"},{"id":"g3_093","t":"～ばよかった","ko":"~했으면 좋았을 텐데, ~할 걸","cat":"문말표현","conn":[{"w":"동사","f":"行けば + よかった"},{"w":"동사 부정","f":"言わなければ + よかった"},{"w":"い형용사","f":"安ければ + よかった"},{"w":"な형용사·명사","f":"暇であれば + よかった"}],"rule":["1. 1그룹 동사는 어미 う단을 え단으로 바꾸고 ば를 붙인다(行く→行けば). 2그룹은 る→れば(食べれば), する→すれば, 来る→来れば.","2. 그 뒤에 いい의 과거형 よかった를 붙인다(行けばよかった).","3. '~하지 말 걸'은 ない의 い를 ければ로 바꾼다(言わない→言わなければよかった).","4. い형용사는 い를 ければ로(安い→安ければよかった)."],"why":"조건형 ば + いい(좋다)의 과거형 よかった로, '~하면 좋았다'는 말이 실제로는 하지 않은 일에 대한 후회가 된다.","nu":"실제로 일어나지 않은 과거 일에 대한 후회·아쉬움으로, 주로 자신의 일에 쓴다. 상대에게 쓰면 '~했으면 좋았잖아'라는 조언·비난이 되고 のに를 붙이는 경우가 많다(言えばよかったのに). 회화에서는 ～たらよかった도 많이 쓴다.","cmp":[{"g":"～たらよかった","d":"거의 같은 뜻으로 더 회화적."},{"g":"～ばいい","d":"지금·앞으로에 대한 조언 '~하면 된다'. 후회가 아니다."}],"ex":[{"jp":"もっと早[はや]く家[いえ]を出[で]ればよかった。","ko":"더 일찍 집을 나섰으면 좋았을 텐데."},{"jp":"あんなこと、言[い]わなければよかった。","ko":"그런 말 하지 말 걸 그랬다."},{"jp":"もう少[すこ]し安[やす]ければよかったのに。","ko":"조금만 더 쌌으면 좋았을 텐데."}],"dr":[{"t":"make","q":"行く → ～ばよかった","a":"行けばよかった","hint":"く를 け로 바꾸고 ば + よかった"},{"t":"make","q":"買わない → ～ばよかった","a":"買わなければよかった","hint":"ない의 い를 ければ로 + よかった"},{"t":"fill","q":"昨日[きのう]もっと早[はや]く（　）よかった。","a":"寝れば","opts":["寝れば","寝るので","寝るのに","寝ながら"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/ばよかった-ba-yokatta-meaning","https://bunpro.jp/grammar_points/%E3%81%B0%E3%82%88%E3%81%8B%E3%81%A3%E3%81%9F"],"vf":1,"u":8,"g":1,"gp":"gg_N3_01"},{"id":"g3_094","t":"～ふりをする","ko":"~인 척하다","cat":"문말표현","conn":[{"w":"동사 보통형","f":"知らない + ふりをする"},{"w":"동사 ている","f":"寝ている + ふりをする"},{"w":"い형용사","f":"痛い + ふりをする"},{"w":"な형용사","f":"元気な + ふりをする"},{"w":"명사","f":"病気の + ふりをする"}],"rule":["1. 동사는 보통형(사전형·ない형·ている형·た형)을 그대로 쓴다. 예: 寝る→寝ている(る가 て로 바뀌고 いる 추가).","2. い형용사는 그대로, な형용사는 な, 명사는 の를 붙여 명사 수식 형태로 만든다.","3. 그 뒤에 ふりをする를 붙인다(寝ているふりをする)."],"why":"ふり(振り, 겉모습·태도) + を + する로 이루어져 '그런 모습을 하다'가 된다.","nu":"사실과 다른 모습을 일부러 보이는 것. 회화에서는 を를 빼기도 한다(知らないふりする). 지금 척하는 중이면 ふりをしている. 한국어 '척하다'와 달리 명사에는 の가 필요하다.","cmp":[{"g":"～ようだ","d":"겉보기로 하는 추측. 일부러 연기한다는 뜻이 없다."}],"ex":[{"jp":"弟[おとうと]は寝[ね]ているふりをしている。","ko":"남동생은 자는 척하고 있다."},{"jp":"彼女[かのじょ]は私[わたし]を見[み]ても、知[し]らないふりをした。","ko":"그녀는 나를 보고도 모르는 척했다."},{"jp":"彼[かれ]は病気[びょうき]のふりをして学校[がっこう]を休[やす]んだ。","ko":"그는 아픈 척하고 학교를 쉬었다."}],"dr":[{"t":"make","q":"知らない → ～ふりをする","a":"知らないふりをする","hint":"보통형 그대로 + ふりをする"},{"t":"make","q":"病気 → ～ふりをする","a":"病気のふりをする","hint":"명사 + の + ふりをする"},{"t":"fill","q":"母[はは]が来[き]たので、寝[ね]ている（　）をした。","a":"ふり","opts":["ふり","はず","つもり","わけ"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%B5%E3%82%8A%E3%82%92%E3%81%99%E3%82%8B","https://jlptsensei.com/learn-japanese-grammar/%E3%81%B5%E3%82%8A%E3%82%92%E3%81%99%E3%82%8B-furi-o-suru-meaning/"],"vf":1,"u":8,"g":1,"gp":"gg_N3_01"},{"id":"g3_097","t":"～ますように","ko":"~하기를 (빕니다)","cat":"문말표현","conn":[{"w":"동사 ます형","f":"合格し + ますように"},{"w":"가능동사","f":"会え + ますように"},{"w":"부정","f":"降り + ませんように"}],"rule":["1. 동사를 ます형으로 바꾼다(合格する→合格します, 降る→降ります).","2. ます 뒤에 ように를 붙인다(合格しますように).","3. 일어나지 않기를 바랄 때는 ません + ように(雨が降りませんように)."],"why":"","nu":"신사 참배, 생일 카드, 편지 끝 등에서 소원을 빌 때 문장을 끝맺는 표현. 주로 운에 달린 일(합격, 날씨, 건강)에 쓰며, 다른 사람에 대한 소원에도 쓸 수 있다. 앞에 どうか를 붙여 간절함을 더하기도 한다.","cmp":[{"g":"～たい","d":"자기 희망을 말할 뿐 무엇에 비는 기원이 아니다."}],"ex":[{"jp":"試験[しけん]に合格[ごうかく]できますように。","ko":"시험에 합격할 수 있기를."},{"jp":"明日[あした]、雨[あめ]が降[ふ]りませんように。","ko":"내일 비가 오지 않기를."},{"jp":"家族[かぞく]がみんな元気[げんき]でいられますように。","ko":"가족 모두가 건강하게 지낼 수 있기를."}],"dr":[{"t":"make","q":"会える → ～ますように","a":"会えますように","hint":"ます형 + ように"},{"t":"make","q":"忘れる (부정) → ～ませんように","a":"忘れませんように","hint":"ません + ように"},{"t":"fill","q":"新[あたら]しい年[とし]も、いいことがあります（　）。","a":"ように","opts":["ように","ために","そうに","ばかり"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%82%88%E3%81%86%E3%81%AB%E3%81%84%E3%81%AE%E3%82%8B"],"vf":1,"u":8,"g":1,"gp":"gg_N3_02"},{"id":"g3_110","t":"～ようとしない","ko":"~하려고 하지 않는다","cat":"문말표현","conn":[{"w":"동사 의지형(1그룹)","f":"謝る → 謝ろう + としない"},{"w":"동사 의지형(2그룹)","f":"食べる → 食べよう + としない"},{"w":"동사 의지형(する)","f":"勉強する → 勉強しよう + としない"},{"w":"동사 의지형(来る)","f":"来る → 来よう(こよう) + としない"}],"rule":["1. 1그룹 동사는 어미 う단을 お단으로 바꾸고 う를 붙여 의지형을 만든다(謝る → 謝ろう).","2. 2그룹 동사는 る를 よう로 바꾼다(食べる → 食べよう).","3. する는 しよう, 来る는 来よう(こよう)가 된다.","4. 의지형 뒤에 としない를 붙인다. 과거는 としなかった."],"why":"의지형 + と + する(~하려고 하다)의 부정형이다.","nu":"주로 다른 사람이 어떤 일을 할 마음을 전혀 보이지 않는 것을 말하며, 말하는 사람의 불만이 담기기 쉽다. 말하는 사람 자신에게는 잘 쓰지 않는다. 단순히 하지 않는다(しない)가 아니라 '할 생각조차 보이지 않는다'는 뜻이다.","cmp":[{"g":"～ようとする","d":"~하려고 하다. 시도하거나 막 하려는 순간을 나타낸다. ようとしない는 그 부정으로 '할 생각을 보이지 않는다'."}],"ex":[{"jp":"弟[おとうと]は部屋[へや]を片付[かたづ]けようとしない。","ko":"남동생은 방을 치우려고 하지 않는다."},{"jp":"彼[かれ]は自分[じぶん]が悪[わる]いのに謝[あやま]ろうとしない。","ko":"그는 자기가 잘못했는데도 사과하려고 하지 않는다."},{"jp":"息子[むすこ]は全然[ぜんぜん]勉強[べんきょう]しようとしなかった。","ko":"아들은 전혀 공부하려고 하지 않았다."}],"dr":[{"t":"make","q":"聞く → ～ようとしない","a":"聞こうとしない","hint":"く를 こ로 바꾸고 う + としない"},{"t":"make","q":"起きる → ～ようとしない","a":"起きようとしない","hint":"る를 よう로 + としない"},{"t":"fill","q":"熱[ねつ]があるのに、彼[かれ]は病院[びょういん]に行[い]こう（　）。","a":"としない","opts":["としない","ようにしない","ことがない","ばかりだ"]}],"src":[],"vf":0,"u":9,"g":1,"gp":"gg_N3_02"},{"id":"g3_111","t":"～ようと思う","ko":"~하려고 한다, ~할 생각이다","cat":"문말표현","conn":[{"w":"동사 의지형(1그룹)","f":"買う → 買おう + と思う"},{"w":"동사 의지형(2그룹)","f":"寝る → 寝よう + と思う"},{"w":"동사 의지형(する)","f":"旅行する → 旅行しよう + と思う"},{"w":"동사 의지형(来る)","f":"来る → 来よう(こよう) + と思う"}],"rule":["1. 1그룹 동사는 어미 う단을 お단으로 바꾸고 う를 붙인다(買う → 買おう).","2. 2그룹 동사는 る를 よう로 바꾼다(寝る → 寝よう).","3. する는 しよう, 来る는 来よう(こよう)가 된다.","4. 의지형 뒤에 인용의 と와 思う를 붙인다."],"why":"의지형(~해야지) + 인용의 と + 思う(생각하다)로, '~해야지'라고 생각한다는 구성이다.","nu":"말하는 사람 자신의 의지·계획을 나타낸다. ようと思っている는 전부터 계속 품고 있는 생각을 나타내며 다른 사람의 의지를 말할 때도 쓸 수 있다(兄は留学しようと思っている). 정중하게는 ようと思います.","cmp":[{"g":"～つもりだ","d":"이미 마음을 굳힌 의도·계획을 말하는 느낌이 더 강하다."}],"ex":[{"jp":"今日[きょう]は早[はや]く寝[ね]ようと思[おも]います。","ko":"오늘은 일찍 자려고 합니다."},{"jp":"新[あたら]しいカメラを買[か]おうと思[おも]っています。","ko":"새 카메라를 사려고 생각하고 있습니다."},{"jp":"夏休[なつやす]みに日本[にほん]へ旅行[りょこう]しようと思[おも]う。","ko":"여름 방학에 일본으로 여행하려고 한다."}],"dr":[{"t":"make","q":"行く → ～ようと思う","a":"行こうと思う","hint":"く를 こ로 바꾸고 う + と思う"},{"t":"make","q":"見る → ～ようと思う","a":"見ようと思う","hint":"る를 よう로 + と思う"},{"t":"fill","q":"来年[らいねん]、日本[にほん]に留学[りゅうがく]しよう（　）います。","a":"と思って","opts":["と思って","ように","ことに","ために"]}],"src":[],"vf":0,"u":9,"g":1,"gp":"gg_N3_02"},{"id":"g3_115","t":"～ようにしましょう","ko":"~하도록 합시다","cat":"문말표현","conn":[{"w":"동사 사전형","f":"寝る + ようにしましょう"},{"w":"동사 ない형","f":"遅れない + ようにしましょう"},{"w":"동사(する)","f":"運動する + ようにしましょう"}],"rule":["1. 동사를 사전형 또는 ない형으로 만든다(遅れる → 遅れない: る를 빼고 ない).","2. 그 뒤에 ように를 붙인다.","3. 마지막에 する의 권유형 しましょう를 붙인다(寝るようにしましょう)."],"why":"ようにする(~하도록 신경 쓰다·노력하다)에 권유의 ましょう가 붙은 형태다.","nu":"습관이나 주의 사항을 꾸준히 지키도록 함께 노력하자고 권할 때 쓴다. 학교·병원·안내문 등에서 듣는 사람에게 부드럽게 지시하는 말로도 많이 쓴다. 한 번 하고 끝나는 행동보다 계속 신경 써야 하는 일에 어울린다.","cmp":[{"g":"～ましょう","d":"그 행동 자체를 지금 하자는 권유(行きましょう). ようにしましょう는 '그렇게 되도록 평소에 신경 쓰자'는 뜻."}],"ex":[{"jp":"毎日[まいにち]野菜[やさい]を食[た]べるようにしましょう。","ko":"매일 채소를 먹도록 합시다."},{"jp":"授業[じゅぎょう]に遅[おく]れないようにしましょう。","ko":"수업에 늦지 않도록 합시다."},{"jp":"一日[いちにち]三十分[さんじゅっぷん]は運動[うんどう]するようにしましょう。","ko":"하루 30분은 운동하도록 합시다."}],"dr":[{"t":"make","q":"早く寝る → ～ようにしましょう","a":"早く寝るようにしましょう","hint":"사전형 + ように + しましょう"},{"t":"make","q":"忘れる → 부정 + ようにしましょう","a":"忘れないようにしましょう","hint":"る를 빼고 ない + ようにしましょう"},{"t":"fill","q":"健康[けんこう]のために、皆[みな]さん、夜[よる]は甘[あま]いものを食[た]べない（　）。","a":"ようにしましょう","opts":["ようにしましょう","ばかりです","ところです","ままです"]}],"src":[],"vf":0,"u":9,"g":1,"gp":"gg_N3_02"},{"id":"g3_116","t":"～ようになった","ko":"~하게 되었다, ~할 수 있게 되었다","cat":"문말표현","conn":[{"w":"동사 사전형","f":"散歩する + ようになった"},{"w":"동사 가능형","f":"泳げる + ようになった"},{"w":"동사 ない형","f":"食べない + ようになった"}],"rule":["1. 바뀐 뒤의 상태를 동사 사전형 또는 가능형으로 만든다(泳ぐ → 泳げる: 어미 ぐ를 げ로 바꾸고 る).","2. 그 뒤에 ように를 붙인다.","3. なる의 과거형 なった를 붙인다(泳げるようになった)."],"why":"ように(~하는 상태로) + なる(되다)의 과거형이다.","nu":"습관·능력·상황이 시간을 두고 바뀐 것을 말한다. 명사·형용사의 변화에는 쓰지 않고 になった·くなった를 쓴다(きれいになった, 寒くなった). 부정의 변화는 ～なくなった가 더 자연스러운 경우가 많다(食べなくなった). 결정을 나타내는 ことになった와 혼동하지 않도록 주의.","cmp":[{"g":"～ことになった","d":"어떤 일이 결정되었다는 뜻(転勤することになった). ようになった는 능력·습관·상태의 변화."}],"ex":[{"jp":"練習[れんしゅう]して、やっと泳[およ]げるようになった。","ko":"연습해서 드디어 헤엄칠 수 있게 되었다."},{"jp":"最近[さいきん]、父[ちち]は毎朝[まいあさ]散歩[さんぽ]するようになった。","ko":"요즘 아버지는 매일 아침 산책하게 되었다."},{"jp":"日本[にほん]に来[き]てから、納豆[なっとう]を食[た]べるようになった。","ko":"일본에 오고 나서 낫토를 먹게 되었다."}],"dr":[{"t":"make","q":"話す → 가능형 + ようになった","a":"話せるようになった","hint":"す를 せ로 바꾸고 る + ようになった"},{"t":"make","q":"読む → 가능형 + ようになった","a":"読めるようになった","hint":"む를 め로 바꾸고 る + ようになった"},{"t":"fill","q":"毎日[まいにち]練習[れんしゅう]して、ピアノが弾[ひ]ける（　）。","a":"ようになった","opts":["ようになった","ことにした","ようとしない","ばかりだ"]}],"src":[],"vf":0,"u":10,"g":1,"gp":"gg_N3_02"},{"id":"g3_015","t":"～こと","ko":"~하는 것, ~함 (명사화)","cat":"명사화·수식","conn":[{"w":"동사 보통형","f":"話す + こと / 行った + こと"},{"w":"い형용사","f":"若い + こと"},{"w":"な형용사","f":"大切な + こと"}],"rule":["1. 동사는 보통형(사전형・た형・ない형) 그대로 こと를 붙여 명사로 만든다(話す → 話すこと).","2. 만든 명사 뒤에는 が・は・を 같은 조사를 이어 쓴다(話すことが好きだ).","3. い형용사는 그대로, な형용사는 な를 넣어 붙인다(若いこと, 大切なこと)."],"why":"","nu":"동작・상태를 '~하는 것'이라는 명사로 만든다. ことができる(~할 수 있다), たことがある(~한 적이 있다) 같은 표현의 바탕이 된다. 같은 명사화의 の와 달리 見る・聞く 같은 지각 동사 앞에는 こと를 쓰지 않는다(×歌うことを聞いた → 歌うのを聞いた). 반대로 '~이다' 문장의 서술부(趣味は読むことです)에는 こと를 쓴다.","cmp":[{"g":"～の","d":"회화에서 많이 쓰는 명사화. 지각 동사(見る・聞こえる) 앞에서는 の만 쓰고, ～ことです로 끝나는 정의・설명에는 こと를 쓴다."}],"ex":[{"jp":"私[わたし]は人[ひと]と話[はな]すことが好[す]きです。","ko":"저는 사람들과 이야기하는 것을 좋아합니다."},{"jp":"毎日[まいにち]運動[うんどう]することは体[からだ]にいい。","ko":"매일 운동하는 것은 몸에 좋다."},{"jp":"私[わたし]の趣味[しゅみ]は写真[しゃしん]を撮[と]ることです。","ko":"제 취미는 사진을 찍는 것입니다."}],"dr":[{"t":"make","q":"泳ぐ / 好きです → ～こと","a":"泳ぐことが好きです","hint":"사전형 뒤에 こと, 그 뒤에 が."},{"t":"make","q":"日本語を話す / できます → ～こと","a":"日本語を話すことができます","hint":"동사 사전형＋こと＋ができる."},{"t":"fill","q":"私[わたし]の夢[ゆめ]は世界中[せかいじゅう]を旅行[りょこう]する（　）です。","a":"こと","opts":["こと","ため","よう","まま"]}],"src":["https://www.bunpro.jp/grammar_points/98"],"vf":1,"u":10,"g":1,"gp":"gg_N3_02"},{"id":"g3_021","t":"～さ","ko":"~함, ~의 정도(형용사의 명사화)","cat":"명사화·수식","conn":[{"w":"い형용사","f":"高い → 高さ"},{"w":"い형용사","f":"重い → 重さ"},{"w":"な형용사","f":"便利 → 便利さ"},{"w":"いい(불규칙)","f":"いい → よい → よさ"}],"rule":["1. い형용사는 끝의 い를 뗀다(高い → 高).","2. 남은 어간에 さ를 붙여 명사로 만든다(高さ).","3. な형용사는 어간에 바로 さ를 붙인다(便利さ, 大切さ).","4. いい는 よい로 바꾼 뒤 よさ가 된다."],"why":"형용사 어간에 정도·성질을 나타내는 명사화 접미사 さ가 붙은 꼴이다.","nu":"성질의 정도·크기를 객관적으로 나타낸다(高さ 높이, 重さ 무게, 長さ 길이). 한국어로는 '높이', '무게', '소중함'처럼 자연스러운 명사로 옮긴다. 「高さはどのくらいですか」처럼 측정할 때 자주 쓴다.","cmp":[{"g":"～み","d":"甘み·痛み·楽しみ처럼 일부 형용사에만 붙고, 수치보다 느낌·성질 자체를 나타낸다. さ는 대부분의 형용사에 붙는다."}],"ex":[{"jp":"この山[やま]の高[たか]さは三千[さんぜん]メートルぐらいです。","ko":"이 산의 높이는 3000미터 정도입니다."},{"jp":"一人[ひとり]で暮[く]らして、家族[かぞく]の大切[たいせつ]さがわかった。","ko":"혼자 살아 보고 가족의 소중함을 알았다."},{"jp":"このかばんのよさは軽[かる]いところです。","ko":"이 가방의 장점은 가벼운 점입니다."}],"dr":[{"t":"make","q":"重い → ～さ","a":"重さ","hint":"い를 떼고 さ"},{"t":"make","q":"便利 → ～さ","a":"便利さ","hint":"な형용사 어간 + さ"},{"t":"fill","q":"箱[はこ]の（　）を量[はか]ってください。","a":"重さ","opts":["重さ","重い","重く","重かった"]}],"src":["https://mlcjapanese.co.jp/n3_01_04.html"],"vf":1,"u":10,"g":1,"gp":"gg_N3_02"},{"id":"g3_034","t":"～たて","ko":"갓 ~한, 막 ~한","cat":"명사화·수식","conn":[{"w":"1그룹 동사 ます형","f":"焼く → 焼き + たて"},{"w":"1그룹 동사 ます형","f":"作る → 作り + たて"},{"w":"2그룹 동사 ます형","f":"生まれる → 生まれ + たて"},{"w":"できる","f":"できる → でき + たて"}],"rule":["1. 1그룹 동사는 어미 う단을 い단으로 바꿔 ます형 어간을 만든다(焼く → 焼き).","2. 2그룹 동사는 る를 뗀다(生まれる → 生まれ).","3. 그 뒤에 たて를 붙인다(焼きたて).","4. 명사 앞에서는 の를 넣는다(焼きたてのパン). 문장 끝은 ～たてだ."],"why":"","nu":"방금 만들어져 신선하다는 느낌으로, 쓰이는 동사가 한정되어 있다(焼く·作る·できる·炊く·揚げる·洗う·塗る·生まれる 등). 아무 동사에나 붙이지 않는다. 한국어 '갓 ~한'에 가깝다.","cmp":[{"g":"～たばかり","d":"대부분의 동사에 쓰는 '막 ~했다'. たて는 정해진 동사에만 붙고 신선함을 강조한다."}],"ex":[{"jp":"焼[や]きたてのパンはおいしい。","ko":"갓 구운 빵은 맛있다."},{"jp":"できたてのラーメンを食[た]べた。","ko":"갓 만든 라멘을 먹었다."},{"jp":"このシャツは洗[あら]いたてだ。","ko":"이 셔츠는 막 빤 것이다."}],"dr":[{"t":"make","q":"作る → ～たて","a":"作りたて","hint":"る를 り(い단)로 바꾸고 たて"},{"t":"make","q":"炊く → ～たて","a":"炊きたて","hint":"く를 き(い단)로 바꾸고 たて"},{"t":"fill","q":"揚[あ]げ（　）の天[てん]ぷらは本当[ほんとう]においしい。","a":"たて","opts":["たて","ながら","すぎ","がち"]}],"src":["https://nihongokyoshi-net.com/2019/05/20/jlptn2-grammar-tate/","https://bunpro.jp/grammar_points/%E3%81%9F%E3%81%A6"],"vf":1,"u":11,"g":1,"gp":"gg_N3_02"},{"id":"g3_054","t":"～という","ko":"~라는","cat":"명사화·수식","conn":[{"w":"명사(이름) + 명사","f":"ポチ + という + 犬"},{"w":"보통형 문장 + 명사","f":"結婚する + という + 話"},{"w":"의문사 + 명사","f":"何 + という + 花"}],"rule":["1. 이름이나 내용을 먼저 말한다(ポチ / 山田さんが結婚する).","2. 그 뒤에 という를 붙인다.","3. 끝에 그것이 가리키는 명사를 놓는다(ポチという犬, 結婚するという話)."],"why":"인용 조사 と에 言う(말하다)가 붙어 '~라고 하는 (명사)'라는 뜻이 된다.","nu":"상대가 잘 모를 수 있는 이름을 소개하거나, 話・うわさ・ニュース 같은 명사의 내용을 나타낼 때 쓴다. 회화에서는 っていう로 줄여 말하는 일이 많다(ポチっていう犬). 글로 쓸 때는 という를 히라가나로 쓰는 것이 보통이다.","cmp":[{"g":"～の","d":"'~의'. 소유·소속을 나타낼 뿐, 이름이나 내용을 소개하는 뜻은 없다."}],"ex":[{"jp":"「さくら」という店[みせ]を知[し]っていますか。","ko":"'사쿠라'라는 가게를 아세요?"},{"jp":"山田[やまだ]さんが結婚[けっこん]するという話[はなし]を聞[き]いた。","ko":"야마다 씨가 결혼한다는 이야기를 들었다."},{"jp":"これは何[なん]という花[はな]ですか。","ko":"이건 뭐라는 꽃인가요?"}],"dr":[{"t":"make","q":"さくら・店 → ～という","a":"さくらという店","hint":"이름 + という + 명사"},{"t":"make","q":"何・料理 → ～という","a":"何という料理","hint":"의문사 + という + 명사"},{"t":"fill","q":"うちでは「ポチ」（　）犬[いぬ]を飼[か]っています。","a":"という","opts":["という","として","について","によって"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%84%E3%81%86-called"],"vf":1,"u":11,"g":1,"gp":"gg_N3_02"},{"id":"g3_057","t":"～というの","ko":"~라는 것, ~라는 건","cat":"명사화·수식","conn":[{"w":"동사 보통형","f":"休む + というの"},{"w":"い형용사","f":"高い + というの"},{"w":"な형용사","f":"大変だ + というの"},{"w":"명사","f":"林さん + というの"}],"rule":["1. 앞말(문장)은 보통형 그대로 둔다(休む).","2. 그 뒤에 という(~라는)를 붙인다.","3. 이어서 형식명사 の(것)를 붙여 하나의 명사처럼 만든다.","4. 그 뒤에 조사(は・が・を 등)를 붙여 문장 속에서 쓴다."],"why":"という(~라는) + の(것). 앞의 내용을 '~라는 것'으로 묶어 명사처럼 쓰는 형태다.","nu":"회화체. 들은 말·소문·이름 같은 내용을 '~라는 것/사람'으로 묶어 주어나 목적어로 쓴다. 문어체나 격식 있는 글에서는 ということ를 쓰는 편이 자연스럽다. 명사 뒤에 붙으면 '~라는 사람/것'이 된다(林さんというのは…).","cmp":[{"g":"～ということ","d":"뜻은 비슷하지만 더 딱딱하고 글에 잘 쓴다."},{"g":"～の(명사화)","d":"行くの처럼 동작 자체를 명사로 만든다. というの는 '~라는 (말·내용)'으로 인용의 느낌이 들어간다."}],"ex":[{"jp":"田中[たなか]さんが明日[あした]休[やす]むというのを聞[き]いた。","ko":"다나카 씨가 내일 쉰다는 걸 들었다."},{"jp":"来週[らいしゅう]テストがあるというのを忘[わす]れていた。","ko":"다음 주에 시험이 있다는 걸 잊고 있었다."},{"jp":"林[はやし]さんというのは、どの人[ひと]ですか。","ko":"하야시 씨라는 분은 어느 분이에요?"}],"dr":[{"t":"make","q":"彼が休む → ～というのを聞いた","a":"彼が休むというのを聞いた","hint":"보통형 + という + の + を"},{"t":"make","q":"店が閉まる → ～というのを知らなかった","a":"店が閉まるというのを知らなかった","hint":"보통형 + というの + を"},{"t":"fill","q":"会議[かいぎ]が中止[ちゅうし]になった（　）を、さっき知[し]った。","a":"というの","opts":["というの","というより","といっても","として"]}],"src":[],"vf":0,"u":11,"g":1,"gp":"gg_N3_02"},{"id":"g3_058","t":"～というのは","ko":"~(이)란, ~라는 것은","cat":"명사화·수식","conn":[{"w":"명사","f":"駅弁 + というのは"},{"w":"동사 보통형","f":"一人で暮らす + というのは"},{"w":"い형용사","f":"忙しい + というのは"}],"rule":["1. 설명하고 싶은 말(명사·문장)을 그대로 둔다(駅弁).","2. 그 뒤에 というのは를 붙여 주제로 만든다.","3. 뒤에서 그 뜻을 설명한다. 정의는 보통 ～のことだ／～ということだ로 끝맺는다."],"why":"という(~라는) + の(것) + は(주제 조사).","nu":"말의 뜻을 정의하거나 어떤 일이 어떤 것인지 설명할 때 쓴다. 회화에서는 って로 줄여 말하기도 한다(駅弁って何？). 문장 첫머리에 단독으로 쓴 「というのは、～からだ」는 '왜냐하면'의 뜻으로 앞 문장의 이유를 말한다.","cmp":[{"g":"～とは","d":"뜻은 같지만 더 딱딱한 문어체. 사전·설명문에 잘 쓴다."},{"g":"～というと","d":"정의가 아니라 그 말에서 떠오르는 것을 말한다."}],"ex":[{"jp":"駅弁[えきべん]というのは、駅[えき]で売[う]っている弁当[べんとう]のことです。","ko":"에키벤이란 역에서 파는 도시락을 말합니다."},{"jp":"一人[ひとり]で暮[く]らすというのは、思[おも]ったより大変[たいへん]だ。","ko":"혼자 산다는 것은 생각보다 힘들다."},{"jp":"「アルバイト」というのは、ドイツ語[ご]から来[き]た言葉[ことば]です。","ko":"'아르바이트'라는 말은 독일어에서 온 말입니다."}],"dr":[{"t":"make","q":"コンビニ → ～というのは (뜻을 설명하는 문장 앞부분)","a":"コンビニというのは","hint":"명사 + というのは"},{"t":"make","q":"毎日運動する → ～というのは難しい","a":"毎日運動するというのは難しい","hint":"보통형 + というのは"},{"t":"fill","q":"「花見[はなみ]」（　）、桜[さくら]の花[はな]を見[み]て楽[たの]しむことです。","a":"というのは","opts":["というのは","というより","といっても","としたら"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%84%E3%81%86%E3%81%AE%E3%81%AF"],"vf":1,"u":12,"g":1,"gp":"gg_N3_02"},{"id":"g3_027","t":"～せてください","ko":"~하게 해 주세요(제가 ~하겠습니다)","cat":"수수·사역·수동","conn":[{"w":"1그룹 동사","f":"休む → 休ませる → 休ませてください"},{"w":"2그룹 동사","f":"考える → 考えさせてください"},{"w":"する","f":"説明する → 説明させてください"},{"w":"来る","f":"来る → 来させてください(こさせて)"}],"rule":["1. 사역형을 만든다: 1그룹은 어미 う단을 あ단으로 바꾸고 せる(休む → 休ませる).","2. 2그룹은 る를 떼고 させる(考えさせる). する → させる, 来る → 来させる(こさせる).","3. 끝의 る를 て로 바꿔 て형을 만든다(休ませて).","4. ください를 붙인다(休ませてください)."],"why":"사역형(~하게 하다)의 て형 + ください로 '나에게 ~하게 해 달라', 곧 자신의 행동을 허락해 달라는 뜻이 된다.","nu":"내가 하고 싶은 일을 정중하게 허락받거나 자청할 때 쓴다. 더 정중하게는 ～させていただけませんか. 1그룹에 さ를 넣는 休まさせて는 틀린 형태. 見せてください는 見せる(보여 주다)라는 별개 동사로 사역이 아니다.","cmp":[{"g":"～てください","d":"상대에게 행동을 부탁. ～せてください는 내 행동을 허락해 달라는 부탁."}],"ex":[{"jp":"熱[ねつ]があるので、今日[きょう]は休[やす]ませてください。","ko":"열이 있어서 오늘은 쉬게 해 주세요."},{"jp":"その件[けん]は少[すこ]し考[かんが]えさせてください。","ko":"그 건은 조금 생각하게 해 주세요."},{"jp":"私[わたし]にも説明[せつめい]させてください。","ko":"저도 설명하게 해 주세요."}],"dr":[{"t":"make","q":"帰る → ～せてください","a":"帰らせてください","hint":"帰る는 1그룹: る를 ら로 + せてください"},{"t":"make","q":"考える → ～せてください","a":"考えさせてください","hint":"2그룹은 る를 떼고 させてください"},{"t":"fill","q":"私[わたし]にも一度[いちど]やら（　）。","a":"せてください","opts":["せてください","てください","ずに","たい"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/%E3%81%95%E3%81%9B%E3%81%A6%E3%81%8F%E3%81%A0%E3%81%95%E3%81%84-sasete-kudasai-meaning/","https://cotoacademy.com/sasete-kusasai-jlpt-grammar-explanation-meaning-example/"],"vf":1,"u":12,"g":1,"gp":"gg_N3_02"},{"id":"g3_047","t":"～てくれと","ko":"~해 달라고 (말하다·부탁하다)","cat":"수수·사역·수동","conn":[{"w":"동사 て형","f":"待って + くれと言われた"},{"w":"동사 ないで형","f":"言わないで + くれと頼まれた"}],"rule":["1. 부탁받은 행동을 て형으로 바꾼다(待つ → 待って).","2. 뒤에 くれ와 인용 조사 と를 붙인다(待ってくれと).","3. 끝에 言う・頼む 같은 동사를 놓는다(待ってくれと言われた).","4. 하지 말라는 부탁은 ないで + くれと로 한다."],"why":"くれ는 くれる의 명령형이고 と는 인용 조사이다. 남이 한 '～てくれ(~해 줘)'라는 말을 인용하는 형태이다.","nu":"남이 나(또는 우리 쪽)에게 한 부탁·지시를 전할 때 쓴다. 보통 ～と言われた, ～と頼まれた처럼 수동형과 함께 쓴다. 회화체이며, 정중하게 전할 때는 ～てほしいと言われました, ～ように言われました를 쓰기도 한다.","cmp":[{"g":"～ように言われた","d":"지시 내용을 간접적으로 전한다(早く帰るように言われた). てくれと는 상대가 한 말을 더 직접 옮긴 느낌."}],"ex":[{"jp":"母[はは]に早[はや]く帰[かえ]ってくれと言[い]われた。","ko":"엄마가 빨리 돌아와 달라고 했다."},{"jp":"友達[ともだち]に引[ひ]っ越[こ]しを手伝[てつだ]ってくれと頼[たの]まれた。","ko":"친구가 이사를 도와 달라고 부탁했다."},{"jp":"このことは誰[だれ]にも言[い]わないでくれと言[い]われた。","ko":"이 일은 아무에게도 말하지 말아 달라는 말을 들었다."}],"dr":[{"t":"make","q":"待つ → ～てくれと言われた","a":"待ってくれと言われた","hint":"つ → って, 그 뒤에 くれと言われた"},{"t":"make","q":"運ぶ → ～てくれと頼まれた","a":"運んでくれと頼まれた","hint":"ぶ → んで, 그 뒤에 くれと頼まれた"},{"t":"fill","q":"父[ちち]に車[くるま]を洗[あら]って（　）と頼[たの]まれた。","a":"くれ","opts":["くれ","あげ","もらい","おき"]}],"src":[],"vf":0,"u":12,"g":1,"gp":"gg_N3_03"},{"id":"g3_119","t":"～られた (수동 과거)","ko":"~당했다, ~받았다, ~되었다","cat":"수수·사역·수동","conn":[{"w":"1그룹 동사","f":"盗む → 盗まれた"},{"w":"1그룹 동사(う로 끝남)","f":"言う → 言われた"},{"w":"2그룹 동사","f":"褒める → 褒められた"},{"w":"する","f":"注意する → 注意された"},{"w":"来る","f":"来る → 来られた(こられた)"}],"rule":["1. 1그룹 동사는 어미 う단을 あ단으로 바꾸고 れた를 붙인다(盗む → 盗まれた). う로 끝나면 わ로 바꾼다(言う → 言われた).","2. 2그룹 동사는 る를 빼고 られた를 붙인다(褒める → 褒められた).","3. する는 された, 来る는 来られた(こられた)가 된다."],"why":"","nu":"행위를 한 사람은 に로 나타낸다(先生に褒められた). 사람을 주어로 해서 피해를 입었다는 느낌을 주는 수동이 많다(財布を盗まれた, 雨に降られた). 2그룹 동사의 られた는 가능형 과거와 모양이 같으므로 문맥으로 구별한다. 한국어로 '~되었다'로 옮겨지는 말이라도 일본어에서는 수동을 쓰지 않는 경우가 있으니 주의.","cmp":[{"g":"～させられた","d":"사역수동. 하기 싫은 일을 억지로 하게 되었다는 뜻."}],"ex":[{"jp":"電車[でんしゃ]で財布[さいふ]を盗[ぬす]まれた。","ko":"전철에서 지갑을 도둑맞았다."},{"jp":"テストで百点[ひゃくてん]を取[と]って、先生[せんせい]に褒[ほ]められた。","ko":"시험에서 100점을 받아서 선생님께 칭찬받았다."},{"jp":"授業中[じゅぎょうちゅう]に寝[ね]ていて、先生[せんせい]に注意[ちゅうい]された。","ko":"수업 중에 자다가 선생님께 주의를 받았다."}],"dr":[{"t":"make","q":"叱る → 수동 과거","a":"叱られた","hint":"1그룹: る를 ら로 바꾸고 れた"},{"t":"make","q":"見る → 수동 과거","a":"見られた","hint":"2그룹: る를 빼고 られた"},{"t":"fill","q":"楽[たの]しみにしていたのに、弟[おとうと]にケーキを（　）。","a":"食べられた","opts":["食べられた","食べた","食べよう","食べたい"]}],"src":[],"vf":0,"u":13,"g":1,"gp":"gg_N3_03"},{"id":"g3_020","t":"～ことはない","ko":"~할 필요는 없다","cat":"가능·의무·허가","conn":[{"w":"동사 사전형","f":"急ぐ → 急ぐことはない"},{"w":"する 동사","f":"心配する → 心配することはない"},{"w":"来る","f":"来る(くる) → 来ることはない"}],"rule":["1. 동사를 사전형 그대로 쓴다(활용하지 않음).","2. 뒤에 こと를 붙여 명사처럼 만든다(急ぐこと).","3. は + ない를 붙인다 → 急ぐことはない.","4. 정중하게는 ことはありません."],"why":"こと(일) + は + ない(없다)로 '~할 일은 없다', 곧 '~할 필요가 없다'가 된다.","nu":"상대를 안심시키거나 '그렇게까지 할 것 없다'고 조언할 때 쓴다. わざわざ·何も와 자주 함께 온다. 문맥에 따라 '~하는 일은 (결코) 없다'라는 뜻도 있다(彼が約束を破ることはない). 앞에는 ない형이 아닌 사전형이 온다.","cmp":[{"g":"～なくてもいい","d":"'안 해도 된다'는 허용. ことはない는 '할 필요 없다'며 상대의 걱정·행동을 말리는 느낌이 더 강하다."}],"ex":[{"jp":"まだ時間[じかん]があるから、急[いそ]ぐことはないよ。","ko":"아직 시간이 있으니까 서두를 필요 없어."},{"jp":"小[ちい]さいけがだから、心配[しんぱい]することはありません。","ko":"작은 상처니까 걱정하실 필요 없습니다."},{"jp":"わざわざ駅[えき]まで迎[むか]えに来[く]ることはないよ。","ko":"일부러 역까지 마중 나올 필요는 없어."}],"dr":[{"t":"make","q":"謝る → ～ことはない","a":"謝ることはない","hint":"사전형 + ことはない"},{"t":"make","q":"心配する → ～ことはない","a":"心配することはない","hint":"する도 사전형 그대로 + ことはない"},{"t":"fill","q":"電話[でんわ]で済[す]むから、わざわざ行[い]く（　）。","a":"ことはない","opts":["ことはない","しかない","べきだ","ことにした"]}],"src":["https://nihongokyoshi-net.com/2019/01/15/jlptn3-grammar-kotowanai/"],"vf":1,"u":13,"g":1,"gp":"gg_N3_03"},{"id":"g3_023","t":"～しかない","ko":"~할 수밖에 없다","cat":"가능·의무·허가","conn":[{"w":"동사 사전형","f":"歩く → 歩くしかない"},{"w":"する 동사","f":"我慢する → 我慢するしかない"},{"w":"명사(수량)","f":"千円 → 千円しかない"}],"rule":["1. 동사를 사전형 그대로 쓴다.","2. 뒤에 しか(~밖에)를 붙인다(歩くしか).","3. 그 뒤에 ない를 붙인다 → 歩くしかない.","4. 정중하게는 しかありません."],"why":"しか(~밖에) + ない(없다)로 '~하는 것밖에 없다', 곧 다른 방법이 없다는 뜻이 된다.","nu":"다른 선택지가 없어서 체념하거나 각오할 때 쓴다. 명사·수량 뒤에 오면 '~밖에 없다'(千円しかない)는 한정의 뜻이다. 동사를 ない형으로 바꾸는 실수(歩かないしかない)에 주의.","cmp":[{"g":"～ほかない","d":"뜻은 같지만 더 딱딱하고 문어적이다."}],"ex":[{"jp":"終電[しゅうでん]が出[で]てしまったから、歩[ある]いて帰[かえ]るしかない。","ko":"막차가 떠나 버렸으니 걸어서 돌아갈 수밖에 없다."},{"jp":"誰[だれ]も手伝[てつだ]ってくれないなら、自分[じぶん]でやるしかない。","ko":"아무도 도와주지 않는다면 내가 할 수밖에 없다."},{"jp":"財布[さいふ]に千円[せんえん]しかない。","ko":"지갑에 천 엔밖에 없다."}],"dr":[{"t":"make","q":"待つ → ～しかない","a":"待つしかない","hint":"사전형 + しかない"},{"t":"make","q":"諦める → ～しかない","a":"諦めるしかない","hint":"사전형 그대로 + しかない"},{"t":"fill","q":"バスがないので、タクシーで行[い]く（　）。","a":"しかない","opts":["しかない","ことはない","はずがない","つもりはない"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%97%E3%81%8B%E3%81%AA%E3%81%84"],"vf":1,"u":13,"g":1,"gp":"gg_N3_03"},{"id":"g3_071","t":"～ないと","ko":"~하지 않으면, ~해야 해","cat":"가능·의무·허가","conn":[{"w":"동사 ない형","f":"急がない + と"},{"w":"い형용사","f":"安くない + と"},{"w":"な형용사·명사","f":"元気じゃない + と / 学生でない + と"},{"w":"する・来る","f":"しない + と / 来ない + と"}],"rule":["1. 1그룹 동사는 어미 う단을 あ단으로 바꾸고 ない를 붙인다(急ぐ → 急がない).","2. 그 뒤에 조건의 と를 붙인다(急がないと).","3. 뒤에 좋지 않은 결과를 말하거나(遅れる), 문장을 ないと로 끝내 '~해야 해'라는 뜻으로 쓴다."],"why":"ない(부정) + と(조건 조사). 문장 끝의 ないと는 ないといけない의 いけない가 생략된 형태다.","nu":"두 가지로 쓴다. (1) 조건: '~하지 않으면 (곤란한 결과가 생긴다)'. (2) 문말: 친한 사이의 회화에서 '~해야 해'(もう帰らないと). (2)는 회화체이므로 글이나 윗사람에게는 ないといけません·なければなりません을 쓴다.","cmp":[{"g":"～なければ","d":"조건 '~하지 않으면'. 뒤에 なりません·いけません을 이어 의무를 나타낸다. 문말에서 생략해 なきゃ로도 쓴다."},{"g":"～ないといけない","d":"의무를 다 갖춰 말한 형태. ないと만 쓰면 회화적이다."}],"ex":[{"jp":"急[いそ]がないと、電車[でんしゃ]に遅[おく]れるよ。","ko":"서두르지 않으면 전철 놓친다."},{"jp":"もう十時[じゅうじ]だ。そろそろ帰[かえ]らないと。","ko":"벌써 10시다. 슬슬 돌아가야겠다."},{"jp":"体[からだ]が元気[げんき]じゃないと、仕事[しごと]も楽[たの]しくない。","ko":"몸이 건강하지 않으면 일도 즐겁지 않다."}],"dr":[{"t":"make","q":"急ぐ → ～ないと","a":"急がないと","hint":"ぐ → が + ない + と"},{"t":"make","q":"勉強する → ～ないと","a":"勉強しないと","hint":"する → しない + と"},{"t":"fill","q":"早[はや]く寝[ね]（　）、明日[あした]起[お]きられないよ。","a":"ないと","opts":["ないと","ないで","なくても","ながら"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AA%E3%81%84%E3%81%A8"],"vf":1,"u":14,"g":1,"gp":"gg_N3_03"},{"id":"g3_095","t":"～べきだ","ko":"(마땅히) ~해야 한다","cat":"가능·의무·허가","conn":[{"w":"동사 사전형","f":"謝る + べきだ"},{"w":"する","f":"する + べきだ / す + べきだ"},{"w":"い형용사","f":"優しく + あるべきだ"},{"w":"な형용사·명사","f":"公平で + あるべきだ"}],"rule":["1. 동사 사전형에 그대로 べきだ를 붙인다(謝る→謝るべきだ).","2. する는 するべきだ 외에 すべきだ도 쓴다.","3. '~해서는 안 된다'는 べきではない로 말하고, ない형에 べき를 붙이지 않는다.","4. 명사를 꾸밀 때는 べき + 명사(読むべき本)."],"why":"고어 조동사 べし의 연체형 べき에 だ가 붙은 형태다.","nu":"말하는 사람의 판단으로 '그렇게 하는 것이 옳다'고 할 때 쓴다. 규칙·법에 따른 의무에는 なければならない가 자연스럽다. 윗사람에게 직접 쓰면 강하게 들린다. 과거 べきだった는 '~했어야 했다'.","cmp":[{"g":"～なければならない","d":"규칙·필요에 의한 의무."},{"g":"～ほうがいい","d":"부드러운 조언."}],"ex":[{"jp":"悪[わる]いことをしたら、すぐ謝[あやま]るべきだ。","ko":"나쁜 짓을 했으면 바로 사과해야 한다."},{"jp":"もっと早[はや]く連絡[れんらく]すべきだった。","ko":"더 빨리 연락했어야 했다."},{"jp":"人[ひと]の悪口[わるくち]は言[い]うべきではない。","ko":"남의 험담은 해서는 안 된다."}],"dr":[{"t":"make","q":"守る → ～べきだ","a":"守るべきだ","hint":"사전형 + べきだ"},{"t":"make","q":"言う (부정) → ～べきではない","a":"言うべきではない","hint":"사전형 + べきではない"},{"t":"fill","q":"学生[がくせい]はもっと勉強[べんきょう]す（　）だ。","a":"べき","opts":["べき","ため","つもり","はず"]}],"src":["https://www.guidetojapanese.org/should.html","https://ja.wiktionary.org/wiki/%E3%81%B9%E3%81%97"],"vf":1,"u":14,"g":1,"gp":"gg_N3_03"},{"id":"g3_124","t":"～わけにはいかない","ko":"~할 수는 없다","cat":"가능·의무·허가","conn":[{"w":"동사 사전형","f":"休む + わけにはいかない"},{"w":"동사 ない형","f":"行かない + わけにはいかない"}],"rule":["1. 동사 사전형 뒤에 わけにはいかない를 붙이면 '사정상 ~할 수는 없다'(休むわけにはいかない).","2. 동사 ない형 뒤에 붙이면 '~하지 않을 수는 없다', 곧 '해야 한다'(行かないわけにはいかない).","3. 정중하게는 わけにはいきません."],"why":"","nu":"능력이 없어서가 아니라 사회적·도덕적·심리적 사정 때문에 할 수 없다는 뜻이다. 능력상 불가능은 가능형 부정(できない, 読めない)을 쓴다.","cmp":[{"g":"～できない","d":"능력·상황상 불가능. わけにはいかない는 할 수는 있지만 사정상 해서는 안 된다는 뜻."}],"ex":[{"jp":"明日[あした]は大事[だいじ]な会議[かいぎ]があるから、休[やす]むわけにはいかない。","ko":"내일은 중요한 회의가 있어서 쉴 수는 없다."},{"jp":"車[くるま]で来[き]たので、お酒[さけ]を飲[の]むわけにはいかない。","ko":"차로 왔기 때문에 술을 마실 수는 없다."},{"jp":"先生[せんせい]に頼[たの]まれたので、行[い]かないわけにはいかない。","ko":"선생님께 부탁받았기 때문에 안 갈 수는 없다."}],"dr":[{"t":"make","q":"休む → ～わけにはいかない","a":"休むわけにはいかない","hint":"사전형 그대로 + わけにはいかない"},{"t":"make","q":"手伝う(부정) → ～わけにはいかない","a":"手伝わないわけにはいかない","hint":"う를 わ로 바꾸고 ない + わけにはいかない"},{"t":"fill","q":"約束[やくそく]したから、今[いま]さらやめる（　）。","a":"わけにはいかない","opts":["わけにはいかない","ようになった","ばかりだ","わけだ"]}],"src":[],"vf":0,"u":14,"g":1,"gp":"gg_N3_03"},{"id":"g3_129","t":"～切れない","ko":"다 ~할 수 없다","cat":"가능·의무·허가","conn":[{"w":"1그룹 동사 ます형","f":"読み + 切れない"},{"w":"2그룹 동사 ます형","f":"食べ + 切れない"},{"w":"2그룹 동사 ます형","f":"数え + 切れない"}],"rule":["1. 1그룹 동사는 어미 う단을 い단으로 바꿔 ます형을 만든다(読む → 読み).","2. 2그룹 동사는 る를 떼어 ます형을 만든다(食べる → 食べ).","3. ます형 뒤에 切れない를 붙인다(食べ切れない). 가능을 말할 때는 切れる(食べ切れる)."],"why":"","nu":"양이 너무 많거나 시간이 모자라서 끝까지 다 하지 못한다는 뜻이다. 히라가나로 きれない라고 쓰는 경우도 많다. 数え切れないほど(셀 수 없을 만큼), 待ちきれない(너무 기다려져서 못 참겠다)처럼 굳어진 표현도 자주 쓴다.","cmp":[{"g":"～られない (가능 부정)","d":"食べられない는 그 음식을 먹을 수 없다는 뜻(못 먹는 음식 등)이고, 食べ切れない는 먹을 수는 있지만 양이 많아 다 먹지 못한다는 뜻이다."}],"ex":[{"jp":"こんなにたくさん、一人[ひとり]では食[た]べ切[き]れない。","ko":"이렇게 많이는 혼자서 다 못 먹어."},{"jp":"この本[ほん]は厚[あつ]くて、一週間[いっしゅうかん]では読[よ]み切[き]れない。","ko":"이 책은 두꺼워서 일주일로는 다 못 읽는다."},{"jp":"夜空[よぞら]には数[かぞ]え切[き]れないほど星[ほし]があった。","ko":"밤하늘에는 셀 수 없을 만큼 별이 있었다."}],"dr":[{"t":"make","q":"食べる → ～切れない","a":"食べ切れない","hint":"る를 뗀 ます형 + 切れない"},{"t":"make","q":"読む → ～切れない","a":"読み切れない","hint":"む를 み로 바꾼 ます형 + 切れない"},{"t":"fill","q":"料理[りょうり]が多[おお]すぎて、全部[ぜんぶ]は食[た]べ（　）。","a":"切れない","opts":["切れない","やすい","ながら","たがる"]}],"src":[],"vf":0,"u":15,"g":1,"gp":"gg_N3_03"},{"id":"g3_002","t":"～うちに","ko":"~동안에, ~하기 전에","cat":"시간·순서","conn":[{"w":"동사 사전형·ている형","f":"降っている + うちに"},{"w":"동사 ない형","f":"暗くならない + うちに"},{"w":"い형용사","f":"熱い + うちに"},{"w":"な형용사","f":"元気な + うちに"},{"w":"명사","f":"学生の + うちに"}],"rule":["1. 글자가 바뀌는 활용은 없고, 수식형(명사를 꾸미는 꼴) 뒤에 うちに를 붙인다.","2. い형용사는 그대로(熱い), な형용사는 な를 넣고(元気な), 명사는 の를 넣는다(学生の).","3. 동사는 상태를 나타내는 ている형이나 ない형에 자주 붙는다(降らないうちに).","4. 뒤에는 그 상태가 끝나기 전에 해 두는 일이 온다."],"why":"うち(内, 안쪽·범위 안) + に로, '그 상태가 이어지는 범위 안에'라는 뜻이다.","nu":"'상태가 바뀌면 곤란하니 그 전에'라는 말하는 사람의 마음이 담긴다. 「～ないうちに」는 '~해 버리기 전에'로, 피하고 싶은 일이 일어나기 전을 말한다. 또 '~하는 사이에 (어느새)' 변화가 일어났다는 용법도 있다(話しているうちに眠くなった). 같은 시간 범위만 중립적으로 말할 때는 「～間に」를 쓴다.","cmp":[{"g":"～間に","d":"間に는 정해진 기간을 중립적으로 말한다. うちに는 상태가 변하기 전에라는 걱정·의도가 들어간다."},{"g":"～前に","d":"前に는 단순한 시간 순서. ないうちに는 '그렇게 되면 곤란하니 그 전에'라는 마음이 있다."}],"ex":[{"jp":"料理[りょうり]が熱[あつ]いうちに食[た]べましょう。","ko":"요리가 뜨거울 때 먹읍시다."},{"jp":"暗[くら]くならないうちに家[いえ]に帰[かえ]ろう。","ko":"어두워지기 전에 집에 가자."},{"jp":"元気[げんき]なうちに、いろいろな国[くに]へ行[い]きたい。","ko":"건강할 때 여러 나라에 가고 싶다."}],"dr":[{"t":"make","q":"若い → ～うちに","a":"若いうちに","hint":"い형용사는 그대로 うちに를 붙인다"},{"t":"make","q":"雨が降らない → ～うちに","a":"雨が降らないうちに","hint":"ない형 뒤에 うちに를 붙인다"},{"t":"fill","q":"忘[わす]れない（　）、メモしておこう。","a":"うちに","opts":["うちに","くせに","ばかりに","おかげで"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201609.html"],"vf":1,"u":15,"g":1,"gp":"gg_N3_03"},{"id":"g3_008","t":"～から～にかけて","ko":"~부터 ~에 걸쳐","cat":"시간·순서","conn":[{"w":"명사(시간)","f":"夜 + から + 朝 + にかけて"},{"w":"명사(장소)","f":"関東 + から + 東北 + にかけて"}],"rule":["1. 글자가 바뀌는 활용은 없고, 명사1 + から + 명사2 + にかけて의 틀에 시간·장소 명사를 넣는다.","2. 명사1은 범위의 시작, 명사2는 범위의 끝이다(夜から朝にかけて).","3. から를 빼고 「명사 + にかけて」만으로도 쓴다(週末にかけて)."],"why":"に + かける(걸치다)의 て형으로, '~에 걸쳐서'라는 뜻이다.","nu":"경계가 정확하지 않은 대략적인 범위를 말한다. 그 범위 안에서 계속되거나 여기저기 일어나는 일에 쓰며, 한 번만 일어난 일에는 쓰지 않는다. 일기예보·뉴스에서 자주 쓴다. 시작과 끝이 분명할 때는 「～から～まで」.","cmp":[{"g":"～から～まで","d":"まで는 시작·끝이 분명한 범위(9時から5時まで). にかけて는 대략적인 범위."}],"ex":[{"jp":"今夜[こんや]から明日[あした]の朝[あさ]にかけて、雨[あめ]が降[ふ]るでしょう。","ko":"오늘 밤부터 내일 아침에 걸쳐 비가 오겠습니다."},{"jp":"この花[はな]は三月[さんがつ]から四月[しがつ]にかけて咲[さ]きます。","ko":"이 꽃은 3월부터 4월에 걸쳐 핍니다."},{"jp":"九州[きゅうしゅう]から四国[しこく]にかけて、強[つよ]い風[かぜ]が吹[ふ]いている。","ko":"규슈에서 시코쿠에 걸쳐 강한 바람이 불고 있다."}],"dr":[{"t":"make","q":"夏 / 秋 → ～から～にかけて","a":"夏から秋にかけて","hint":"시작 명사 + から + 끝 명사 + にかけて"},{"t":"make","q":"東京 / 大阪 → ～から～にかけて","a":"東京から大阪にかけて","hint":"장소 명사도 같은 틀"},{"t":"fill","q":"昼[ひる]から夕方[ゆうがた]に（　）、雪[ゆき]が降[ふ]り続[つづ]いた。","a":"かけて","opts":["かけて","ついて","とって","よって"]}],"src":["https://nihongokyoshi-net.com/2018/04/22/jlptn3-grammar-kara-nikakete/"],"vf":1,"u":15,"g":1,"gp":"gg_N3_03"},{"id":"g3_036","t":"～たところ","ko":"~했더니, ~해 보니","cat":"시간·순서","conn":[{"w":"1그룹 동사","f":"聞く → 聞いた → 聞いたところ"},{"w":"行く(예외)","f":"行く → 行った → 行ったところ"},{"w":"2그룹 동사","f":"調べる → 調べた → 調べたところ"},{"w":"する","f":"電話する → 電話したところ"}],"rule":["1. 동사를 た형으로 바꾼다: 1그룹 く는 いた(聞く → 聞いた), 단 行く는 예외로 行った.","2. 2그룹은 る를 た로(調べる → 調べた), する는 した.","3. た형 뒤에 ところ를 붙인다(行ったところ).","4. 뒤에 그 결과 알게 된 사실을 과거형으로 쓴다(休みだった)."],"why":"","nu":"'~해 보았더니 (그 결과) …였다'. 뒤 문장은 화자의 의지와 관계없는 결과·발견이고 보통 과거형이다. 다소 딱딱한 말로, 회화에서는 ～たら를 많이 쓴다. 「～たところだ」(막 ~한 참이다)와 혼동하지 않도록 주의.","cmp":[{"g":"～たら","d":"같은 '발견'의 뜻을 회화적으로 나타낸다(行ったら休みだった)."},{"g":"～たところだ","d":"문장 끝에서 '막 ~했다'는 시점을 나타낸다."}],"ex":[{"jp":"店[みせ]に行[い]ったところ、休[やす]みだった。","ko":"가게에 갔더니 쉬는 날이었다."},{"jp":"先生[せんせい]に聞[き]いたところ、すぐに教[おし]えてくれた。","ko":"선생님께 여쭈었더니 바로 가르쳐 주셨다."},{"jp":"調[しら]べたところ、原因[げんいん]がわかった。","ko":"조사해 보니 원인을 알게 되었다."}],"dr":[{"t":"make","q":"電話する → ～たところ","a":"電話したところ","hint":"する → した + ところ"},{"t":"make","q":"読む → ～たところ","a":"読んだところ","hint":"む는 んだ로 바꾸고 ところ"},{"t":"fill","q":"駅[えき]に着[つ]いた（　）、電車[でんしゃ]はもう出[で]ていた。","a":"ところ","opts":["ところ","まま","ため","ほど"]}],"src":[],"vf":0,"u":15,"g":1,"gp":"gg_N3_03"},{"id":"g3_037","t":"～たとたん","ko":"~하자마자, ~한 순간","cat":"시간·순서","conn":[{"w":"동사 た형","f":"開けた + とたん"},{"w":"동사 た형(1그룹)","f":"着いた + とたん"},{"w":"동사 た형(する·来る)","f":"来た + とたん"}],"rule":["1. 동사를 た형으로 바꾼다(開ける → 開けた, 着く → 着いた).","2. た형 뒤에 とたん(또는 とたんに)을 붙인다.","3. 뒤 문장에는 그 순간 바로 일어난 뜻밖의 일을 쓴다."],"why":"とたん은 한자로 途端(바로 그 순간)이라는 명사이고, に가 붙어 '그 순간에'라는 뜻이 된다.","nu":"이미 일어난 일을 묘사할 때 주로 쓰며, 뒤 문장은 말하는 사람이 예상하지 못한 변화가 온다. 뒤에 의지·희망·명령(～しよう, ～たい, ～てください)은 쓸 수 없다. 사전형에 붙이는 실수(開けるとたん)에 주의.","cmp":[{"g":"～てすぐ","d":"단순히 '~하고 바로'. 뒤에 자기 의지 행동도 올 수 있다(帰ってすぐ寝よう). とたん은 뜻밖의 일에만."}],"ex":[{"jp":"窓[まど]を開[あ]けたとたん、強[つよ]い風[かぜ]が入[はい]ってきた。","ko":"창문을 연 순간 강한 바람이 들어왔다."},{"jp":"家[いえ]に着[つ]いたとたん、雨[あめ]が降[ふ]り出[だ]した。","ko":"집에 도착하자마자 비가 내리기 시작했다."},{"jp":"電車[でんしゃ]を降[お]りたとたん、忘[わす]れ物[もの]に気[き]づいた。","ko":"전철에서 내린 순간 물건을 두고 내린 걸 알아차렸다."}],"dr":[{"t":"make","q":"開ける → ～たとたん","a":"開けたとたん","hint":"2그룹: る를 떼고 た + とたん"},{"t":"make","q":"飲む → ～たとたん","a":"飲んだとたん","hint":"1그룹 む → んだ, 그 뒤에 とたん"},{"t":"fill","q":"ドアを開[あ]けた（　）、猫[ねこ]が飛[と]び出[だ]した。","a":"とたん","opts":["とたん","ついでに","ながら","つもりで"]}],"src":["https://bunpro.jp/grammar_points/313","https://jlptsensei.com/learn-japanese-grammar/たとたん-ta-totan-meaning"],"vf":1,"u":16,"g":1,"gp":"gg_N3_03"},{"id":"g3_038","t":"～たびに","ko":"~할 때마다","cat":"시간·순서","conn":[{"w":"동사 사전형","f":"会う + たびに"},{"w":"명사","f":"旅行の + たびに"}],"rule":["1. 동사는 사전형 그대로 たびに를 붙인다(会う → 会うたびに).","2. 명사는 の를 넣고 たびに를 붙인다(旅行 → 旅行のたびに).","3. 뒤 문장에는 그때마다 매번 일어나는 일을 쓴다."],"why":"たび는 한자로 度(때, 번)이고, に가 붙어 '그때마다'라는 뜻이 된다.","nu":"여러 번 되풀이되는 일에 쓴다. 한 번뿐인 일에는 쓰지 않는다. 회화와 글 모두 쓴다. 동사 た형에 붙이는 실수(会ったたびに)에 주의.","cmp":[{"g":"～ごとに","d":"'~마다'. 3日ごとに처럼 일정한 간격도 나타낸다. たびに는 그 일이 일어날 때마다."}],"ex":[{"jp":"この写真[しゃしん]を見[み]るたびに、子供[こども]の頃[ころ]を思[おも]い出[だ]す。","ko":"이 사진을 볼 때마다 어린 시절이 생각난다."},{"jp":"祖母[そぼ]は会[あ]うたびに、お菓子[かし]をくれる。","ko":"할머니는 만날 때마다 과자를 주신다."},{"jp":"父[ちち]は出張[しゅっちょう]のたびに、お土産[みやげ]を買[か]ってくる。","ko":"아버지는 출장 갈 때마다 선물을 사 오신다."}],"dr":[{"t":"make","q":"会う → ～たびに","a":"会うたびに","hint":"사전형 그대로 + たびに"},{"t":"make","q":"旅行 → ～たびに","a":"旅行のたびに","hint":"명사 + の + たびに"},{"t":"fill","q":"あの子[こ]は会[あ]う（　）、背[せ]が高[たか]くなっている。","a":"たびに","opts":["たびに","とたん","ついでに","くせに"]}],"src":["https://nihongokyoshi-net.com/2018/04/04/jlptn3-grammar-tabini/","https://jlptsensei.com/learn-japanese-grammar/たびに-tabi-ni-meaning"],"vf":1,"u":16,"g":1,"gp":"gg_N3_04"},{"id":"g3_041","t":"～ついでに","ko":"~하는 김에","cat":"시간·순서","conn":[{"w":"동사 사전형","f":"行く + ついでに"},{"w":"동사 た형","f":"来た + ついでに"},{"w":"명사","f":"買い物の + ついでに"}],"rule":["1. 동사는 사전형이나 た형에 그대로 ついでに를 붙인다(行くついでに, 来たついでに).","2. 명사는 の를 넣고 ついでに를 붙인다(買い物のついでに).","3. 앞에는 원래 하려던 일, 뒤에는 그 기회에 덧붙여 하는 일을 쓴다."],"why":"","nu":"앞뒤 행동의 주어가 같고, 뒤에는 의지로 하는 행동이 온다. ついでに만 문장 앞에 따로 써서 '하는 김에'(ついでに、これもお願い)라고도 한다. 회화와 글 모두 쓴다.","cmp":[{"g":"～ながら","d":"두 동작을 동시에 하는 것(音楽を聞きながら勉強する). ついでに는 한 일을 하는 기회에 다른 일을 덤으로 하는 것."}],"ex":[{"jp":"コンビニに行[い]くついでに、この手紙[てがみ]を出[だ]してくれる？","ko":"편의점 가는 김에 이 편지 좀 부쳐 줄래?"},{"jp":"駅[えき]まで来[き]たついでに、本屋[ほんや]に寄[よ]った。","ko":"역까지 온 김에 서점에 들렀다."},{"jp":"散歩[さんぽ]のついでに、パンを買[か]ってきた。","ko":"산책하는 김에 빵을 사 왔다."}],"dr":[{"t":"make","q":"行く → ～ついでに","a":"行くついでに","hint":"사전형 그대로 + ついでに"},{"t":"make","q":"買い物 → ～ついでに","a":"買い物のついでに","hint":"명사 + の + ついでに"},{"t":"fill","q":"郵便局[ゆうびんきょく]へ行[い]く（　）、銀行[ぎんこう]にも寄[よ]った。","a":"ついでに","opts":["ついでに","とたん","くせに","たびに"]}],"src":[],"vf":0,"u":16,"g":1,"gp":"gg_N3_04"},{"id":"g3_050","t":"～てはじめて","ko":"~하고 나서야 비로소","cat":"시간·순서","conn":[{"w":"동사 て형","f":"住んで + はじめて"},{"w":"동사 て형(2그룹)","f":"別れて + はじめて"},{"w":"동사 て형(なる)","f":"病気になって + はじめて"}],"rule":["1. 동사를 て형으로 바꾼다(住む → 住んで).","2. 그 뒤에 はじめて를 붙인다(住んではじめて).","3. 뒤 문장에는 그 일을 겪은 뒤에야 알게 된 것·할 수 있게 된 것을 쓴다(分かった, 気づいた)."],"why":"て형에 初めて(처음으로)가 붙은 형태로, '~하고서 처음으로'라는 뜻이다.","nu":"어떤 경험을 한 뒤에야 깨닫거나 실현된 일을 말한다. 뒤에는 分かる, 気づく, 知る 같은 말이 자주 오며, 말하는 사람의 의지·명령은 오지 않는다. 회화와 글 모두 쓴다.","cmp":[{"g":"～てから","d":"단순히 '~하고 나서'라는 순서. てはじめて는 '그 전에는 몰랐다'는 깨달음이 담긴다."}],"ex":[{"jp":"病気[びょうき]になってはじめて、健康[けんこう]の大切[たいせつ]さが分[わ]かった。","ko":"병에 걸리고 나서야 비로소 건강의 소중함을 알았다."},{"jp":"一人[ひとり]で暮[く]らしてはじめて、母[はは]の苦労[くろう]を知[し]った。","ko":"혼자 살아 보고 나서야 엄마의 고생을 알았다."},{"jp":"実際[じっさい]に使[つか]ってみてはじめて、その良[よ]さに気[き]づいた。","ko":"실제로 써 보고 나서야 그 장점을 깨달았다."}],"dr":[{"t":"make","q":"住む → ～てはじめて","a":"住んではじめて","hint":"む → んで, 그 뒤에 はじめて"},{"t":"make","q":"失う → ～てはじめて","a":"失ってはじめて","hint":"う → って, 그 뒤에 はじめて"},{"t":"fill","q":"外国[がいこく]に住[す]んで（　）、自分[じぶん]の国[くに]のことがよく分[わ]かった。","a":"はじめて","opts":["はじめて","ほしい","ごらん","しまう"]}],"src":["https://nihongokyoshi-net.com/2018/07/26/jlptn3-grammar-tehajimete/","https://bunpro.jp/ja/grammar_points/%E3%81%A6%E5%88%9D%E3%82%81%E3%81%A6"],"vf":1,"u":17,"g":1,"gp":"gg_N3_04"},{"id":"g3_064","t":"～ところだった","ko":"(하마터면) ~할 뻔했다","cat":"시간·순서","conn":[{"w":"동사 사전형","f":"遅れる + ところだった"},{"w":"동사 ない형","f":"間に合わない + ところだった"}],"rule":["1. 동사는 사전형 그대로 둔다(遅れる).","2. 그 뒤에 ところ를 붙인다.","3. ところ 뒤에 だ의 과거형 だった를 붙인다(遅れるところだった).","4. 앞에 もう少しで·危うく를 자주 함께 쓴다."],"why":"ところ(그 시점·국면) + だった(だ의 과거).","nu":"나쁜 일이 일어나기 직전까지 갔지만 실제로는 일어나지 않았을 때 쓴다. 회화와 글 모두에 쓴다. 과거의 상황에 대해서만 쓰며, 실제로 일어난 일에는 쓰지 않는다. ～ているところだった는 '~하고 있던 참이었다'로 뜻이 다르다.","cmp":[{"g":"～そうになった","d":"동사 ます형 + そうになった도 '~할 뻔했다'. 몸의 움직임처럼 자연스럽게 일어날 뻔한 일에 잘 쓴다(転びそうになった)."}],"ex":[{"jp":"もう少[すこ]しで電車[でんしゃ]に遅[おく]れるところだった。","ko":"하마터면 전철을 놓칠 뻔했다."},{"jp":"危[あぶ]なかった。車[くるま]にぶつかるところだった。","ko":"위험했다. 차에 부딪힐 뻔했다."},{"jp":"君[きみ]が教[おし]えてくれなかったら、間[ま]に合[あ]わないところだった。","ko":"네가 알려 주지 않았으면 제시간에 못 맞출 뻔했다."}],"dr":[{"t":"make","q":"忘れる → ～ところだった","a":"忘れるところだった","hint":"사전형 + ところだった"},{"t":"make","q":"落ちる → もう少しで ～ところだった","a":"もう少しで落ちるところだった","hint":"もう少しで + 사전형 + ところだった"},{"t":"fill","q":"アラームが鳴[な]らなかったら、寝坊[ねぼう]する（　）。","a":"ところだった","opts":["ところだった","ことだった","はずだった","ばかりだった"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%93%E3%82%8D%E3%81%A0%E3%81%A3%E3%81%9F1"],"vf":1,"u":17,"g":1,"gp":"gg_N3_04"},{"id":"g3_131","t":"～最中に","ko":"한창 ~하는 중에","cat":"시간·순서","conn":[{"w":"동사 ている형","f":"食べている + 最中に"},{"w":"명사","f":"会議の + 最中に"}],"rule":["1. 동사를 て형으로 바꾸고 いる를 붙여 진행형을 만든다(食べる → 食べている).","2. 진행형 뒤에 最中に를 붙인다(食べている最中に).","3. 명사는 の를 넣고 最中に를 붙인다(会議 → 会議の最中に)."],"why":"","nu":"어떤 일이 한창 진행되고 있는 바로 그때 다른 일이 갑자기 일어났다는 뜻으로, 뒤에는 방해가 되는 뜻밖의 일이 오는 경우가 많다. 最中に 뒤에는 일회성 사건이 오며, 계속되는 상태(~하고 있었다)는 잘 오지 않는다. 문장 끝에 '今、勉強している最中だ(지금 한창 공부하는 중이다)'처럼 最中だ로도 쓴다.","cmp":[{"g":"～ている間に","d":"間に는 그 시간 범위 안의 어느 때라는 중립적인 뜻이다. 最中に는 동작이 한창 진행 중인 바로 그때를 강조하며 방해의 느낌이 있다."}],"ex":[{"jp":"食事[しょくじ]をしている最中[さいちゅう]に、電話[でんわ]が鳴[な]った。","ko":"한창 식사하는 중에 전화가 울렸다."},{"jp":"会議[かいぎ]の最中[さいちゅう]に、地震[じしん]があった。","ko":"한창 회의 중에 지진이 있었다."},{"jp":"シャワーを浴[あ]びている最中[さいちゅう]に、電気[でんき]が消[き]えた。","ko":"한창 샤워하는 중에 전기가 나갔다."}],"dr":[{"t":"make","q":"食べる → ～最中に","a":"食べている最中に","hint":"て형 + いる + 最中に"},{"t":"make","q":"会議 → ～最中に","a":"会議の最中に","hint":"명사 + の + 最中に"},{"t":"fill","q":"授業[じゅぎょう]の（　）、急[きゅう]に停電[ていでん]した。","a":"最中に","opts":["最中に","ために","かわりに","くせに"]}],"src":[],"vf":0,"u":17,"g":1,"gp":"gg_N3_04"},{"id":"g3_004","t":"～おかげで","ko":"~덕분에","cat":"원인·이유","conn":[{"w":"동사 보통형","f":"手伝ってくれた + おかげで"},{"w":"い형용사","f":"涼しい + おかげで"},{"w":"な형용사","f":"丈夫な + おかげで"},{"w":"명사","f":"先生の + おかげで"}],"rule":["1. 글자가 바뀌는 활용은 없고, 명사를 꾸미는 꼴 뒤에 おかげで를 붙인다.","2. 명사는 の를 넣고(先生のおかげで), な형용사는 な를 넣는다(丈夫なおかげで).","3. 동사·い형용사는 보통형 그대로 붙인다(手伝ってくれたおかげで).","4. 뒤에는 좋은 결과가 온다."],"why":"お(존경 접두어) + 陰(かげ, 그늘)에서 나온 말로, 남의 보살핌·도움을 뜻하는 おかげ에 で가 붙은 것이다.","nu":"좋은 결과의 원인을 감사하는 마음으로 말한다. 나쁜 결과에는 「～せいで」를 쓴다. 나쁜 결과에 일부러 おかげで를 쓰면 비꼬는 말이 된다(君のおかげで遅刻したよ). な형용사에 だ를 넣어 だおかげで로 쓰는 것은 틀린 꼴.","cmp":[{"g":"～せいで","d":"せいで는 나쁜 결과의 원인(탓)을 말한다. おかげで는 좋은 결과."},{"g":"～ため（に）","d":"ために는 좋고 나쁨과 관계없이 원인을 객관적으로 말하는 딱딱한 표현."}],"ex":[{"jp":"先生[せんせい]のおかげで、試験[しけん]に合格[ごうかく]しました。","ko":"선생님 덕분에 시험에 합격했습니다."},{"jp":"友達[ともだち]が手伝[てつだ]ってくれたおかげで、早[はや]く終[お]わった。","ko":"친구가 도와준 덕분에 빨리 끝났다."},{"jp":"体[からだ]が丈夫[じょうぶ]なおかげで、毎日[まいにち]元気[げんき]に働[はたら]ける。","ko":"몸이 튼튼한 덕분에 매일 건강하게 일할 수 있다."}],"dr":[{"t":"make","q":"母 → ～おかげで","a":"母のおかげで","hint":"명사 뒤에는 の를 넣는다"},{"t":"make","q":"薬を飲んだ → ～おかげで","a":"薬を飲んだおかげで","hint":"동사 보통형 그대로 붙인다"},{"t":"fill","q":"みんなが応援[おうえん]してくれた（　）、優勝[ゆうしょう]できました。","a":"おかげで","opts":["おかげで","せいで","くせに","わりに"]}],"src":["https://www.mlcjapanese.co.jp/n3_04_08.html","https://bunpro.jp/grammar_points/238"],"vf":1,"u":18,"g":1,"gp":"gg_N3_04"},{"id":"g3_026","t":"～せいで","ko":"~탓에, ~때문에(나쁜 결과)","cat":"원인·이유","conn":[{"w":"명사","f":"雨 → 雨のせいで"},{"w":"동사 보통형","f":"寝坊した → 寝坊したせいで"},{"w":"い형용사","f":"暑い → 暑いせいで"},{"w":"な형용사","f":"下手な → 下手なせいで"}],"rule":["1. 명사는 の를 넣고 せいで를 붙인다(雨のせいで).","2. な형용사는 な를 넣는다(下手なせいで).","3. 동사·い형용사는 보통형 그대로 붙인다(寝坊したせいで).","4. 뒤에는 나쁜 결과가 온다(試合が中止になった)."],"why":"せい(所為, 탓) + で(원인)로 '~의 탓으로'라는 뜻이다.","nu":"원인에 책임을 돌리는 느낌이 있어 나쁜 결과에만 쓴다. 좋은 결과에는 ～おかげで를 쓴다. 문장 끝에서는 ～せいだ(~탓이다).","cmp":[{"g":"～おかげで","d":"좋은 결과의 원인에 감사하는 표현. せいで는 나쁜 결과."}],"ex":[{"jp":"雨[あめ]のせいで、試合[しあい]が中止[ちゅうし]になった。","ko":"비 때문에 시합이 취소되었다."},{"jp":"寝坊[ねぼう]したせいで、電車[でんしゃ]に乗[の]り遅[おく]れた。","ko":"늦잠을 잔 탓에 전철을 놓쳤다."},{"jp":"部屋[へや]が暑[あつ]いせいで、よく眠[ねむ]れなかった。","ko":"방이 더운 탓에 잘 자지 못했다."}],"dr":[{"t":"make","q":"風邪 → ～せいで","a":"風邪のせいで","hint":"명사 + の + せいで"},{"t":"make","q":"暑い → ～せいで","a":"暑いせいで","hint":"い형용사는 그대로 + せいで"},{"t":"fill","q":"事故[じこ]の（　）、道[みち]がとても混[こ]んでいる。","a":"せいで","opts":["せいで","おかげで","ように","くせに"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/せいで-sei-de-meaning/","https://www.mlcjapanese.co.jp/n3_04_08.html"],"vf":1,"u":18,"g":1,"gp":"gg_N3_04"},{"id":"g3_039","t":"～だもん（～だもの）","ko":"~인걸, ~니까 뭐","cat":"원인·이유","conn":[{"w":"동사 보통형","f":"知らない + もん"},{"w":"い형용사","f":"寒い + もん"},{"w":"な형용사","f":"好きだ + もん"},{"w":"명사","f":"子供だ + もん"},{"w":"んだ 형태","f":"疲れたんだ + もん"}],"rule":["1. 문장을 보통형으로 끝낸다.","2. 명사·な형용사는 だ를 붙인다(子供 → 子供だ).","3. 맨 끝에 もの를 붙이고, 회화에서는 흔히 もん으로 줄인다(子供だもん).","4. 앞에 ん을 넣은 ～んだもん(疲れたんだもん)도 자주 쓴다."],"why":"","nu":"아주 친한 사이의 회화체로, 자기 행동을 변명하거나 정당화할 때 문장 끝에 쓴다. だって와 함께 쓰는 일이 많다. 어린아이 말투나 응석 부리는 느낌이 있어 윗사람이나 공식적인 자리에서는 쓰지 않는다.","cmp":[{"g":"～ものだから","d":"문장 중간에서 이유를 대고 뒤 문장으로 이어진다. 정중체(ものですから)로도 쓴다. ～もん은 문장 끝 회화체."},{"g":"～から","d":"중립적인 이유 표현. もん처럼 변명하는 응석 섞인 느낌은 없다."}],"ex":[{"jp":"だって、まだ子供[こども]だもん。","ko":"그치만 아직 어린애인걸."},{"jp":"外[そと]に出[で]たくない。寒[さむ]いもん。","ko":"밖에 나가기 싫어. 춥단 말이야."},{"jp":"もう歩[ある]けないよ。疲[つか]れたんだもん。","ko":"더는 못 걷겠어. 지쳤는걸."}],"dr":[{"t":"make","q":"子供 → ～もん","a":"子供だもん","hint":"명사는 だ를 붙이고 もん"},{"t":"make","q":"眠い → ～もん","a":"眠いもん","hint":"い형용사는 그대로 + もん"},{"t":"fill","q":"宿題[しゅくだい]してないの？だって、時間[じかん]がなかった（　）。","a":"もん","opts":["もん","たびに","とたん","ついでに"]}],"src":["https://nihongokyoshi-net.com/2019/01/22/jlptn2-grammar-mon/","https://bunpro.jp/grammar_points/213"],"vf":1,"u":18,"g":1,"gp":"gg_N3_04"},{"id":"g3_081","t":"～によって","ko":"~에 따라, ~에 의해","cat":"원인·이유","conn":[{"w":"명사","f":"人 + によって"},{"w":"명사 수식","f":"台風 + による + 被害"}],"rule":["1. 명사 뒤에 によって를 붙인다.","2. 뜻은 네 가지다: ① 따라 다름(人によって違う) ② 원인(台風によって) ③ 수단(話し合いによって) ④ 수동문의 행위자(ピカソによって描かれた).","3. 문어체에서는 により, 명사를 꾸밀 때는 による + 명사를 쓴다."],"why":"","nu":"'따라 다름'의 뜻은 회화에서도 자주 쓰고(人によって違う), 원인·수단·수동의 뜻은 뉴스나 문장체에서 많이 쓴다. 원인의 뜻일 때 뒤에 말하는 사람의 의지·명령은 오지 않는다. 수동문 행위자에 によって를 쓰는 것은 작품·발명·건설 등 만들어 내는 동작이 대표적이다.","cmp":[{"g":"～によれば","d":"정보의 출처('~에 의하면'). によって에는 이 뜻이 없다."},{"g":"～で","d":"원인·수단의 일상적인 표현. によって는 더 딱딱하다."}],"ex":[{"jp":"考[かんが]え方[かた]は人[ひと]によって違[ちが]う。","ko":"생각하는 방식은 사람에 따라 다르다."},{"jp":"台風[たいふう]によって電車[でんしゃ]が止[と]まった。","ko":"태풍으로 인해 전철이 멈췄다."},{"jp":"この絵[え]は有名[ゆうめい]な画家[がか]によって描[か]かれた。","ko":"이 그림은 유명한 화가에 의해 그려졌다."}],"dr":[{"t":"make","q":"国 → ～習慣が違う","a":"国によって習慣が違う","hint":"명사 + によって + 違う"},{"t":"make","q":"地震 + ～ + 被害（명사 수식）","a":"地震による被害","hint":"명사 수식은 による"},{"t":"fill","q":"季節[きせつ]（　）景色[けしき]が変[か]わる。","a":"によって","opts":["によって","によれば","にとって","について"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/によって-による-ni-yotte-ni-yoru-meaning","https://nihongokyoshi-net.com/2019/05/03/jlptn3-grammar-niyotte-3/"],"vf":1,"u":19,"g":1,"gp":"gg_N3_04"},{"id":"g3_127","t":"～んだもん","ko":"~인걸, ~거든(변명·이유)","cat":"원인·이유","conn":[{"w":"동사 보통형","f":"遅れた + んだもん"},{"w":"い형용사","f":"眠い + んだもん"},{"w":"な형용사","f":"好き + なんだもん (だ→な)"},{"w":"명사","f":"日曜日 + なんだもん (だ→な)"}],"rule":["1. 동사·い형용사는 보통형(현재·과거·부정) 그대로 뒤에 んだ를 붙인다(眠い → 眠いんだ).","2. な형용사·명사는 だ를 な로 바꾼 뒤 んだ를 붙인다(好きだ → 好きなんだ).","3. 마지막에 もん을 붙여 문장을 끝낸다(眠いんだ → 眠いんだもん)."],"why":"설명의 のだ가 회화에서 줄어든 んだ에, 이유를 내세우는 종조사 もの의 회화형 もん이 붙은 형태다.","nu":"친한 사이의 회화에서만 쓰는 말투로, 자기 행동을 변명하거나 정당화하는 느낌이 강하다. 아이나 젊은 여성의 어리광 섞인 말투로 들리기 쉬우므로 윗사람이나 격식 있는 자리에서는 쓰지 않는다. 앞에 だって(그치만)가 자주 함께 온다. 한국어의 '~란 말이야/~인걸'에 가깝다.","cmp":[{"g":"～から","d":"から는 이유를 중립적으로 말하며 어떤 자리에서도 쓸 수 있다. んだもん은 자기 입장을 고집하는 변명조의 반말이다."}],"ex":[{"jp":"だって、眠[ねむ]いんだもん。","ko":"그치만 졸린걸."},{"jp":"遅[おく]れてごめん。電車[でんしゃ]が止[と]まったんだもん。","ko":"늦어서 미안. 전철이 멈췄단 말이야."},{"jp":"だって、この服[ふく]が好[す]きなんだもん。","ko":"그치만 이 옷이 좋은걸."}],"dr":[{"t":"make","q":"眠い → ～んだもん","a":"眠いんだもん","hint":"い형용사는 그대로 んだもん"},{"t":"make","q":"好きだ → ～んだもん","a":"好きなんだもん","hint":"な형용사는 だ를 な로 바꾸고 んだもん"},{"t":"fill","q":"だって、知[し]らなかった（　）。","a":"んだもん","opts":["んだもん","ために","ように","ことに"]}],"src":[],"vf":0,"u":19,"g":1,"gp":"gg_N3_04"},{"id":"g3_112","t":"～ように (목적)","ko":"~하도록","cat":"목적","conn":[{"w":"동사 사전형","f":"間に合う + ように"},{"w":"동사 ない형","f":"忘れない + ように"},{"w":"동사 가능형","f":"話せる + ように"}],"rule":["1. 이루고 싶은 상태를 동사 사전형·ない형·가능형으로 만든다(忘れる → 忘れない: る를 빼고 ない).","2. 그 뒤에 ように를 붙인다.","3. ように 뒤에 그 목적을 위해 하는 행동을 이어 말한다(忘れないようにメモする)."],"why":"","nu":"ように 앞에는 주로 의지로 조절할 수 없는 동사(わかる, 見える, 間に合う), 가능형, ない형이 온다. 의지동사로 직접 목적을 말할 때는 ために를 쓰는 것이 기본이다(日本へ行くために貯金する). 한국어 '~하도록'에 끌려 의지동사 사전형 + ように를 쓰는 실수가 많다.","cmp":[{"g":"～ために","d":"앞에 의지동사가 오고 앞뒤 주어가 같을 때 쓰는 목적 표현."}],"ex":[{"jp":"忘[わす]れないように、手帳[てちょう]にメモした。","ko":"잊어버리지 않도록 수첩에 메모했다."},{"jp":"後[うし]ろの人[ひと]にも聞[き]こえるように、大[おお]きい声[こえ]で話[はな]してください。","ko":"뒷사람에게도 들리도록 큰 소리로 말해 주세요."},{"jp":"日本語[にほんご]が話[はな]せるように、毎日[まいにち]練習[れんしゅう]している。","ko":"일본어를 말할 수 있도록 매일 연습하고 있다."}],"dr":[{"t":"make","q":"遅れる → ない형 + ように","a":"遅れないように","hint":"る를 빼고 ない + ように"},{"t":"make","q":"読む → 가능형 + ように","a":"読めるように","hint":"む를 め로 바꾸고 る + ように"},{"t":"fill","q":"風邪[かぜ]をひかない（　）、よく手[て]を洗[あら]います。","a":"ように","opts":["ように","ばかりに","ところ","までに"]}],"src":[],"vf":0,"u":19,"g":1,"gp":"gg_N3_04"},{"id":"g3_066","t":"～としたら","ko":"(만약) ~라고 한다면","cat":"접속·조건","conn":[{"w":"동사 보통형","f":"降る + としたら"},{"w":"い형용사","f":"高い + としたら"},{"w":"な형용사","f":"本当だ + としたら"},{"w":"명사","f":"雨だ + としたら"}],"rule":["1. 앞말은 보통형 그대로 둔다(降る, 降らない, 降った).","2. 명사·な형용사는 보통 だ를 붙인다(雨 → 雨だ). だ를 생략하기도 한다.","3. 그 뒤에 としたら를 붙인다(雨だとしたら).","4. 뒤에는 그 가정 아래에서의 판단·생각을 말한다."],"why":"と(인용) + したら(する의 たら형). '~라고 해 본다면' → 가정의 뜻.","nu":"사실인지 모르는 일이나 실제와 다른 일을 일단 가정해 보고 판단을 말할 때 쓴다. 회화와 글 모두에 쓴다. もし와 자주 함께 쓴다. 비슷한 표현으로 とすれば가 있다. 일상적인 조건(봄이 되면 등)에는 たら·と를 쓰는 편이 자연스럽다.","cmp":[{"g":"～とすれば","d":"뜻은 거의 같다. 판단·추론을 말하는 문장에서 자주 쓰며 약간 더 딱딱하다."},{"g":"～なら","d":"상대의 말이나 상황을 받아 '~라면'이라고 할 때 쓴다. としたら는 일부러 가정을 세운다는 느낌이 강하다."}],"ex":[{"jp":"明日[あした]雨[あめ]だとしたら、試合[しあい]は中止[ちゅうし]だろう。","ko":"내일 비라면 시합은 취소겠지."},{"jp":"もし宝[たから]くじが当[あ]たったとしたら、何[なに]をしたい？","ko":"만약 복권에 당첨된다면 뭘 하고 싶어?"},{"jp":"その話[はなし]が本当[ほんとう]だとしたら、大変[たいへん]なことだ。","ko":"그 이야기가 사실이라면 큰일이다."}],"dr":[{"t":"make","q":"雨 → ～としたら","a":"雨だとしたら","hint":"명사 + だ + としたら"},{"t":"make","q":"一億円ある → ～としたら","a":"一億円あるとしたら","hint":"동사 보통형 + としたら"},{"t":"fill","q":"彼[かれ]が犯人[はんにん]だ（　）、なぜあの日[ひ]ここにいたのだろう。","a":"としたら","opts":["としたら","として","ところで","というより"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%97%E3%81%9F%E3%82%89-%E3%81%A8%E3%81%99%E3%82%8C%E3%81%B0-%E3%81%A8%E3%81%99%E3%82%8B%E3%81%A8"],"vf":1,"u":20,"g":1,"gp":"gg_N3_04"},{"id":"g3_090","t":"～ば～のに","ko":"~했으면 ~했을 텐데","cat":"접속·조건","conn":[{"w":"1그룹 동사","f":"行く → 行けば"},{"w":"2그룹 동사","f":"起きる → 起きれば"},{"w":"불규칙 동사","f":"来る → 来れば(くれば) / する → すれば"},{"w":"い형용사","f":"安い → 安ければ"},{"w":"な형용사·명사","f":"暇なら / 学生なら"}],"rule":["1. 앞부분을 ば형으로 바꾼다: 1그룹은 어미 う단을 え단으로 바꾸고 ば(行く → 行けば), 2그룹은 る를 れ로 바꾸고 ば(起きる → 起きれば).","2. 불규칙: 来る → 来れば(くれば), する → すれば. い형용사는 い → ければ(安ければ), な형용사·명사는 なら를 쓴다.","3. 뒷부분에는 실제로는 일어나지 않은 결과를 말하고 끝에 のに를 붙인다(間に合ったのに).","4. 자주 쓰는 꼴: ～ばよかったのに(~하면 좋았을 텐데)."],"why":"","nu":"현실과 반대되는 일을 가정하며 후회·아쉬움·불만을 나타낸다. 남에게 쓰면 '그렇게 했으면 좋았잖아'라는 비난이 된다(早く言えばいいのに). 회화에서 많이 쓰며, 앞의 ば형 대신 たら를 쓰기도 한다(来たら間に合ったのに). 끝을 のに로 맺고 뒤를 생략하는 일이 많다.","cmp":[{"g":"～ばよかった","d":"자기 일에 대한 후회. のに가 붙으면 아쉬움·불만이 더 강해지고 남의 일에도 쓴다."},{"g":"～のに (역접)","d":"'~인데도'. 문장 중간에서 두 사실을 잇는 용법은 반사실 가정이 없다."}],"ex":[{"jp":"もっと早[はや]く来[く]れば、電車[でんしゃ]に間[ま]に合[あ]ったのに。","ko":"좀 더 빨리 왔으면 전철을 탈 수 있었을 텐데."},{"jp":"もう少[すこ]し安[やす]ければ、買[か]ったのに。","ko":"조금만 더 쌌으면 샀을 텐데."},{"jp":"言[い]ってくれれば、手伝[てつだ]ったのに。","ko":"말해 줬으면 도와줬을 텐데."}],"dr":[{"t":"make","q":"勉強する → ～合格したのに","a":"勉強すれば合格したのに","hint":"する → すれば"},{"t":"make","q":"起きる → ～よかったのに","a":"起きればよかったのに","hint":"2그룹: る → れ + ば"},{"t":"fill","q":"傘[かさ]を持[も]って行[い]けば、ぬれなかった（　）。","a":"のに","opts":["のに","ので","から","ために"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%B0%E3%82%88%E3%81%8B%E3%81%A3%E3%81%9F"],"vf":1,"u":20,"g":1,"gp":"gg_N3_05"},{"id":"g3_107","t":"もし～たなら","ko":"만약 ~했다면","cat":"접속·조건","conn":[{"w":"동사 た형","f":"もし + 知っていた + なら"},{"w":"い형용사","f":"もし + よかった + なら"},{"w":"な형용사","f":"もし + 暇だった + なら"},{"w":"명사","f":"もし + 学生だった + なら"}],"rule":["1. 동사·형용사를 과거형(た형)으로 만든다. 예: 知る→知っていた(る가 って로 바뀌고 いた 추가), いい→よかった.","2. な형용사·명사는 だった로 만든다(暇だった).","3. 그 뒤에 なら를 붙이고 앞에 もし를 놓는다(もし知っていたなら)."],"why":"","nu":"실제와 반대되는 과거 가정('~했다면 …했을 텐데')에 자주 쓰며, 뒤에 のに·だろう가 온다. '정말로 ~했다면'처럼 상대의 말을 전제로 삼을 때도 쓴다. 회화에서는 もし～たら가 더 흔하다.","cmp":[{"g":"もし～たら","d":"일반적인 가정으로 더 회화적. 미래의 일에도 자연스럽게 쓴다."}],"ex":[{"jp":"もしあの時[とき]知[し]っていたなら、すぐに教[おし]えたのに。","ko":"만약 그때 알았다면 바로 알려 줬을 텐데."},{"jp":"もし彼[かれ]が本当[ほんとう]にそう言[い]ったなら、謝[あやま]るべきだ。","ko":"만약 그가 정말로 그렇게 말했다면 사과해야 한다."},{"jp":"もし天気[てんき]がよかったなら、海[うみ]に行[い]けたのに。","ko":"만약 날씨가 좋았다면 바다에 갈 수 있었을 텐데."}],"dr":[{"t":"make","q":"知る → もし～たなら","a":"もし知っていたなら","hint":"る를 って로 + いた + なら"},{"t":"make","q":"暇 → もし～たなら","a":"もし暇だったなら","hint":"な형용사·명사는 だった + なら"},{"t":"fill","q":"もし昨日[きのう]晴[は]れていた（　）、出[で]かけたのに。","a":"なら","opts":["なら","のに","から","けど"]}],"src":["https://cotoacademy.com/moshi-tanara-grammar-meaning-explanation/"],"vf":1,"u":20,"g":1,"gp":"gg_N3_05"},{"id":"g3_109","t":"もしも～なら","ko":"만약 ~라면","cat":"접속·조건","conn":[{"w":"동사 보통형","f":"行かない + なら"},{"w":"い형용사","f":"高い + なら"},{"w":"な형용사","f":"暇 + なら (だ 없이)"},{"w":"명사","f":"雨 + なら (だ 없이)"}],"rule":["1. 문장 앞에 もしも를 놓아 가정이라는 것을 먼저 드러낸다.","2. 동사·い형용사는 보통형(현재·과거·부정) 그대로 뒤에 なら를 붙인다.","3. 명사·な형용사는 だ를 빼고 그 자리에 なら를 붙인다(雨だ → 雨なら)."],"why":"","nu":"もしも는 もし보다 가정의 느낌을 강하게 드러내며, 실제로는 잘 일어나지 않을 것 같은 일에 자주 쓴다. もしも는 なら뿐 아니라 たら·ば와도 함께 쓴다. なら 뒤에는 그 가정에 대한 판단·조언·의지가 오는 경우가 많다. 앞 일이 먼저 일어나고 그다음 일이 이어지는 순서(~하고 나서)를 말할 때는 なら보다 たら가 자연스럽다(駅に着いたら電話して).","cmp":[{"g":"もし～たら","d":"たら는 앞 일이 실현된 뒤의 일을 말할 때 폭넓게 쓴다. なら는 상대의 말이나 주어진 상황을 전제로 판단·조언을 말할 때 잘 어울린다."}],"ex":[{"jp":"もしも明日[あした]雨[あめ]なら、試合[しあい]は中止[ちゅうし]です。","ko":"만약 내일 비가 오면 시합은 중지입니다."},{"jp":"もしも時間[じかん]がないなら、無理[むり]に来[こ]なくてもいいよ。","ko":"만약 시간이 없다면 무리해서 안 와도 돼."},{"jp":"もしも暇[ひま]なら、ちょっと手伝[てつだ]ってくれない？","ko":"만약 한가하면 좀 도와주지 않을래?"}],"dr":[{"t":"make","q":"雨だ → もしも～なら","a":"もしも雨なら","hint":"명사는 だ를 빼고 なら"},{"t":"make","q":"行かない → もしも～なら","a":"もしも行かないなら","hint":"동사 보통형에 그대로 なら"},{"t":"fill","q":"もしも分[わ]からない（　）、先生[せんせい]に聞[き]いてください。","a":"なら","opts":["なら","のに","ので","けれど"]}],"src":[],"vf":0,"u":21,"g":1,"gp":"gg_N3_05"},{"id":"g3_011","t":"～くせに","ko":"~인 주제에, ~면서도","cat":"역접","conn":[{"w":"동사 보통형","f":"知っている + くせに"},{"w":"い형용사","f":"若い + くせに"},{"w":"な형용사","f":"暇な + くせに"},{"w":"명사","f":"子供の + くせに"}],"rule":["1. 명사를 꾸미는 꼴 뒤에 くせに를 붙인다.","2. な형용사는 어미 だ를 な로 바꾼다(暇だ → 暇なくせに).","3. 명사는 の를 넣는다(子供のくせに).","4. 동사·い형용사는 보통형 그대로 붙인다(知っているくせに, 若いくせに)."],"why":"くせ(癖, 버릇·나쁜 경향) + に로 이루어진 말이다.","nu":"주로 남의 행동을 비난·경멸하는 회화체이며 감정이 강하다. 윗사람이나 공적인 자리에서는 피하고 중립적인 「～のに」를 쓴다. 앞뒤 주어가 같아야 한다. 「～くせして」도 같은 뜻의 회화체.","cmp":[{"g":"～のに","d":"のに는 의외·불만을 말하는 중립 표현. くせに는 상대를 탓하는 마음이 강하다."}],"ex":[{"jp":"弟[おとうと]は暇[ひま]なくせに、全然[ぜんぜん]手伝[てつだ]ってくれない。","ko":"남동생은 한가한 주제에 전혀 도와주지 않는다."},{"jp":"本当[ほんとう]は知[し]っているくせに、何[なに]も言[い]わない。","ko":"사실은 알고 있으면서 아무 말도 안 한다."},{"jp":"子供[こども]のくせに、生意気[なまいき]なことを言[い]うな。","ko":"어린애 주제에 건방진 소리 하지 마."}],"dr":[{"t":"make","q":"下手だ → ～くせに","a":"下手なくせに","hint":"な형용사는 だ를 な로 바꾼다"},{"t":"make","q":"大人 → ～くせに","a":"大人のくせに","hint":"명사 뒤에는 の를 넣는다"},{"t":"fill","q":"自分[じぶん]では何[なに]もしない（　）、文句[もんく]ばかり言[い]う。","a":"くせに","opts":["くせに","ために","ように","おかげで"]}],"src":["https://bunpro.jp/grammar_points/295"],"vf":1,"u":21,"g":1,"gp":"gg_N3_05"},{"id":"g3_019","t":"～ことは…が","ko":"~하기는 ~하지만","cat":"역접","conn":[{"w":"동사 보통형","f":"読む → 読むことは読むが"},{"w":"동사 た형","f":"行った → 行ったことは行ったが"},{"w":"い형용사","f":"高い → 高いことは高いが"},{"w":"な형용사","f":"便利な → 便利なことは便利だが"}],"rule":["1. 같은 말을 두 번 쓴다: 앞쪽은 보통형(명사 수식형) + ことは.","2. い형용사·동사는 같은 형태를 그대로 반복한다(高いことは高い).","3. な형용사는 앞쪽만 な, 뒤쪽은 だ로 끝낸다(便利なことは便利だ).","4. 뒤에 が(회화는 けど)를 붙이고 앞과 반대되는 내용(주로 제한·불만)을 이어 말한다."],"why":"こと(것) + は(주제)로 '~하다는 것은 (분명) ~하다'고 일단 인정한 뒤 が로 뒤집는 구조다.","nu":"사실을 일단 인정하지만 완전히 만족하거나 긍정하지는 않는다는 뉘앙스. 뒤에는 앞 내용과 반대되는 점(주로 단점·한계)이 온다. 회화에서는 が 대신 けど를 많이 쓴다. な형용사 뒤쪽을 便利な로 끝내는 실수에 주의.","cmp":[{"g":"～けど／が","d":"단순 역접. ことは…が는 앞 내용을 '인정은 하지만'이라고 한 번 더 강조한 뒤 뒤집는다."}],"ex":[{"jp":"この店[みせ]の料理[りょうり]はおいしいことはおいしいが、値段[ねだん]が高[たか]い。","ko":"이 가게 요리는 맛있기는 맛있지만 가격이 비싸다."},{"jp":"宿題[しゅくだい]はやったことはやったけど、半分[はんぶん]しかできなかった。","ko":"숙제는 하기는 했지만 절반밖에 못 했다."},{"jp":"この部屋[へや]は静[しず]かなことは静[しず]かだが、駅[えき]から遠[とお]い。","ko":"이 방은 조용하기는 조용하지만 역에서 멀다."}],"dr":[{"t":"make","q":"読む → ～ことは…が","a":"読むことは読むが","hint":"보통형 + ことは + 같은 동사 + が"},{"t":"make","q":"便利 → ～ことは…が","a":"便利なことは便利だが","hint":"앞은 な, 뒤는 だ로 끝내고 が"},{"t":"fill","q":"このかばんは高[たか]い（　）高[たか]いが、とても丈夫[じょうぶ]だ。","a":"ことは","opts":["ことは","ことに","ことか","ことで"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%93%E3%81%A8%E3%81%AF-%E3%81%8C"],"vf":1,"u":21,"g":1,"gp":"gg_N3_05"},{"id":"g3_033","t":"だけど","ko":"~지만, 하지만","cat":"역접","conn":[{"w":"명사","f":"学生 → 学生だけど"},{"w":"な형용사","f":"静か → 静かだけど"},{"w":"문장 앞(접속사)","f":"行きたい。だけど、お金がない。"}],"rule":["1. 명사·な형용사 뒤에 단정의 だ를 붙인다(静かだ).","2. 그 뒤에 けど를 붙이고 반대 내용을 잇는다(静かだけど、不便だ).","3. 문장 맨 앞에 접속사로 だけど、를 써도 된다.","4. い형용사·동사 뒤에는 だ 없이 けど만 붙인다(高いけど)."],"why":"단정의 だ + 역접 조사 けど로 이루어져 있다.","nu":"회화체. 정중하게는 ですが·ですけど, 글에서는 しかし·だが를 쓴다. 高いだけど·行くだけど처럼 い형용사·동사에 だ를 붙이는 실수에 주의.","cmp":[{"g":"でも","d":"문장 앞에 쓰는 회화적 '하지만'. 명사·な형용사 뒤에 직접 붙여 역접을 만들지는 않는다."},{"g":"しかし","d":"문어적이고 딱딱한 '그러나'."}],"ex":[{"jp":"この部屋[へや]は静[しず]かだけど、駅[えき]から遠[とお]い。","ko":"이 방은 조용하지만 역에서 멀다."},{"jp":"彼[かれ]はまだ学生[がくせい]だけど、自分[じぶん]で会社[かいしゃ]を作[つく]った。","ko":"그는 아직 학생이지만 스스로 회사를 만들었다."},{"jp":"行[い]きたい。だけど、お金[かね]がない。","ko":"가고 싶다. 하지만 돈이 없다."}],"dr":[{"t":"make","q":"便利 → ～だけど","a":"便利だけど","hint":"な형용사 + だ + けど"},{"t":"make","q":"雨 → ～だけど","a":"雨だけど","hint":"명사 + だ + けど"},{"t":"fill","q":"この店[みせ]は有名[ゆうめい]（　）、あまりおいしくない。","a":"だけど","opts":["だけど","だから","なので","けど"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/だけど-dakedo-meaning/","https://bunpro.jp/grammar_points/%E3%81%91%E3%81%A9-%E3%81%A0%E3%81%91%E3%81%A9"],"vf":1,"u":22,"g":1,"gp":"gg_N3_05"},{"id":"g3_035","t":"たとえ～ても","ko":"설령 ~하더라도","cat":"역접","conn":[{"w":"동사 て형","f":"降る → たとえ降っても"},{"w":"い형용사","f":"寒い → たとえ寒くても"},{"w":"な형용사","f":"下手 → たとえ下手でも"},{"w":"명사","f":"子ども → たとえ子どもでも"}],"rule":["1. 동사는 て형에 も를 붙인다: 1그룹 る는 って(降る → 降って → 降っても).","2. い형용사는 い를 くて로 바꾸고 も(寒くても).","3. な형용사·명사는 でも를 붙인다(下手でも, 子どもでも).","4. 앞에 たとえ를 놓아 '설령'을 강조한다(たとえ降っても)."],"why":"","nu":"가정한 조건이 실제로 일어나도 결과는 바뀌지 않는다는 강한 역접. 뒤에는 의지·판단·당연함이 자주 온다. たとえ는 생략할 수 있지만, たとえ만 쓰고 ても를 빠뜨리면 틀린다.","cmp":[{"g":"～ても","d":"たとえ 없이도 같은 뜻. たとえ를 붙이면 '설령'의 가정이 더 강조된다."}],"ex":[{"jp":"たとえ雨[あめ]が降[ふ]っても、試合[しあい]は行[おこな]われる。","ko":"설령 비가 오더라도 시합은 열린다."},{"jp":"たとえ高[たか]くても、このかばんが欲[ほ]しい。","ko":"설령 비싸더라도 이 가방을 갖고 싶다."},{"jp":"たとえ子[こ]どもでも、ルールは守[まも]らなければならない。","ko":"설령 아이라도 규칙은 지켜야 한다."}],"dr":[{"t":"make","q":"失敗する → たとえ～ても","a":"たとえ失敗しても","hint":"する의 て형 して + も"},{"t":"make","q":"遠い → たとえ～ても","a":"たとえ遠くても","hint":"い를 くて로 바꾸고 も"},{"t":"fill","q":"たとえ反対[はんたい]され（　）、私[わたし]は留学[りゅうがく]する。","a":"ても","opts":["ても","たら","ば","と"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/たとえ～ても-tatoe-temo-meaning","https://bunpro.jp/grammar_points/276"],"vf":1,"u":22,"g":1,"gp":"gg_N3_05"},{"id":"g3_052","t":"～ても","ko":"~해도, ~하더라도","cat":"역접","conn":[{"w":"동사 て형","f":"降って + も"},{"w":"い형용사","f":"高くて + も"},{"w":"いい","f":"よくて + も"},{"w":"な형용사","f":"静かで + も"},{"w":"명사","f":"日曜日で + も"}],"rule":["1. 동사는 て형에 も를 붙인다(降る → 降っても).","2. い형용사는 い를 く로 바꾸고 て + も를 붙인다(高い → 高くても). いい는 よくても.","3. な형용사·명사는 で + も를 붙인다(静かでも, 日曜日でも)."],"why":"","nu":"앞의 조건이 있어도 뒤의 결과는 바뀌지 않음을 나타낸다. 실제 사실에도, 가정에도 쓴다. たとえ・いくら・どんなに와 잘 어울리고, 의문사와 함께 쓰면 '무엇을 ~해도'(何を言っても)가 된다. 명사 + でも를 '커피라도'의 でも와 혼동하지 않도록 주의.","cmp":[{"g":"～のに","d":"이미 일어난 사실에 대한 불만·의외. 가정에는 쓰지 않는다. ～ても는 가정에도 쓸 수 있다."}],"ex":[{"jp":"雨[あめ]が降[ふ]っても、試合[しあい]はあります。","ko":"비가 와도 시합은 있습니다."},{"jp":"高[たか]くても、このかばんが買[か]いたい。","ko":"비싸도 이 가방을 사고 싶다."},{"jp":"日曜日[にちようび]でも、この店[みせ]は開[あ]いています。","ko":"일요일이라도 이 가게는 열려 있습니다."}],"dr":[{"t":"make","q":"高い → ～ても","a":"高くても","hint":"い → く, 그 뒤에 ても"},{"t":"make","q":"静か → ～ても","a":"静かでも","hint":"な형용사 + でも"},{"t":"fill","q":"いくら練習[れんしゅう]し（　）、上手[じょうず]にならない。","a":"ても","opts":["ても","ながら","たり","そう"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A6%E3%82%82"],"vf":1,"u":22,"g":1,"gp":"gg_N3_05"},{"id":"g3_060","t":"～といっても","ko":"~라고 해도 (실제로는 그리 대단하지 않다)","cat":"역접","conn":[{"w":"동사 보통형","f":"できる + といっても"},{"w":"い형용사","f":"寒い + といっても"},{"w":"な형용사","f":"有名(だ) + といっても"},{"w":"명사","f":"旅行(だ) + といっても"}],"rule":["1. 앞말은 보통형 그대로 둔다. 명사·な형용사는 だ를 붙여도 되고 빼도 된다(旅行).","2. 그 뒤에 といっても를 붙인다.","3. 뒤에 '실제로는 그 말에서 기대하는 만큼은 아니다'라는 내용을 말한다(近所)."],"why":"と(인용) + いっても(言う의 て형 + も: 말해도).","nu":"앞에서 한 말 때문에 상대가 크게 생각할까 봐 실제 정도를 덧붙여 낮출 때 쓴다. 회화에 많이 쓴다. 단순한 역접 '~지만'과 달리 '말은 그렇지만 실제로는 별것 아니다'라는 뜻이 핵심이다.","cmp":[{"g":"～けれども","d":"단순 역접. 앞말의 정도를 고쳐 낮추는 뜻은 없다."},{"g":"～からといって","d":"'~라는 이유만으로 (반드시 ~인 것은 아니다)'. 뒤에 부정이 온다."}],"ex":[{"jp":"旅行[りょこう]といっても、近所[きんじょ]の温泉[おんせん]に行[い]くだけです。","ko":"여행이라고 해도 근처 온천에 가는 것뿐이에요."},{"jp":"料理[りょうり]ができるといっても、簡単[かんたん]なものしか作[つく]れない。","ko":"요리를 할 줄 안다고 해도 간단한 것밖에 못 만든다."},{"jp":"寒[さむ]いといっても、雪[ゆき]が降[ふ]るほどではない。","ko":"춥다고 해도 눈이 올 정도는 아니다."}],"dr":[{"t":"make","q":"旅行 → ～といっても","a":"旅行といっても","hint":"명사 + といっても"},{"t":"make","q":"英語が話せる → ～といっても","a":"英語が話せるといっても","hint":"보통형 + といっても"},{"t":"fill","q":"社長[しゃちょう]（　）、社員[しゃいん]は三人[さんにん]しかいない会社[かいしゃ]です。","a":"といっても","opts":["といっても","というと","というのは","にとって"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E8%A8%80%E3%81%A3%E3%81%A6%E3%82%82"],"vf":1,"u":23,"g":1,"gp":"gg_N3_05"},{"id":"g3_069","t":"どんなに～ても","ko":"아무리 ~해도","cat":"역접","conn":[{"w":"동사 て형","f":"どんなに + 走って + も"},{"w":"い형용사","f":"どんなに + 高くて + も"},{"w":"な형용사","f":"どんなに + 好きで + も"},{"w":"명사","f":"どんなに + いい人で + も"}],"rule":["1. 문장 앞쪽에 どんなに를 놓는다.","2. 동사는 て형으로 바꾼다. 走る는 1그룹이므로 어미 る를 って로 바꾼다(走って).","3. て형 뒤에 も를 붙인다(走っても). い형용사는 い를 くて로(高くても), な형용사·명사는 でも를 붙인다.","4. 뒤에는 그래도 결과가 바뀌지 않는다는 내용을 말한다."],"why":"どんなに(얼마나) + ても(~해도).","nu":"정도가 아무리 커도 결과는 같다는 뜻. 회화와 글 모두에 쓴다. 뒤에는 보통 '안 된다·바뀌지 않는다'는 내용이 온다. で로 끝나는 て형은 でも가 된다(読んでも, 飲んでも).","cmp":[{"g":"いくら～ても","d":"뜻은 거의 같으며 회화에서 자주 쓴다(いくら呼んでも返事がない)."},{"g":"どんなに～ことか","d":"'얼마나 ~했는지'라는 감탄. 양보가 아니다."}],"ex":[{"jp":"どんなに走[はし]っても、バスに間[ま]に合[あ]わなかった。","ko":"아무리 달려도 버스를 탈 수 없었다."},{"jp":"どんなに高[たか]くても、このカメラが欲[ほ]しい。","ko":"아무리 비싸도 이 카메라를 갖고 싶다."},{"jp":"どんなに好[す]きでも、毎日[まいにち]食[た]べたら飽[あ]きる。","ko":"아무리 좋아해도 매일 먹으면 질린다."}],"dr":[{"t":"make","q":"走る → どんなに～ても","a":"どんなに走っても","hint":"る → って + も"},{"t":"make","q":"忙しい → どんなに～ても","a":"どんなに忙しくても","hint":"い → くて + も"},{"t":"fill","q":"どんなに練習[れんしゅう]し（　）、上手[じょうず]にならない。","a":"ても","opts":["ても","たら","ながら","たり"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A9%E3%82%93%E3%81%AA%E3%81%AB-%E3%81%A6%E3%82%82"],"vf":1,"u":23,"g":1,"gp":"gg_N3_05"},{"id":"g3_077","t":"～にしては","ko":"~치고는","cat":"역접","conn":[{"w":"명사","f":"初心者 + にしては"},{"w":"동사 보통형","f":"初めて作った + にしては"}],"rule":["1. 기준이 되는 명사 뒤에 にしては를 붙인다(だ는 붙이지 않는다).","2. 동사는 보통형 뒤에 그대로 붙인다(初めて作ったにしては).","3. 뒤에는 그 기준에서 예상되는 것과 다른 결과를 말한다."],"why":"","nu":"'~이라는 점을 생각하면 의외로'라는 뜻으로, 칭찬과 비판 모두에 쓴다. 뒤 문장에는 말하는 사람의 평가가 오며 의지·명령은 오지 않는다. 형용사 뒤에는 보통 쓰지 않고 わりに를 쓴다(安いわりにおいしい). 회화와 문장 모두에 쓴다.","cmp":[{"g":"～わりに","d":"정도를 비교하며 형용사에도 붙는다. にしては는 주로 명사·동사의 구체적 기준."},{"g":"～のに","d":"사실과 반대 결과에 대한 불만·의외. 기준과 비교하는 뜻은 없다."}],"ex":[{"jp":"初心者[しょしんしゃ]にしては上手[じょうず]だね。","ko":"초보자치고는 잘하네."},{"jp":"初[はじ]めて作[つく]ったにしては、おいしいケーキだ。","ko":"처음 만든 것치고는 맛있는 케이크다."},{"jp":"四月[しがつ]にしては寒[さむ]い日[ひ]が続[つづ]いている。","ko":"4월치고는 추운 날이 이어지고 있다."}],"dr":[{"t":"make","q":"子ども → ～よく知っている","a":"子どもにしてはよく知っている","hint":"명사 + にしては (だ 없이)"},{"t":"make","q":"一日で書いた → ～よくできている","a":"一日で書いたにしてはよくできている","hint":"동사 보통형 + にしては"},{"t":"fill","q":"十月[じゅうがつ]（　）暑[あつ]いですね。","a":"にしては","opts":["にしては","にとって","によって","について"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/にしては-ni-shite-wa-meaning","https://cotoacademy.com/nishitewa-jlpt-grammar-explanation-meaning-example/"],"vf":1,"u":23,"g":1,"gp":"gg_N3_05"},{"id":"g3_078","t":"～にしても","ko":"~라 해도, ~라 치더라도","cat":"역접","conn":[{"w":"동사 보통형","f":"休む + にしても"},{"w":"い형용사","f":"忙しい + にしても"},{"w":"명사","f":"冗談 + にしても"}],"rule":["1. 동사·い형용사는 보통형 뒤에 にしても를 붙인다(休むにしても).","2. 명사는 바로 뒤에 붙인다(冗談にしても).","3. 앞의 사정을 일단 인정하고, 뒤에서 그래도 달라지지 않는 판단을 말한다."],"why":"","nu":"'~인 것은 인정하지만 그래도'라는 양보로, 뒤에는 비판·의견·당연함 등 말하는 사람의 판단이 온다(冗談にしてもひどい). 회화와 문장 모두에 쓴다. A にしても B にしても 꼴로 'A든 B든'의 뜻도 된다.","cmp":[{"g":"～ても","d":"단순한 '~해도'. にしても는 상대 사정을 인정하는 느낌이 강하고 뒤에 판단이 온다."},{"g":"～にしては","d":"'~치고는'으로 기준과 비교한 의외. 뜻이 전혀 다르다."}],"ex":[{"jp":"冗談[じょうだん]にしても、それはひどいよ。","ko":"농담이라 해도 그건 심해."},{"jp":"休[やす]むにしても、連絡[れんらく]はしてください。","ko":"쉬더라도 연락은 해 주세요."},{"jp":"忙[いそが]しいにしても、電話[でんわ]ぐらいできるでしょう。","ko":"바쁘다 해도 전화 정도는 할 수 있잖아요."}],"dr":[{"t":"make","q":"遅れる → ～連絡してほしい","a":"遅れるにしても連絡してほしい","hint":"동사 보통형 + にしても"},{"t":"make","q":"冗談 → ～言いすぎだ","a":"冗談にしても言いすぎだ","hint":"명사 + にしても"},{"t":"fill","q":"高[たか]い（　）、一度[いちど]は行[い]ってみたい。","a":"にしても","opts":["にしても","にしては","によって","について"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/にしても-ni-shite-mo-meaning","https://nihongokyoshi-net.com/2019/05/25/jlptn3-grammar-nishitemo-nishitemo"],"vf":1,"u":24,"g":1,"gp":"gg_N3_05"},{"id":"g3_108","t":"もし～ても","ko":"만약 ~하더라도","cat":"역접","conn":[{"w":"동사 て형","f":"もし + 降って + も"},{"w":"い형용사","f":"もし + 高く + ても"},{"w":"いい","f":"もし + よく + ても"},{"w":"な형용사","f":"もし + 暇で + も"},{"w":"명사","f":"もし + 雨で + も"}],"rule":["1. 동사를 て형으로 만들고 も를 붙인다(降る→降って→降っても).","2. い형용사는 い를 くても로(高い→高くても), いい는 よくても.","3. な형용사·명사는 でも를 붙인다(暇でも, 雨でも).","4. 앞에 もし를 놓아 가정임을 분명히 한다."],"why":"","nu":"가정한 일이 일어나도 결과는 바뀌지 않는다는 뜻. 뒤에는 의지·판단·사실이 온다. もし 대신 たとえ를 쓰면 '설령'이라는 극단적인 가정이 강조된다.","cmp":[{"g":"たとえ～ても","d":"같은 구조로, 극단적인 경우라도 결과가 같다는 점을 더 강조한다."},{"g":"もし～たら","d":"순접 가정 '~하면'. 결과가 조건에 따라 달라진다."}],"ex":[{"jp":"もし雨[あめ]が降[ふ]っても、試合[しあい]はあります。","ko":"만약 비가 오더라도 시합은 있습니다."},{"jp":"もし高[たか]くても、このかばんを買[か]いたい。","ko":"만약 비싸더라도 이 가방을 사고 싶다."},{"jp":"もし失敗[しっぱい]しても、もう一度[いちど]やればいい。","ko":"만약 실패하더라도 한 번 더 하면 된다."}],"dr":[{"t":"make","q":"降る → もし～ても","a":"もし降っても","hint":"る를 って로 + も"},{"t":"make","q":"高い → もし～ても","a":"もし高くても","hint":"い를 くても로"},{"t":"fill","q":"もし明日[あした]雨[あめ]が降[ふ]って（　）、出[で]かけます。","a":"も","opts":["も","から","ので","ばかり"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%82%82%E3%81%97"],"vf":1,"u":24,"g":1,"gp":"gg_N3_06"},{"id":"g3_125","t":"～わりには","ko":"~에 비해서는","cat":"역접","conn":[{"w":"동사 보통형","f":"勉強しない + わりには"},{"w":"い형용사","f":"安い + わりには"},{"w":"な형용사","f":"静かな + わりには"},{"w":"명사","f":"年 + の + わりには"}],"rule":["1. 동사·い형용사는 보통형 그대로 わりには를 붙인다(安いわりには).","2. な형용사는 だ를 な로 바꾸고 わりには를 붙인다(静かなわりには).","3. 명사는 の를 넣어 のわりには를 붙인다(年のわりには).","4. 뒤에 예상과 다른 실제 결과를 말한다. は를 빼고 わりに라고도 한다."],"why":"","nu":"어떤 정도·조건에서 보통 예상되는 것과 실제가 다를 때 쓴다. 좋은 쪽과 나쁜 쪽 모두에 쓴다. 평가를 말하는 표현이라 뒤에 명령·의지 표현은 오지 않는다. 회화에서 자주 쓴다.","cmp":[{"g":"～にしては","d":"뜻이 비슷하다. 명사에 の 없이 바로 붙는다(子どもにしては)."}],"ex":[{"jp":"この店[みせ]は安[やす]いわりにはおいしい。","ko":"이 가게는 싼 것에 비해서는 맛있다."},{"jp":"弟[おとうと]はあまり勉強[べんきょう]しないわりには成績[せいせき]がいい。","ko":"남동생은 별로 공부하지 않는 것에 비해서는 성적이 좋다."},{"jp":"祖父[そふ]は年[とし]のわりには元気[げんき]だ。","ko":"할아버지는 연세에 비해서는 정정하시다."}],"dr":[{"t":"make","q":"静かだ → ～わりには","a":"静かなわりには","hint":"だ를 な로 + わりには"},{"t":"make","q":"年 → ～わりには","a":"年のわりには","hint":"명사 + の + わりには"},{"t":"fill","q":"彼[かれ]はたくさん食[た]べる（　）やせている。","a":"わりには","opts":["わりには","ために","ように","ことに"]}],"src":[],"vf":0,"u":24,"g":1,"gp":"gg_N3_06"},{"id":"g3_012","t":"～くらい","ko":"~정도, ~만큼","cat":"비교·정도","conn":[{"w":"동사 보통형","f":"泣きたい + くらい"},{"w":"い형용사","f":"痛い + くらい"},{"w":"な형용사","f":"きれいな + くらい"},{"w":"명사·수량","f":"10分 + くらい / それ + くらい"}],"rule":["1. 글자가 바뀌는 활용은 없고, 명사를 꾸미는 꼴 뒤에 くらい(ぐらい)를 붙인다.","2. な형용사는 な를 넣는다(きれいなくらい). 명사·수량에는 그대로 붙인다(10分くらい).","3. 「A くらい B」로 B의 정도를 A라는 예로 나타낸다(泣きたいくらい痛い)."],"why":"","nu":"① 대략의 수량(10分くらい). ② 정도를 예를 들어 강조(泣きたいくらい痛い). ③ 하찮게 여김(それくらい自分でやって). ぐらい로도 쓴다. 정도 강조 용법은 「～ほど」와 거의 같지만, ほど가 조금 더 딱딱하다.","cmp":[{"g":"～ほど","d":"정도의 뜻은 비슷하지만, '~만큼 ~하지 않다'(AほどBではない) 비교에는 ほど를 쓰고, 하찮게 여기는 뜻은 くらい만 있다."}],"ex":[{"jp":"駅[えき]まで歩[ある]いて10分[じゅっぷん]くらいです。","ko":"역까지 걸어서 10분 정도입니다."},{"jp":"足[あし]をぶつけて、泣[な]きたいくらい痛[いた]かった。","ko":"발을 부딪쳐서 울고 싶을 정도로 아팠다."},{"jp":"そのくらい自分[じぶん]でやりなさい。","ko":"그 정도는 스스로 해."}],"dr":[{"t":"make","q":"死ぬほど眠い → くらい로 바꾸기","a":"死ぬくらい眠い","hint":"동사 보통형 뒤에 くらい"},{"t":"make","q":"1時間 → ～くらい","a":"1時間くらい","hint":"수량 뒤에 그대로 くらい"},{"t":"fill","q":"お腹[なか]が痛[いた]くて、立[た]てない（　）だった。","a":"くらい","opts":["くらい","ばかり","ながら","しか"]}],"src":["https://nihongokyoshi-net.com/2019/01/23/jlptn3-grammar-kurai/","https://aiueo.cc/pages/ja/grammar/web/269.php"],"vf":1,"u":25,"g":1,"gp":"gg_N3_06"},{"id":"g3_013","t":"～くらい～はない","ko":"~만큼 ~한 것은 없다 (가장 ~하다)","cat":"비교·정도","conn":[{"w":"명사","f":"富士山 + くらい + きれいな山 + は + ない"},{"w":"명사(사람)","f":"母 + くらい + 優しい人 + は + いない"},{"w":"동사 사전형","f":"寝る + くらい + 楽しいこと + は + ない"}],"rule":["1. 기준이 되는 명사(또는 동사 사전형) 뒤에 くらい(ぐらい)를 붙인다(富士山くらい).","2. 그 뒤에 '형용사＋명사'로 비교 대상을 놓는다. な형용사는 な를 넣어 명사를 꾸민다(きれいな山).","3. 비교 대상 뒤에 は를 붙이고 마지막에 ない를 둔다. 사람・동물이면 いない를 쓴다(優しい人はいない)."],"why":"","nu":"'A만큼 ~한 것은 없다', 즉 A가 가장 ~하다는 말하는 사람의 강한 느낌을 나타낸다. 객관적인 최상급 사실보다는 주관적 평가에 쓰기 쉽다. ほど～はない와 거의 같은 뜻이다. 한국인은 사람에게도 ない를 쓰는 실수(×優しい人はない)를 하기 쉽다.","cmp":[{"g":"～ほど～はない","d":"뜻은 거의 같고 서로 바꿔 쓸 수 있는 경우가 많다."},{"g":"～が一番～","d":"단순히 '가장 ~하다'를 말함. くらい～はない는 감정이 더 강하다."}],"ex":[{"jp":"母[はは]くらい優[やさ]しい人[ひと]はいない。","ko":"엄마만큼 다정한 사람은 없다."},{"jp":"夏[なつ]に飲[の]む冷[つめ]たいビールくらいおいしいものはない。","ko":"여름에 마시는 차가운 맥주만큼 맛있는 것은 없다."},{"jp":"好[す]きな人[ひと]と話[はな]すくらい楽[たの]しいことはない。","ko":"좋아하는 사람과 이야기하는 것만큼 즐거운 일은 없다."}],"dr":[{"t":"make","q":"この店のラーメン / おいしいラーメン → ～くらい～はない","a":"この店のラーメンくらいおいしいラーメンはない","hint":"기준＋くらい＋형용사＋명사＋は＋ない."},{"t":"make","q":"田中さん / まじめな人 → ～くらい～はいない","a":"田中さんくらいまじめな人はいない","hint":"사람이면 마지막을 いない로 한다."},{"t":"fill","q":"自分[じぶん]の家[いえ]（　）落[お]ち着[つ]く場所[ばしょ]はない。","a":"くらい","opts":["くらい","さえ","まで","ばかり"]}],"src":[],"vf":0,"u":25,"g":1,"gp":"gg_N3_06"},{"id":"g3_059","t":"～というより","ko":"~라기보다 (오히려)","cat":"비교·정도","conn":[{"w":"동사 보통형","f":"歩く + というより"},{"w":"い형용사","f":"暑い + というより"},{"w":"な형용사","f":"静か(だ) + というより"},{"w":"명사","f":"先生(だ) + というより"}],"rule":["1. 앞에 일단 떠오르는 표현을 둔다. 명사·な형용사는 だ를 붙여도 되고, 회화에서는 빼기도 한다(先生).","2. 그 뒤에 というより를 붙인다.","3. 뒤에 더 알맞은 표현을 말한다(友達). むしろ를 함께 쓰기도 한다."],"why":"という(~라는) + より(~보다).","nu":"A라고 말할 수도 있지만 B라고 하는 편이 더 정확하다고 고쳐 말할 때 쓴다. 회화와 글 모두에 쓴다. 'A보다 B가 좋다'는 선호(好み)의 비교가 아니라 표현의 적절함을 비교한다는 점에 주의.","cmp":[{"g":"～より","d":"AよりBのほうが～처럼 두 대상의 정도를 비교한다. というより는 같은 대상을 어떻게 부르는 게 맞는지 비교한다."}],"ex":[{"jp":"山田[やまだ]先生[せんせい]は、先生[せんせい]というより友達[ともだち]みたいだ。","ko":"야마다 선생님은 선생님이라기보다 친구 같다."},{"jp":"今日[きょう]は暑[あつ]いというより、もう痛[いた]いくらいだ。","ko":"오늘은 덥다기보다 이제 아플 정도다."},{"jp":"彼[かれ]は歩[ある]くというより、走[はし]っているようだった。","ko":"그는 걷는다기보다 뛰고 있는 것 같았다."}],"dr":[{"t":"make","q":"先生 / 友達 → ～というより","a":"先生というより友達だ","hint":"명사 + というより + 더 맞는 말"},{"t":"make","q":"静かだ / さびしい → ～というより","a":"静かというよりさびしい","hint":"な형용사는 だ를 빼도 된다(静かだというより도 가능)"},{"t":"fill","q":"この部屋[へや]は広[ひろ]い（　）、何[なに]もないだけだ。","a":"というより","opts":["というより","というのは","ということだ","として"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%84%E3%81%86%E3%82%88%E3%82%8A"],"vf":1,"u":25,"g":1,"gp":"gg_N3_06"},{"id":"g3_084","t":"～に比べて","ko":"~에 비해(서)","cat":"비교·정도","conn":[{"w":"명사","f":"夏 + に比べて"},{"w":"동사 사전형 + の","f":"歩く + の + に比べて"}],"rule":["1. 비교 기준이 되는 명사 뒤에 に比べて를 붙인다.","2. 동사를 기준으로 할 때는 사전형 뒤에 の를 넣어 명사로 만든 뒤 붙인다(歩くのに比べて).","3. 뒤에는 기준과 비교한 결과(형용사·정도 표현)가 온다.","4. に比べると・と比べて도 같은 뜻으로 쓴다."],"why":"に + 比[くら]べる(비교하다)의 て형 比べて가 결합한 형태다.","nu":"회화와 문장 모두에 쓴다. 문어체에서는 に比べ를 쓴다. 기준과 결과를 비교하는 말이라 뒤에 비교할 수 없는 내용(의지 등)은 오지 않는다. な형용사·명사에 だ를 붙여 に比べて로 잇지 않는다.","cmp":[{"g":"～より","d":"'~보다'로 비교 기준을 표시. 뜻은 비슷하지만 に比べて는 두 대상을 나란히 놓고 비교하는 느낌이 강하다."},{"g":"～に対して","d":"대비의 뜻이 있지만 정도 비교가 아니라 두 사실의 대조."}],"ex":[{"jp":"夏[なつ]に比[くら]べて、冬[ふゆ]は寒[さむ]い。","ko":"여름에 비해 겨울은 춥다."},{"jp":"去年[きょねん]に比べて、今年[ことし]は雨[あめ]が少[すく]ない。","ko":"작년에 비해 올해는 비가 적다."},{"jp":"電車[でんしゃ]で行[い]くのに比べて、バスは時間[じかん]がかかる。","ko":"전철로 가는 것에 비해 버스는 시간이 걸린다."}],"dr":[{"t":"make","q":"東京 → ～大阪は物価が安い","a":"東京に比べて大阪は物価が安い","hint":"기준 명사 + に比べて"},{"t":"make","q":"書く → ～話すほうが簡単だ","a":"書くのに比べて話すほうが簡単だ","hint":"동사 사전형 + の + に比べて"},{"t":"fill","q":"兄[あに]（　）、弟[おとうと]はよく勉強[べんきょう]する。","a":"に比べて","opts":["に比べて","にとって","について","にかわって"]}],"src":["https://nihongokyoshi-net.com/2018/08/02/jlptn3-grammar-kurabete/","https://jlptsensei.com/learn-japanese-grammar/%E3%81%AB%E6%AF%94%E3%81%B9%E3%81%A6-ni-kurabete-meaning/"],"vf":1,"u":26,"g":1,"gp":"gg_N3_06"},{"id":"g3_091","t":"～ば～ほど","ko":"~하면 ~할수록","cat":"비교·정도","conn":[{"w":"동사","f":"読めば + 読む + ほど"},{"w":"동사(する)","f":"すれば + する + ほど"},{"w":"い형용사","f":"安ければ + 安い + ほど"},{"w":"な형용사","f":"静かなら + 静かな + ほど"}],"rule":["1. 1그룹 동사는 어미 う단을 え단으로 바꾸고 ば를 붙인다(読む→読めば). 2그룹은 る를 れば로(食べる→食べれば), する→すれば, 来る→来れば.","2. 그 뒤에 같은 동사의 사전형을 한 번 더 쓰고 ほど를 붙인다(読めば読むほど).","3. い형용사는 い를 ければ로 바꾼 뒤 사전형 + ほど(安ければ安いほど). いい는 よければいいほど.","4. な형용사는 なら(또는 であれば) 뒤에 な형 + ほど(静かなら静かなほど)."],"why":"조건의 ば와 정도를 나타내는 ほど를 이어, '~하면 그만큼 더'라는 비례 관계를 나타낸다.","nu":"앞뒤에 같은 단어를 반복한다. ば 부분을 빼고 ～ほど만 써도 같은 뜻이 된다(練習するほど上手になる). 뒷문장에는 정도가 변하는 내용이 온다. 회화·문어 모두 쓴다.","cmp":[{"g":"～ほど","d":"ば 부분을 생략한 형태로 뜻은 같고 더 간결하다."}],"ex":[{"jp":"日本語[にほんご]は勉強[べんきょう]すればするほど面白[おもしろ]くなる。","ko":"일본어는 공부하면 할수록 재미있어진다."},{"jp":"部屋[へや]は駅[えき]に近[ちか]ければ近[ちか]いほど高[たか]い。","ko":"방은 역에 가까우면 가까울수록 비싸다."},{"jp":"説明[せつめい]は簡単[かんたん]なら簡単[かんたん]なほどいい。","ko":"설명은 간단하면 간단할수록 좋다."}],"dr":[{"t":"make","q":"読む → ～ば～ほど","a":"読めば読むほど","hint":"む를 め로 바꾸고 ば, 뒤에 사전형 + ほど"},{"t":"make","q":"安い → ～ば～ほど","a":"安ければ安いほど","hint":"い를 ければ로 바꾸고, 뒤에 사전형 + ほど"},{"t":"fill","q":"考[かんが]えれば考[かんが]える（　）、わからなくなる。","a":"ほど","opts":["ほど","まで","ので","のに"]}],"src":["https://mlcjapanese.co.jp/n3_011.html","https://bunpro.jp/ja/grammar_points/ば-ほど"],"vf":1,"u":26,"g":1,"gp":"gg_N3_06"},{"id":"g3_096","t":"～ほど","ko":"~할 만큼, ~만큼 (~지 않다)","cat":"비교·정도","conn":[{"w":"동사 사전형","f":"泣く + ほど"},{"w":"동사 ない형","f":"数えきれない + ほど"},{"w":"い형용사","f":"痛い + ほど"},{"w":"명사","f":"山 + ほど / 去年 + ほど"}],"rule":["1. 동사·い형용사는 보통형 그대로 ほど를 붙인다(泣く→泣くほど).","2. 명사는 그대로 ほど를 붙인다(山ほど).","3. 'AはBほど～ない'는 'A는 B만큼 ~하지 않다'로, 뒤에 반드시 부정이 온다."],"why":"","nu":"정도 표현(泣くほどうれしい)은 과장된 비유로 많이 쓴다. 비교의 'Bほど～ない'는 뒤가 부정이어야 하며, 긍정 비교에는 より를 쓴다. 'Bほど～な명사はない'는 'B가 가장 ~하다'는 뜻.","cmp":[{"g":"～くらい","d":"정도 표현에서는 거의 같지만 더 회화적이고, '이 정도쯤(これくらい)'처럼 가벼운 정도에도 쓴다."}],"ex":[{"jp":"泣[な]くほどうれしかった。","ko":"울 만큼 기뻤다."},{"jp":"今年[ことし]の夏[なつ]は去年[きょねん]ほど暑[あつ]くない。","ko":"올여름은 작년만큼 덥지 않다."},{"jp":"宿題[しゅくだい]が山[やま]ほどある。","ko":"숙제가 산더미만큼 있다."}],"dr":[{"t":"make","q":"死ぬ／疲れた → ～ほど","a":"死ぬほど疲れた","hint":"사전형 + ほど + 정도"},{"t":"make","q":"今日は寒くない／昨日 (비교)","a":"今日は昨日ほど寒くない","hint":"비교 대상 + ほど + 부정"},{"t":"fill","q":"この店[みせ]のラーメンは、あの店[みせ]（　）おいしくない。","a":"ほど","opts":["ほど","ので","ながら","のに"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%BB%E3%81%A9%EF%BD%9E%E3%81%AA%E3%81%84","https://mlcjapanese.co.jp/n3_011.html"],"vf":1,"u":26,"g":1,"gp":"gg_N3_06"},{"id":"g3_101","t":"まるで～ようだ","ko":"마치 ~같다","cat":"비교·정도","conn":[{"w":"명사","f":"まるで + 夢の + ようだ"},{"w":"동사 보통형","f":"まるで + 知っている + ようだ"},{"w":"명사 수식","f":"まるで + 子供の + ような顔"},{"w":"동사 수식","f":"まるで + 本物の + ように見える"}],"rule":["1. 비유할 대상이 명사면 の를 붙인다(夢→夢の).","2. 동사는 보통형을 그대로 쓴다(知っている).","3. 뒤에 ようだ(문말)·ように(동사·형용사 수식)·ような(명사 수식)를 붙인다.","4. 앞에 まるで를 놓아 '마치'라는 비유임을 강조한다(まるで夢のようだ)."],"why":"","nu":"실제로는 그렇지 않지만 아주 닮았음을 강조한다. 회화에서는 みたい와 함께 쓰는 일이 많다(まるで夢みたい). まるで 뒤에 부정이 오면 '전혀 ~않다'(まるでわからない)라는 다른 용법이 된다.","cmp":[{"g":"まるで～みたいだ","d":"같은 뜻의 회화체. 명사에 の 없이 붙는다(夢みたい)."}],"ex":[{"jp":"合格[ごうかく]できたなんて、まるで夢[ゆめ]のようだ。","ko":"합격하다니 마치 꿈 같다."},{"jp":"彼[かれ]はまるで日本人[にほんじん]のように日本語[にほんご]を話[はな]す。","ko":"그는 마치 일본인처럼 일본어를 한다."},{"jp":"彼女[かのじょ]はまるで何[なに]も知[し]らないような顔[かお]をしている。","ko":"그녀는 마치 아무것도 모르는 듯한 얼굴을 하고 있다."}],"dr":[{"t":"make","q":"夢 → まるで～ようだ","a":"まるで夢のようだ","hint":"명사 + の + ようだ, 앞에 まるで"},{"t":"make","q":"子供／笑う → まるで～ように","a":"まるで子供のように笑う","hint":"명사 + の + ように + 동사"},{"t":"fill","q":"今日[きょう]は4月[しがつ]なのに、まるで夏[なつ]の（　）暑[あつ]い。","a":"ように","opts":["ように","ために","くせに","おかげで"]}],"src":["https://bunpro.jp/grammar_points/260"],"vf":1,"u":27,"g":1,"gp":"gg_N3_06"},{"id":"g3_113","t":"～のように (비유·예시)","ko":"~처럼, ~같이","cat":"비교·정도","conn":[{"w":"명사","f":"鳥 + の + ように"},{"w":"동사 보통형","f":"夢を見ている + ように"},{"w":"연체사","f":"この + ように"}],"rule":["1. 비유·예시의 대상이 명사이면 の를 넣어 のように를 붙인다(鳥 → 鳥のように).","2. 동사는 보통형에 그대로 ように를 붙인다.","3. 뒤에 동사·형용사가 오면 ように, 명사가 오면 ような를 쓴다(鳥のような声)."],"why":"","nu":"실제로는 그것이 아니지만 그것과 닮았다는 비유와, 해당하는 예를 드는 예시(東京のように人が多い町) 양쪽에 쓴다. 비유를 강조할 때는 まるで와 함께 쓴다. 회화에서는 みたいに를 많이 쓴다. 명사 앞에서 ように를 그대로 쓰는 실수에 주의.","cmp":[{"g":"～みたいに","d":"같은 뜻의 회화체. 명사에 の 없이 바로 붙는다(鳥みたいに)."}],"ex":[{"jp":"鳥[とり]のように空[そら]を飛[と]びたい。","ko":"새처럼 하늘을 날고 싶다."},{"jp":"彼[かれ]はまるで夢[ゆめ]を見[み]ているように、ぼんやりしていた。","ko":"그는 마치 꿈을 꾸고 있는 것처럼 멍하니 있었다."},{"jp":"東京[とうきょう]のように人[ひと]が多[おお]い町[まち]では、電車[でんしゃ]がとても便利[べんり]だ。","ko":"도쿄처럼 사람이 많은 도시에서는 전철이 아주 편리하다."}],"dr":[{"t":"make","q":"雪 → ～のように白い","a":"雪のように白い","hint":"명사 + の + ように"},{"t":"make","q":"本物 → ～のような花 (명사 앞)","a":"本物のような花","hint":"명사 앞에서는 ような"},{"t":"fill","q":"彼[かれ]は魚[さかな]の（　）上手[じょうず]に泳[およ]ぐ。","a":"ように","opts":["ように","ばかり","ままに","せいで"]}],"src":[],"vf":0,"u":27,"g":1,"gp":"gg_N3_06"},{"id":"g3_055","t":"～ということだ","ko":"~라고 한다, (즉) ~라는 것이다","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"来る + ということだ"},{"w":"い형용사","f":"難しい + ということだ"},{"w":"な형용사","f":"静かだ + ということだ"},{"w":"명사","f":"雨だ + ということだ"}],"rule":["1. 앞말은 바꾸지 않고 보통형 그대로 둔다(来る, 来た, 来ない 등).","2. 명사·な형용사는 보통 だ를 붙인 형태 뒤에 잇는다(雨だ, 静かだ).","3. 그 뒤에 という(~라고)를 붙인다.","4. 마지막에 ことだ를 붙인다. 정중하게는 ということです."],"why":"","nu":"두 가지로 쓴다. (1) 전문: 신문·뉴스·남에게서 들은 내용을 그대로 전할 때 '~라고 한다'. 다소 딱딱한 말투로, 회화에서는 ～そうだ·～って가 더 흔하다. (2) 결론·바꿔 말하기: 앞 내용을 정리해 '즉 ~라는 뜻이다'라고 할 때(つまり～ということだ).","cmp":[{"g":"～そうだ(전문)","d":"보통형 + そうだ도 '~라고 한다'. 회화에서 더 흔하며, ということだ는 정보를 인용해 전하는 느낌이 더 강하다."},{"g":"～ということは","d":"'~라는 것은 (곧) ~'처럼 앞 내용을 주제로 삼아 결론을 끌어낼 때 쓴다."}],"ex":[{"jp":"天気予報[てんきよほう]によると、明日[あした]は雨[あめ]だということだ。","ko":"일기 예보에 따르면 내일은 비가 온다고 한다."},{"jp":"山田[やまだ]さんは来月[らいげつ]結婚[けっこん]するということです。","ko":"야마다 씨는 다음 달 결혼한다고 합니다."},{"jp":"返事[へんじ]が来[こ]ないのは、つまり行[い]けないということだ。","ko":"답장이 안 온다는 건 즉 못 간다는 뜻이다."}],"dr":[{"t":"make","q":"彼は来る → ～ということだ","a":"彼は来るということだ","hint":"보통형 + ということだ"},{"t":"make","q":"試験は難しい → ～ということです","a":"試験は難しいということです","hint":"い형용사는 그대로 + ということです"},{"t":"fill","q":"ニュースによると、駅[えき]の前[まえ]に新[あたら]しい店[みせ]ができる（　）。","a":"ということだ","opts":["ということだ","ことにする","ところだ","わけがない"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%84%E3%81%86%E3%81%93%E3%81%A8%E3%81%A0"],"vf":1,"u":27,"g":1,"gp":"gg_N3_06"},{"id":"g3_082","t":"～によれば","ko":"~에 의하면","cat":"추량·전문","conn":[{"w":"명사(정보의 출처)","f":"天気予報 + によれば"}],"rule":["1. 정보의 출처인 명사(뉴스, 예보, 사람 등) 뒤에 によれば를 붙인다.","2. 문장 끝은 そうだ・らしい・ということだ 같은 전문(들은 말) 표현으로 맺는다.","3. 같은 뜻으로 によると를 써도 된다."],"why":"","nu":"회화와 문장 모두에 쓰며, によると가 조금 더 흔하다. 남에게서 들은 정보를 전하는 표현이므로 문장 끝을 단정형(雨だ)으로 끝내면 부자연스럽다. 한국어 '~에 의하면 ~래'처럼 끝을 そうだ 등으로 맞추는 것이 핵심이다.","cmp":[{"g":"～によると","d":"뜻과 쓰임이 같다. 회화에서 더 자주 쓴다."},{"g":"～によって","d":"따라 다름·원인·수단. 정보 출처의 뜻은 없다."}],"ex":[{"jp":"天気予報[てんきよほう]によれば、明日[あした]は雨[あめ]だそうだ。","ko":"일기예보에 의하면 내일은 비가 온대."},{"jp":"ニュースによれば、事故[じこ]で電車[でんしゃ]が遅[おく]れているらしい。","ko":"뉴스에 의하면 사고로 전철이 늦어지고 있는 것 같다."},{"jp":"先生[せんせい]の話[はなし]によれば、試験[しけん]は来週[らいしゅう]だということです。","ko":"선생님 말씀에 의하면 시험은 다음 주라고 합니다."}],"dr":[{"t":"make","q":"新聞 → ～物価が上がるそうだ","a":"新聞によれば物価が上がるそうだ","hint":"출처 명사 + によれば ... そうだ"},{"t":"make","q":"天気予報によれば、明日は晴れる（전문 표현으로 끝맺기）","a":"天気予報によれば、明日は晴れるそうだ","hint":"끝을 そうだ로"},{"t":"fill","q":"田中[たなか]さんの話[はなし]（　）、山田[やまだ]さんは来月[らいげつ]結婚[けっこん]するそうだ。","a":"によれば","opts":["によれば","にとって","に対して","にかわって"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%AB%E3%82%88%E3%82%8B%E3%81%A8-%E3%81%AB%E3%82%88%E3%82%8C%E3%81%B0"],"vf":1,"u":28,"g":1,"gp":"gg_N3_06"},{"id":"g3_089","t":"～はずだ","ko":"(당연히) ~일 것이다, ~할 터이다","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"着いた + はずだ"},{"w":"い형용사","f":"寒い + はずだ"},{"w":"な형용사","f":"静かな + はずだ"},{"w":"명사","f":"休みの + はずだ"}],"rule":["1. 동사·い형용사는 보통형 뒤에 はずだ를 붙인다. 과거는 동사를 た형으로 바꾼다(着く → 着いた + はずだ, く가 い로 바뀌는 イ음편).","2. な형용사는 な를 넣고(静かなはずだ), 명사는 の를 넣는다(休みのはずだ).","3. 정중형은 はずです, 부정은 はずがない(그럴 리 없다)를 쓴다."],"why":"","nu":"근거(시간표, 사실, 들은 이야기 등)를 바탕으로 '당연히 그럴 것'이라고 확신할 때 쓴다. 근거 없는 추측에는 だろう・と思う가 자연스럽다. 자기 의지로 하는 일(私は明日行くはずだ)에는 보통 쓰지 않는다. 한국어 '~할 거야'를 모두 はずだ로 옮기지 않도록 주의한다.","cmp":[{"g":"～だろう","d":"막연한 추측. はずだ는 근거가 있는 확신."},{"g":"～べきだ","d":"'마땅히 ~해야 한다'는 당위. はずだ는 예상."}],"ex":[{"jp":"電車[でんしゃ]は十時[じゅうじ]に出[で]たから、もう着[つ]いたはずだ。","ko":"전철은 10시에 출발했으니까 이미 도착했을 거다."},{"jp":"北海道[ほっかいどう]は今[いま]、寒[さむ]いはずです。","ko":"홋카이도는 지금 추울 겁니다."},{"jp":"今日[きょう]は日曜日[にちようび]だから、銀行[ぎんこう]は休[やす]みのはずだ。","ko":"오늘은 일요일이니까 은행은 쉬는 날일 거다."}],"dr":[{"t":"make","q":"書く → ～はずだ（과거）","a":"書いたはずだ","hint":"く → いた (イ음편) + はずだ"},{"t":"make","q":"元気だ → ～はずだ","a":"元気なはずだ","hint":"な형용사는 な + はずだ"},{"t":"fill","q":"薬[くすり]を飲[の]んだから、もうすぐ熱[ねつ]が下[さ]がる（　）。","a":"はずだ","opts":["はずだ","べきだ","ばかりだ","わけにはいかない"]}],"src":["https://www.mlcjapanese.co.jp/n3_04_09.html","https://jlptsensei.com/learn-japanese-grammar/%E3%81%AF%E3%81%9A%E3%81%A0-hazu-da-meaning/"],"vf":1,"u":28,"g":1,"gp":"gg_N3_07"},{"id":"g3_103","t":"～みたいだ","ko":"~인 것 같다, ~같다","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"降った + みたいだ"},{"w":"い형용사","f":"古い + みたいだ"},{"w":"な형용사","f":"暇 + みたいだ"},{"w":"명사","f":"子供 + みたいだ"}],"rule":["1. 동사·い형용사는 보통형 그대로 みたいだ를 붙인다. 예: 降る→降った(る가 った로 바뀜)→降ったみたいだ.","2. な형용사와 명사는 な·だ 없이 바로 붙인다(暇みたいだ, 子供みたいだ).","3. 명사를 꾸밀 때는 みたいな, 동사·형용사를 꾸밀 때는 みたいに로 바꾼다."],"why":"","nu":"ようだ의 회화체. 보거나 들은 근거로 하는 추측(~인 것 같다), 비유(~같다), 예시(東京みたいな大都市)에 쓴다. '暇なみたいだ'처럼 な를 넣는 것은 틀린 형태다. 정중하게는 みたいです.","cmp":[{"g":"～ようだ","d":"같은 뜻으로 더 격식·문어적. 명사에는 の를 넣는다(子供のようだ)."},{"g":"～らしい","d":"주로 전해 들은 정보에 근거한 추측."}],"ex":[{"jp":"道[みち]がぬれている。雨[あめ]が降[ふ]ったみたいだ。","ko":"길이 젖어 있다. 비가 온 것 같다."},{"jp":"田中[たなか]さんは今日[きょう]は暇[ひま]みたいだ。","ko":"다나카 씨는 오늘 한가한 것 같다."},{"jp":"彼[かれ]は子供[こども]みたいに笑[わら]った。","ko":"그는 아이처럼 웃었다."}],"dr":[{"t":"make","q":"降る (과거) → ～みたいだ","a":"降ったみたいだ","hint":"る를 った로 + みたいだ"},{"t":"make","q":"静か → ～みたいだ","a":"静かみたいだ","hint":"な형용사는 어간 + みたいだ(な 없음)"},{"t":"fill","q":"部屋[へや]が暗[くら]い。彼[かれ]はもう寝[ね]た（　）だ。","a":"みたい","opts":["みたい","べき","ので","ながら"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%BF%E3%81%9F%E3%81%84"],"vf":1,"u":28,"g":1,"gp":"gg_N3_07"},{"id":"g3_106","t":"もしかすると～かもしれない","ko":"어쩌면 ~일지도 모른다","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"降る + かもしれない"},{"w":"い형용사","f":"寒い + かもしれない"},{"w":"な형용사","f":"暇 + かもしれない"},{"w":"명사","f":"病気 + かもしれない"}],"rule":["1. 문장 앞에 もしかすると를 놓는다.","2. 동사·い형용사는 보통형 그대로 かもしれない를 붙인다(降る→降るかもしれない).","3. な형용사·명사는 だ 없이 바로 붙인다(暇かもしれない, 病気かもしれない)."],"why":"","nu":"가능성이 그다지 높지 않은 추측을 강조한다. もしかしたら·もしかして도 같은 뜻으로, 더 회화적이다. 정중형은 かもしれません, 회화에서는 かも로 줄이기도 한다.","cmp":[{"g":"～だろう／でしょう","d":"가능성이 더 높다고 보는 추측."}],"ex":[{"jp":"もしかすると、明日[あした]は雨[あめ]が降[ふ]るかもしれない。","ko":"어쩌면 내일은 비가 올지도 모른다."},{"jp":"もしかすると、彼[かれ]はもう帰[かえ]ったかもしれない。","ko":"어쩌면 그는 벌써 돌아갔을지도 모른다."},{"jp":"もしかすると、その話[はなし]は本当[ほんとう]かもしれません。","ko":"어쩌면 그 이야기는 사실일지도 모릅니다."}],"dr":[{"t":"make","q":"遅れる → もしかすると～かもしれない","a":"もしかすると遅れるかもしれない","hint":"사전형 + かもしれない"},{"t":"make","q":"病気 → もしかすると～かもしれない","a":"もしかすると病気かもしれない","hint":"명사 + かもしれない(だ 없음)"},{"t":"fill","q":"もしかすると、彼[かれ]は来[こ]ない（　）。","a":"かもしれない","opts":["かもしれない","べきだ","ことにする","ようにする"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%82%82%E3%81%97%E3%81%8B%E3%81%97%E3%81%9F%E3%82%89"],"vf":1,"u":29,"g":1,"gp":"gg_N3_07"},{"id":"g3_118","t":"～らしい","ko":"~라고 한다, ~인 것 같다","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"降る + らしい"},{"w":"い형용사","f":"おいしい + らしい"},{"w":"な형용사","f":"静か + らしい (だ 없이)"},{"w":"명사","f":"雪 + らしい (だ 없이)"}],"rule":["1. 동사·い형용사는 보통형에 그대로 らしい를 붙인다(降るらしい).","2. 명사·な형용사는 だ를 빼고 らしい를 붙인다(雪だ → 雪らしい).","3. 과거는 앞부분을 과거로 만든다(雪だった → 雪だったらしい)."],"why":"","nu":"들은 정보나 간접적인 근거를 바탕으로 한 추측을 나타낸다. 자기 눈으로 직접 보고 판단할 때는 ようだ·みたいだ가 자연스럽다. 명사 + らしい에는 '~답다'(男らしい, 学生らしい)라는 다른 용법도 있으니 문맥으로 구별한다. 정중하게는 らしいです.","cmp":[{"g":"～そうだ(전문)","d":"들은 내용을 그대로 전한다. 명사·な형용사는 だそうだ."},{"g":"～ようだ","d":"직접 보거나 느낀 근거로 추측할 때 주로 쓴다."}],"ex":[{"jp":"明日[あした]は雪[ゆき]らしい。","ko":"내일은 눈이 온다고 한다."},{"jp":"駅前[えきまえ]の新[あたら]しいレストランはおいしいらしいよ。","ko":"역 앞의 새 레스토랑은 맛있대."},{"jp":"田中[たなか]さんは来月[らいげつ]会社[かいしゃ]を辞[や]めるらしい。","ko":"다나카 씨는 다음 달 회사를 그만둔다고 한다."}],"dr":[{"t":"make","q":"雨だ → ～らしい","a":"雨らしい","hint":"명사는 だ를 빼고 らしい"},{"t":"make","q":"休みだった → ～らしい","a":"休みだったらしい","hint":"과거 だった는 남기고 らしい"},{"t":"fill","q":"ニュースによると、明日[あした]は台風[たいふう]が来[く]る（　）。","a":"らしい","opts":["らしい","ように","ばかり","まま"]}],"src":[],"vf":0,"u":29,"g":1,"gp":"gg_N3_07"},{"id":"g3_121","t":"～わけがない","ko":"~일 리가 없다","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"知らない + わけがない"},{"w":"い형용사","f":"まずい + わけがない"},{"w":"な형용사","f":"簡単な + わけがない"},{"w":"명사","f":"本物 + の / である + わけがない"}],"rule":["1. 동사·い형용사는 보통형 그대로 뒤에 わけ를 붙인다(まずい → まずいわけ).","2. な형용사는 だ를 な로 바꾸고, 명사는 の 또는 である를 넣는다(簡単だ → 簡単なわけ).","3. わけ 뒤에 조사 が와 ない를 붙인다(まずいわけがない).","4. 회화에서는 が를 빼고 わけない라고도 한다."],"why":"","nu":"말하는 사람이 강하게 확신하고 그럴 가능성을 완전히 부정할 때 쓴다. 주관적이고 감정이 실린 말이라 윗사람 앞에서는 조심한다. 부분 부정인 わけではない와 헷갈리지 않도록 주의.","cmp":[{"g":"～はずがない","d":"뜻이 거의 같다. 근거를 바탕으로 따져서 '그럴 리 없다'고 판단하는 느낌."},{"g":"～わけではない","d":"'전부 그런 것은 아니다'라는 부분 부정."}],"ex":[{"jp":"あんなに練習[れんしゅう]したんだから、負[ま]けるわけがない。","ko":"그렇게 연습했으니까 질 리가 없다."},{"jp":"いつも行列[ぎょうれつ]ができる店[みせ]だから、まずいわけがない。","ko":"늘 줄이 생기는 가게니까 맛없을 리가 없다."},{"jp":"一日[いちにち]で覚[おぼ]えられるほど、日本語[にほんご]が簡単[かんたん]なわけがない。","ko":"하루 만에 외울 수 있을 만큼 일본어가 쉬울 리가 없다."}],"dr":[{"t":"make","q":"知る(부정) → ～わけがない","a":"知らないわけがない","hint":"る를 ら로 바꾸고 ない + わけがない"},{"t":"make","q":"暇だ → ～わけがない","a":"暇なわけがない","hint":"だ를 な로 + わけがない"},{"t":"fill","q":"彼[かれ]は正直[しょうじき]な人[ひと]だから、うそをつく（　）。","a":"わけがない","opts":["わけがない","わけだ","ことにする","ようになる"]}],"src":[],"vf":0,"u":29,"g":1,"gp":"gg_N3_07"},{"id":"g3_126","t":"～んだって","ko":"~래, ~라던데","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"行く + んだって"},{"w":"い형용사","f":"面白い + んだって"},{"w":"な형용사","f":"有名な + んだって"},{"w":"명사","f":"歌手 + な + んだって"}],"rule":["1. 동사·い형용사는 보통형 그대로 んだって를 붙인다(行くんだって).","2. 명사·な형용사는 だ를 な로 바꾸고 んだって를 붙인다(歌手だ → 歌手なんだって).","3. 과거는 앞부분을 과거로 만든다(行ったんだって)."],"why":"설명의 のだ(회화체 んだ)에 인용의 って가 붙은 형태다.","nu":"친한 사이에서 쓰는 회화체 전문 표현이다. 격식 있는 자리에서는 ～そうです를 쓴다. 끝을 올려 말하면 '~래?' 하고 들은 내용을 확인하는 질문이 된다.","cmp":[{"g":"～そうだ(전문)","d":"정중한 말이나 글에도 쓴다. 명사·な형용사는 だそうだ."}],"ex":[{"jp":"田中[たなか]さん、来月[らいげつ]東京[とうきょう]に引[ひ]っ越[こ]すんだって。","ko":"다나카 씨, 다음 달에 도쿄로 이사한대."},{"jp":"あの映画[えいが]、すごく面白[おもしろ]いんだって。","ko":"그 영화 엄청 재미있대."},{"jp":"山田[やまだ]さんのお姉[ねえ]さん、有名[ゆうめい]な歌手[かしゅ]なんだって。","ko":"야마다 씨 언니가 유명한 가수래."}],"dr":[{"t":"make","q":"休みだ → ～んだって","a":"休みなんだって","hint":"だ를 な로 + んだって"},{"t":"make","q":"結婚した → ～んだって","a":"結婚したんだって","hint":"과거형 그대로 + んだって"},{"t":"fill","q":"明日[あした]、テストがある（　）。知[し]ってた？","a":"んだって","opts":["んだって","ように","ばかり","わりに"]}],"src":[],"vf":0,"u":29,"g":1,"gp":"gg_N3_07"},{"id":"g3_010","t":"～きり","ko":"~만, ~한 채로 (그 뒤로 계속)","cat":"강조·한정","conn":[{"w":"동사 た형","f":"出かける → 出かけた + きり"},{"w":"명사·수량","f":"二人 + きり / 一度 + きり"},{"w":"지시어","f":"それ + っきり"}],"rule":["1. 동사는 た형으로 바꾼다: 2그룹은 る를 た로(出かける → 出かけた), 1그룹은 음편(行く → 行った).","2. た형 뒤에 きり를 붙인다(出かけたきり).","3. 뒤에는 그 뒤로 이어지지 않는 상태(~ない, ~ている)가 온다(帰ってこない).","4. 명사·수량에는 그대로 붙여 '~만'을 뜻한다(二人きり)."],"why":"'끊다'라는 뜻의 동사 切る(きる)에서 나온 말로, 거기서 끊겨 더 이어지지 않는다는 뜻이다.","nu":"たきり는 '~한 것을 마지막으로 그 뒤 기대한 일이 없다'는 뜻으로 뒤에 부정·지속 표현이 온다. 회화에서는 っきり(行ったっきり, それっきり)가 많다. 명사 + きり는 한정('~뿐')이다.","cmp":[{"g":"～たまま","d":"たまま는 어떤 상태가 그대로 유지됨(窓を開けたまま寝た). たきり는 그 일 이후로 다음 일이 일어나지 않음."}],"ex":[{"jp":"兄[あに]は朝[あさ]出[で]かけたきり、まだ帰[かえ]ってこない。","ko":"형은 아침에 나간 채로 아직 돌아오지 않는다."},{"jp":"彼女[かのじょ]とは卒業式[そつぎょうしき]で会[あ]ったきりだ。","ko":"그녀와는 졸업식에서 만난 것이 마지막이다."},{"jp":"部屋[へや]で二人[ふたり]きりになった。","ko":"방에서 둘만 남게 되었다."}],"dr":[{"t":"make","q":"行く → ～きり","a":"行ったきり","hint":"く는 촉음편 った로 바꾸고 きり"},{"t":"make","q":"寝る → ～きり","a":"寝たきり","hint":"2그룹은 る를 た로 바꾸고 きり"},{"t":"fill","q":"彼[かれ]は去年[きょねん]電話[でんわ]をくれた（　）、連絡[れんらく]がない。","a":"きり","opts":["きり","ばかり","ながら","ほど"]}],"src":["https://www.mlcjapanese.co.jp/n3_004.html","https://bunpro.jp/grammar_points/309"],"vf":1,"u":30,"g":1,"gp":"gg_N3_07"},{"id":"g3_014","t":"～こそ","ko":"~야말로, 바로 ~","cat":"강조·한정","conn":[{"w":"명사","f":"今度 + こそ"},{"w":"명사 + 조사","f":"あなたに + こそ"},{"w":"이유 から","f":"好きだから + こそ"}],"rule":["1. こそ는 형태가 바뀌지 않으며 강조하고 싶은 명사 바로 뒤에 붙인다.","2. は・を 자리에서는 그 조사를 빼고 こそ로 바꾼다(今度は → 今度こそ). が는 빼거나 こそが처럼 뒤에 남기기도 한다(健康こそが大切だ).","3. 이유를 강조할 때는 から 뒤에 붙인다(好きだからこそ)."],"why":"","nu":"여러 가운데 '바로 그것'이라고 강하게 내세울 때 쓴다(今年こそ合格したい: 올해야말로 합격하고 싶다). 인사에서 'こちらこそ(저야말로)'로 자주 쓴다. 나쁜 의미의 강조에는 잘 쓰지 않는다. ×今度はこそ처럼 は와 겹쳐 쓰지 않는다.","cmp":[{"g":"～は","d":"주제를 내세울 뿐 강조의 힘이 약하다. こそ는 '다른 것이 아니라 바로 이것'이라는 강한 강조."}],"ex":[{"jp":"今度[こんど]こそ試合[しあい]に勝[か]ちたい。","ko":"이번에야말로 시합에서 이기고 싶다."},{"jp":"A：よろしくお願[ねが]いします。B：こちらこそ、よろしくお願[ねが]いします。","ko":"A: 잘 부탁드립니다. B: 저야말로 잘 부탁드립니다."},{"jp":"あなたのことが心配[しんぱい]だからこそ言[い]っているんです。","ko":"당신이 걱정되니까 하는 말이에요."}],"dr":[{"t":"make","q":"明日は早く起きる → ～こそ","a":"明日こそ早く起きる","hint":"は를 빼고 그 자리에 こそ를 넣는다."},{"t":"make","q":"大切だから → ～こそ","a":"大切だからこそ","hint":"이유를 강조할 때는 から 뒤에 こそ."},{"t":"fill","q":"去年[きょねん]は失敗[しっぱい]したが、今年[ことし]（　）合格[ごうかく]したい。","a":"こそ","opts":["こそ","しか","ほど","まで"]}],"src":["https://nihongokyoshi-net.com/2018/06/02/jlptn3-grammar-koso/"],"vf":1,"u":30,"g":1,"gp":"gg_N3_07"},{"id":"g3_022","t":"～さえ","ko":"~조차, ~마저","cat":"강조·한정","conn":[{"w":"명사","f":"ひらがな → ひらがなさえ"},{"w":"명사(주어)","f":"先生 → 先生でさえ"},{"w":"명사 + 조사","f":"親に → 親にさえ"},{"w":"동사 ます형","f":"泣く → 泣きさえする"}],"rule":["1. 명사 뒤에 さえ를 붙인다(ひらがなさえ).","2. が·を 자리에서는 그 조사를 빼고 さえ만 쓴다(ひらがなを → ひらがなさえ).","3. に·と·から 같은 조사는 남기고 그 뒤에 붙인다(親にさえ).","4. 주어를 강조할 때는 でさえ도 많이 쓴다(先生でさえ)."],"why":"","nu":"극단적인 예 하나를 들어 '그것조차 그러니 다른 것은 말할 것도 없다'는 함의를 준다. 부정이나 부정적인 문맥에서 많이 쓴다. 「～さえ～ば」(~만 ~하면)는 조건을 나타내는 별도 문형이다. 회화에서는 も·だって로도 비슷하게 말한다.","cmp":[{"g":"～すら","d":"뜻은 거의 같지만 더 문어적이다."},{"g":"～も","d":"'~도'로 가볍다. さえ는 '그런 것조차'라는 의외성이 강하다."}],"ex":[{"jp":"忙[いそが]しくて、昼[ひる]ご飯[はん]を食[た]べる時間[じかん]さえなかった。","ko":"바빠서 점심 먹을 시간조차 없었다."},{"jp":"この問題[もんだい]は先生[せんせい]でさえ解[と]けなかった。","ko":"이 문제는 선생님조차 풀지 못했다."},{"jp":"彼[かれ]は親[おや]にさえ何[なに]も話[はな]さなかった。","ko":"그는 부모에게조차 아무것도 말하지 않았다."}],"dr":[{"t":"make","q":"水がない → ～さえ","a":"水さえない","hint":"が를 빼고 명사 + さえ"},{"t":"make","q":"子どもがわかる → ～でさえ","a":"子どもでさえわかる","hint":"주어 명사 + でさえ"},{"t":"fill","q":"疲[つか]れて、立[た]つこと（　）できなかった。","a":"さえ","opts":["さえ","ばかり","ほど","より"]}],"src":["https://bunpro.jp/grammar_points/さえ"],"vf":1,"u":30,"g":1,"gp":"gg_N3_07"},{"id":"g3_032","t":"～だけしか～ない","ko":"~만밖에 ~않다, 겨우 ~뿐","cat":"강조·한정","conn":[{"w":"명사","f":"肉 → 肉だけしか食べない"},{"w":"수량","f":"千円 → 千円だけしかない"}],"rule":["1. 명사·수량 뒤에 だけ를 붙인다(千円だけ).","2. 그 뒤에 しか를 붙인다(千円だけしか).","3. 술어는 반드시 부정형으로 끝낸다(ない, 食べない, できなかった)."],"why":"だけ(~만)와 しか(~밖에)를 겹쳐 한정의 뜻을 더 강하게 한 꼴이다.","nu":"しか～ない보다 '그것뿐'이라는 적음·부족함을 더 강조한다. 회화에서 많이 쓴다. しか가 들어가므로 술어를 긍정형으로 쓰면 틀린다(×千円だけしかある).","cmp":[{"g":"～しか～ない","d":"같은 뜻의 기본형. だけしか는 강조가 더 세다."},{"g":"～だけ","d":"긍정문에 쓰는 '~만'(千円だけある)."}],"ex":[{"jp":"今日[きょう]は一時間[いちじかん]だけしか勉強[べんきょう]できなかった。","ko":"오늘은 한 시간밖에 공부하지 못했다."},{"jp":"財布[さいふ]に千円[せんえん]だけしかない。","ko":"지갑에 천 엔뿐이다."},{"jp":"彼[かれ]は肉[にく]だけしか食[た]べない。","ko":"그는 고기만 먹는다(고기밖에 안 먹는다)."}],"dr":[{"t":"make","q":"一人 ／ 来た → ～だけしか","a":"一人だけしか来なかった","hint":"だけしか 뒤 술어를 부정형으로(来なかった)"},{"t":"make","q":"水 ／ 飲む → ～だけしか","a":"水だけしか飲まない","hint":"명사 + だけしか + ない형"},{"t":"fill","q":"時間[じかん]がなくて、五分[ごふん]だけ（　）寝[ね]られなかった。","a":"しか","opts":["しか","も","さえ","まで"]}],"src":["https://bunpro.jp/grammar_points/489"],"vf":1,"u":31,"g":1,"gp":"gg_N3_07"},{"id":"g3_068","t":"どんなに～ことか","ko":"얼마나 ~했는지 (모른다), 정말 ~하다","cat":"강조·한정","conn":[{"w":"동사 보통형","f":"どんなに + 心配した + ことか"},{"w":"い형용사","f":"どんなに + うれしい + ことか"},{"w":"な형용사","f":"どんなに + 大変な + ことか"}],"rule":["1. 문장 앞쪽에 どんなに를 놓는다.","2. 동사는 보통형으로 쓴다. 지난 일이면 た형으로 바꾼다(心配する → 心配した).","3. い형용사는 그대로, な형용사는 な를 붙인 형태로 쓴다(大変な).","4. 끝에 ことか를 붙여 감탄으로 맺는다(どんなに心配したことか)."],"why":"","nu":"정도가 아주 크다는 마음을 감정을 담아 강하게 말하는 표현. 의문문이 아니라 감탄이다. 다소 문어적이고 감정적인 표현으로, 편지나 진심을 말하는 장면에 어울린다. どんなに 대신 どれほど·どれだけ·なんと를 쓰기도 한다.","cmp":[{"g":"どんなに～ても","d":"'아무리 ~해도'. 양보의 뜻으로, 감탄인 ことか와 전혀 다르다."}],"ex":[{"jp":"連絡[れんらく]がなくて、どんなに心配[しんぱい]したことか。","ko":"연락이 없어서 얼마나 걱정했는지 몰라."},{"jp":"合格[ごうかく]の知[し]らせを聞[き]いて、どんなにうれしかったことか。","ko":"합격 소식을 듣고 얼마나 기뻤는지 모른다."},{"jp":"一人[ひとり]で子[こ]どもを育[そだ]てるのは、どんなに大変[たいへん]なことか。","ko":"혼자서 아이를 키우는 것은 얼마나 힘든 일인지 모른다."}],"dr":[{"t":"make","q":"待つ → どんなに～ことか (과거)","a":"どんなに待ったことか","hint":"つ → った + ことか"},{"t":"make","q":"うれしい → どんなに～ことか","a":"どんなにうれしいことか","hint":"い형용사 그대로 + ことか"},{"t":"fill","q":"あなたに会[あ]える日[ひ]を、どんなに楽[たの]しみにしていた（　）。","a":"ことか","opts":["ことか","ものの","ばかりか","ように"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%93%E3%81%A8%E3%81%8B"],"vf":1,"u":31,"g":1,"gp":"gg_N3_07"},{"id":"g3_087","t":"～ばかり","ko":"~만, ~뿐 (그것만 함)","cat":"강조·한정","conn":[{"w":"명사","f":"ゲーム + ばかり"},{"w":"동사 て형","f":"寝て + ばかり + いる"}],"rule":["1. 명사 뒤에 ばかり를 붙인다. 이때 を・が는 빠진다(ゲームをする → ゲームばかりする).","2. 계속 반복되는 일에는 ゲームばかりしている처럼 ている와 함께 쓴다.","3. 동사 자체를 '그것만 한다'고 할 때는 て형 + ばかりいる로 만든다(寝る → 寝てばかりいる).","4. に・で 등 다른 조사는 남겨 둔다(テレビでばかり / 友達とばかり)."],"why":"","nu":"'그것만 하고 다른 것은 안 한다'는 뜻으로, 불만이나 비판의 느낌이 담기는 일이 많다(ゲームばかりしている). 회화와 문장 모두에 쓴다. た형 + ばかり(食べたばかり, '막 ~했다')는 뜻이 전혀 다른 문형이므로 구별해야 한다.","cmp":[{"g":"～だけ","d":"단순한 한정 '~만'. ばかり는 같은 것이 반복·많이 있다는 느낌과 불만이 담긴다."},{"g":"～たばかり","d":"た형에 붙어 '막 ~했다'. 한정의 ばかり와 다른 문형."}],"ex":[{"jp":"弟[おとうと]はゲームばかりしている。","ko":"남동생은 게임만 하고 있다."},{"jp":"休[やす]みの日[ひ]は寝[ね]てばかりいる。","ko":"쉬는 날에는 잠만 자고 있다."},{"jp":"この店[みせ]は高[たか]いものばかりだ。","ko":"이 가게는 비싼 것뿐이다."}],"dr":[{"t":"make","q":"甘いものを食べている → ～ばかり","a":"甘いものばかり食べている","hint":"を를 빼고 명사 + ばかり"},{"t":"make","q":"遊ぶ → ～ばかりいる","a":"遊んでばかりいる","hint":"て형(遊んで) + ばかりいる"},{"t":"fill","q":"彼[かれ]は文句[もんく]（　）言[い]って、何[なに]も手伝[てつだ]わない。","a":"ばかり","opts":["ばかり","まで","より","ほど"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/てばかりいる-te-bakari-iru-meaning/","https://bunpro.jp/ja/grammar_points/%E3%81%B0%E3%81%8B%E3%82%8A"],"vf":1,"u":31,"g":1,"gp":"gg_N3_07"},{"id":"g3_088","t":"～ばかりか～も","ko":"~뿐만 아니라 ~도","cat":"강조·한정","conn":[{"w":"명사","f":"英語 + ばかりか"},{"w":"동사 보통형","f":"遅れた + ばかりか"},{"w":"い형용사","f":"安い + ばかりか"},{"w":"な형용사","f":"きれいな + ばかりか"}],"rule":["1. 명사는 바로 뒤에 ばかりか를 붙인다(英語ばかりか).","2. 동사·い형용사는 보통형, な형용사는 な형 뒤에 붙인다(安いばかりか, きれいなばかりか).","3. 뒤 문장에는 も・まで・さえ를 넣어 더 큰 것을 덧붙인다(中国語も話せる)."],"why":"","nu":"'A만이 아니라 그보다 더한 B까지'라는 뜻으로 놀람·감탄이나 불만을 담는다. 다소 문어적이며 회화에서는 ～だけじゃなくて를 많이 쓴다. 뒤 문장에 명령·의뢰·권유는 오지 않는다. 명사 뒤에 だ를 넣지 않는다(英語だばかりか ×).","cmp":[{"g":"～だけでなく","d":"뜻은 같지만 중립적이고 뒤에 의지·권유도 올 수 있다."},{"g":"～ばかり","d":"'~만'(한정). ばかりか는 '~뿐 아니라'(첨가)."}],"ex":[{"jp":"彼女[かのじょ]は英語[えいご]ばかりか、中国語[ちゅうごくご]も話[はな]せる。","ko":"그녀는 영어뿐만 아니라 중국어도 할 줄 안다."},{"jp":"この店[みせ]は安[やす]いばかりか、味[あじ]もいい。","ko":"이 가게는 쌀 뿐만 아니라 맛도 좋다."},{"jp":"彼[かれ]は遅[おく]れて来[き]たばかりか、宿題[しゅくだい]も忘[わす]れた。","ko":"그는 늦게 왔을 뿐만 아니라 숙제도 잊어버렸다."}],"dr":[{"t":"make","q":"子ども → ～大人も楽しめる","a":"子どもばかりか大人も楽しめる","hint":"명사 + ばかりか ... も"},{"t":"make","q":"便利だ → ～値段も安い","a":"便利なばかりか値段も安い","hint":"な형용사는 な + ばかりか"},{"t":"fill","q":"風邪[かぜ]をひいた（　）、財布[さいふ]までなくしてしまった。","a":"ばかりか","opts":["ばかりか","にしては","によって","について"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/ばかりか-bakari-ka-meaning"],"vf":1,"u":32,"g":1,"gp":"gg_N3_08"},{"id":"g3_092","t":"～はもちろん～も","ko":"~은 물론 ~도","cat":"강조·한정","conn":[{"w":"명사","f":"子供 + はもちろん、大人 + も"},{"w":"명사 + 조사","f":"日本で + はもちろん、海外で + も"}],"rule":["1. 당연히 포함되는 것을 명사1로 놓고 はもちろん을 붙인다(肉はもちろん).","2. 쉼표 뒤에 추가되는 명사2를 놓고 も를 붙인다(魚も).","3. 그 뒤에 두 명사에 공통되는 술어를 쓴다(好きだ, 人気がある 등)."],"why":"","nu":"명사1은 당연히 포함되는 것을 놓고, 명사2에 같은 정도로 해당되는 것을 덧붙인다. も 대신 まで를 쓰기도 한다(子供はもちろん大人まで). 회화적인 표현이며, 더 딱딱하게는 はもとより.","cmp":[{"g":"～はもとより～も","d":"뜻은 같지만 더 딱딱한 문어체."},{"g":"～だけでなく～も","d":"단순히 추가할 뿐, '당연히'라는 뉘앙스가 없다."}],"ex":[{"jp":"この歌[うた]は子供[こども]はもちろん、大人[おとな]にも人気[にんき]がある。","ko":"이 노래는 아이는 물론 어른에게도 인기가 있다."},{"jp":"彼[かれ]は英語[えいご]はもちろん、中国語[ちゅうごくご]も話[はな]せる。","ko":"그는 영어는 물론 중국어도 할 수 있다."},{"jp":"この店[みせ]は週末[しゅうまつ]はもちろん、平日[へいじつ]も混[こ]んでいる。","ko":"이 가게는 주말은 물론 평일에도 붐빈다."}],"dr":[{"t":"make","q":"肉が好き／魚も好き (はもちろん으로 잇기)","a":"肉はもちろん、魚も好き","hint":"명사1 + はもちろん、명사2 + も"},{"t":"make","q":"夏は暑い／春も暑い (はもちろん으로 잇기)","a":"夏はもちろん、春も暑い","hint":"당연한 쪽을 앞에 + はもちろん"},{"t":"fill","q":"夏[なつ]（　）、冬[ふゆ]もこの山[やま]には人[ひと]が多[おお]い。","a":"はもちろん","opts":["はもちろん","しか","さえ","ばかり"]}],"src":["https://nihongokyoshi-net.com/2019/05/23/jlptn3-grammar-mochiron/","https://bunpro.jp/ja/grammar_points/%E3%81%AF%E3%82%82%E3%81%A1%E3%82%8D%E3%82%93"],"vf":1,"u":32,"g":1,"gp":"gg_N3_08"},{"id":"g3_130","t":"必ずしも～とは限らない","ko":"반드시 ~인 것은 아니다","cat":"강조·한정","conn":[{"w":"동사 보통형","f":"必ずしも 勝つ + とは限らない"},{"w":"い형용사","f":"必ずしも 正しい + とは限らない"},{"w":"な형용사","f":"必ずしも 便利(だ) + とは限らない"},{"w":"명사","f":"必ずしも 本物(だ) + とは限らない"}],"rule":["1. 말하려는 판단 문장을 보통형으로 만든다(高い物が良い).","2. 술어 앞에 부사 必ずしも를 넣는다(高い物が必ずしも良い).","3. 문장 끝에 とは限らない를 붙여 '늘 그렇지는 않다'는 부분부정으로 만든다. 명사·な형용사는 だ를 넣어도 빼도 된다(本物だとは限らない / 本物とは限らない)."],"why":"限る(한정하다)의 부정형 限らない에 인용의 と와 は가 붙어 '~라고 한정되지는 않는다'는 뜻이 된다.","nu":"모두 그렇다는 게 아니라 예외도 있다는 부분부정이다. 必ずしも는 반드시 뒤에 부정 표현과 함께 쓰며, 긍정문에는 쓰지 않는다(必ずしも良い ×). 必ずしも를 빼고 とは限らない만 써도 같은 뜻이 된다.","cmp":[{"g":"～わけではない","d":"わけではない는 상대의 생각이나 앞 말에서 당연히 나올 결론을 부정할 때 넓게 쓴다. とは限らない는 '늘 그런 것은 아니다, 예외가 있다'는 쪽에 초점이 있다."}],"ex":[{"jp":"高[たか]い物[もの]が必[かなら]ずしもいい物[もの]だとは限[かぎ]らない。","ko":"비싼 물건이 반드시 좋은 물건인 것은 아니다."},{"jp":"先生[せんせい]の言[い]うことが必[かなら]ずしも正[ただ]しいとは限[かぎ]らない。","ko":"선생님 말이 반드시 옳은 것은 아니다."},{"jp":"強[つよ]いチームが必[かなら]ずしも勝[か]つとは限[かぎ]らない。","ko":"강한 팀이 반드시 이기는 것은 아니다."}],"dr":[{"t":"make","q":"正しい → 必ずしも～とは限らない","a":"必ずしも正しいとは限らない","hint":"い형용사 그대로 + とは限らない"},{"t":"make","q":"勝つ → 必ずしも～とは限らない","a":"必ずしも勝つとは限らない","hint":"동사 사전형 그대로 + とは限らない"},{"t":"fill","q":"お金持[かねも]ちが必[かなら]ずしも幸[しあわ]せ（　）。","a":"とは限らない","opts":["とは限らない","に違いない","に決まっている","かもしれない"]}],"src":[],"vf":0,"u":32,"g":1,"gp":"gg_N3_08"},{"id":"g3_001","t":"その上","ko":"게다가, 그 위에","cat":"부사·접속사","conn":[{"w":"문장 + 문장","f":"駅に近い。その上、家賃も安い。"},{"w":"문장 + 문장(동사문)","f":"雨が降ってきた。その上、風も強くなった。"}],"rule":["1. 글자가 바뀌는 활용은 없고, 앞 문장을 「。」로 끝낸 뒤 다음 문장 맨 앞에 その上를 둔다.","2. 뒤 문장은 앞 문장과 같은 방향(좋은 점+좋은 점, 나쁜 점+나쁜 점)의 내용을 덧붙인다.","3. 뒤 문장에는 '~도'를 뜻하는 조사 も가 자주 함께 쓰인다."],"why":"その(그) + 上(うえ, 위)로, '그 위에 (또)'라는 뜻에서 '게다가'로 쓰인다.","nu":"약간 딱딱한 편이지만 회화에서도 흔히 쓴다. 문장과 문장 사이를 잇는 접속사이며, 한 문장 안에서 이을 때는 「～上に」를 쓴다. 뒤에 명령·의뢰문은 잘 오지 않는다. 반대 방향 내용(장점+단점)을 이으면 부자연스럽다.","cmp":[{"g":"しかも","d":"しかも는 덧붙인 내용이 예상 밖이거나 한층 더하다는 느낌이 강하다. その上는 담담하게 추가한다."},{"g":"おまけに","d":"おまけに는 회화체이며, 나쁜 일이 겹칠 때 자주 쓴다."}],"ex":[{"jp":"このアパートは駅[えき]に近[ちか]い。その上[うえ]、家賃[やちん]も安[やす]い。","ko":"이 아파트는 역에서 가깝다. 게다가 집세도 싸다."},{"jp":"彼女[かのじょ]は料理[りょうり]が上手[じょうず]だ。その上[うえ]、歌[うた]もうまい。","ko":"그녀는 요리를 잘한다. 게다가 노래도 잘한다."},{"jp":"道[みち]に迷[まよ]った。その上[うえ]、雨[あめ]まで降[ふ]ってきた。","ko":"길을 잃었다. 게다가 비까지 내리기 시작했다."}],"dr":[{"t":"make","q":"この店は安い。／料理もおいしい。 → その上로 잇기","a":"この店は安い。その上、料理もおいしい。","hint":"앞 문장을 。로 끝내고 뒤 문장 앞에 その上、를 둔다"},{"t":"make","q":"頭が痛い。／熱もある。 → その上로 잇기","a":"頭が痛い。その上、熱もある。","hint":"나쁜 점+나쁜 점도 같은 방향이라 가능"},{"t":"fill","q":"この部屋[へや]は広[ひろ]い。（　）、日当[ひあ]たりもいい。","a":"その上","opts":["その上","しかし","それなら","つまり"]}],"src":["https://bunpro.jp/grammar_points/417"],"vf":1,"u":33,"g":1,"gp":"gg_N3_08"},{"id":"g3_024","t":"すこしも～ない","ko":"조금도 ~하지 않다","cat":"부사·접속사","conn":[{"w":"동사 ない형","f":"わかる → すこしもわからない"},{"w":"い형용사","f":"寒い → すこしも寒くない"},{"w":"な형용사","f":"楽 → すこしも楽ではない"}],"rule":["1. 술어를 부정형으로 바꾼다: い형용사는 い를 く로 바꾸고 ない(寒い → 寒くない).","2. 동사는 ない형(わかる → わからない), な형용사는 ではない·じゃない(楽じゃない).","3. 술어 앞에 すこしも를 놓는다 → すこしも寒くない."],"why":"すこし(少し, 조금) + も(~도)로 '조금도'가 되고, 부정과 함께 완전 부정을 만든다.","nu":"반드시 부정 표현과 함께 쓴다. 긍정문에 쓰면 틀린다. 한자로 少しも라고도 쓴다. 회화에서는 ちっとも, 全然도 많이 쓴다.","cmp":[{"g":"ちっとも～ない","d":"뜻은 같고 더 회화적이다."},{"g":"全然～ない","d":"가장 일반적인 완전 부정."}],"ex":[{"jp":"外[そと]は雪[ゆき]だけど、すこしも寒[さむ]くない。","ko":"밖은 눈이 오지만 조금도 춥지 않다."},{"jp":"彼[かれ]の説明[せつめい]はすこしもわからなかった。","ko":"그의 설명은 조금도 이해되지 않았다."},{"jp":"この仕事[しごと]はすこしも楽[らく]じゃない。","ko":"이 일은 조금도 편하지 않다."}],"dr":[{"t":"make","q":"痛い → すこしも～ない","a":"すこしも痛くない","hint":"い를 く로 바꾸고 ない, 앞에 すこしも"},{"t":"make","q":"変わる → すこしも～ない","a":"すこしも変わらない","hint":"ない형(る를 ら로) + ない, 앞에 すこしも"},{"t":"fill","q":"昨日[きのう]の映画[えいが]は（　）面白[おもしろ]くなかった。","a":"すこしも","opts":["すこしも","たくさん","もっと","ずいぶん"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/少しも～ない-sukoshi-mo-nai-meaning/"],"vf":1,"u":33,"g":1,"gp":"gg_N3_08"},{"id":"g3_028","t":"そのために","ko":"그것을 위해 / 그 때문에","cat":"부사·접속사","conn":[{"w":"문장(목적)","f":"やせたい。そのために、毎朝走る。"},{"w":"문장(원인)","f":"大雪だった。そのために、電車が止まった。"}],"rule":["1. 앞 문장에 목표 또는 원인을 쓰고 。로 끝낸다.","2. 다음 문장 첫머리에 そのために(、)를 놓는다.","3. 뒤 문장에는 그 목표를 위한 행동, 또는 그 원인으로 생긴 결과를 쓴다."],"why":"その(그) + ため(위함·까닭) + に로, ～ために의 '목적'과 '원인' 두 뜻을 그대로 이어받는다.","nu":"앞이 바라는 일(~하고 싶다)이면 '그것을 위해', 앞이 일어난 사실이면 '그 때문에'로 읽는다. 원인의 뜻은 다소 딱딱해 글이나 뉴스에 많고, 회화에서는 だから를 많이 쓴다.","cmp":[{"g":"その結果","d":"결과만 나타낸다. 목적의 뜻은 없다."},{"g":"だから","d":"회화적인 원인·이유. 목적의 뜻은 없다."}],"ex":[{"jp":"来年[らいねん]日本[にほん]に留学[りゅうがく]したい。そのために、毎日[まいにち]日本語[にほんご]を勉強[べんきょう]している。","ko":"내년에 일본에 유학하고 싶다. 그것을 위해 매일 일본어를 공부하고 있다."},{"jp":"やせたい。そのために、毎朝[まいあさ]走[はし]っている。","ko":"살을 빼고 싶다. 그래서(그것을 위해) 매일 아침 달리고 있다."},{"jp":"昨日[きのう]は大雪[おおゆき]だった。そのために、電車[でんしゃ]が止[と]まった。","ko":"어제는 폭설이었다. 그 때문에 전철이 멈췄다."}],"dr":[{"t":"make","q":"やせたい。／毎朝走る。(목적으로 잇기)","a":"やせたい。そのために、毎朝走る。","hint":"두 문장 사이에 そのために"},{"t":"make","q":"試験に合格したい。／毎日勉強する。(목적으로 잇기)","a":"試験に合格したい。そのために、毎日勉強する。","hint":"목표。そのために、행동。"},{"t":"fill","q":"車[くるま]を買[か]いたい。（　）、お金[かね]を貯[た]めている。","a":"そのために","opts":["そのために","それとも","ところが","それでも"]}],"src":["https://bunpro.jp/grammar_points/447"],"vf":1,"u":33,"g":1,"gp":"gg_N3_08"},{"id":"g3_029","t":"その結果","ko":"그 결과","cat":"부사·접속사","conn":[{"w":"문장","f":"毎日練習した。その結果、試合に勝った。"}],"rule":["1. 앞 문장에 원인이 된 행동·상황을 쓴다.","2. 다음 문장을 その結果(、)로 시작한다.","3. 뒤 문장에는 그로 인해 생긴 결과를 쓴다(과거형이 많다)."],"why":"その(그) + 結果(결과) 그대로의 뜻이다.","nu":"다소 딱딱한 말투로 보고·작문·설명에 많이 쓴다. 좋은 결과와 나쁜 결과 모두에 쓸 수 있다. 뒤에는 실제로 생긴 결과가 오므로 명령·의지 표현은 오지 않는다.","cmp":[{"g":"そのために","d":"원인 외에 목적(그것을 위해)도 나타낸다. その結果는 결과만."}],"ex":[{"jp":"毎日[まいにち]練習[れんしゅう]した。その結果、試合[しあい]に勝[か]った。","ko":"매일 연습했다. 그 결과 시합에 이겼다."},{"jp":"会社[かいしゃ]がつぶれた。その結果、多[おお]くの人[ひと]が仕事[しごと]を失[うしな]った。","ko":"회사가 망했다. 그 결과 많은 사람이 일자리를 잃었다."},{"jp":"みんなでよく話[はな]し合[あ]った。その結果、計画[けいかく]を変[か]えることになった。","ko":"다 같이 충분히 의논했다. 그 결과 계획을 바꾸기로 했다."}],"dr":[{"t":"make","q":"毎日走った。／5キロやせた。(결과로 잇기)","a":"毎日走った。その結果、5キロやせた。","hint":"원인。その結果、결과。"},{"t":"make","q":"よく調べた。／原因がわかった。(결과로 잇기)","a":"よく調べた。その結果、原因がわかった。","hint":"두 문장 사이에 その結果"},{"t":"fill","q":"毎日[まいにち]練習[れんしゅう]した。（　）、上手[じょうず]になった。","a":"その結果","opts":["その結果","それとも","ところが","それなのに"]}],"src":["https://nihongokyoshi-net.com/2019/08/20/jlptn3-grammar-kekka/","https://bunpro.jp/grammar_points/447"],"vf":1,"u":34,"g":1,"gp":"gg_N3_08"},{"id":"g3_030","t":"それと","ko":"그리고, 그리고 또","cat":"부사·접속사","conn":[{"w":"문장","f":"部屋を掃除して。それと、ゴミも捨てて。"},{"w":"명사","f":"パンを買ってきて。それと、牛乳も。"}],"rule":["1. 먼저 하나의 항목·용건을 말한다.","2. それと(、)를 놓는다.","3. 덧붙일 항목·용건을 말한다. 명사만 덧붙일 때는 も를 붙이는 경우가 많다(牛乳も)."],"why":"それ(그것) + と(~와)로 '그것과 (또)'라는 뜻이 된다.","nu":"회화체로, 말하다가 생각난 것을 덧붙일 때 자주 쓴다. 격식 있는 글에서는 それから·また를 쓴다. 선택을 묻는 それとも(아니면)와 헷갈리지 않도록 주의.","cmp":[{"g":"それから","d":"추가 외에 순서(그다음에)도 나타내며 더 무난하다."},{"g":"それとも","d":"'아니면'으로 둘 중 하나를 고르게 하는 말. それと는 덧붙이기."}],"ex":[{"jp":"パンを買[か]ってきて。それと、牛乳[ぎゅうにゅう]も。","ko":"빵 사 와. 그리고 우유도."},{"jp":"明日[あした]は傘[かさ]を持[も]ってきてね。それと、お弁当[べんとう]も忘[わす]れないで。","ko":"내일은 우산 가져와. 그리고 도시락도 잊지 마."},{"jp":"コーヒーを一[ひと]つください。それと、ケーキも一[ひと]つ。","ko":"커피 하나 주세요. 그리고 케이크도 하나."}],"dr":[{"t":"make","q":"パンを買う。／牛乳(덧붙이기)","a":"パンを買う。それと、牛乳も。","hint":"それと + 명사 + も"},{"t":"make","q":"部屋を掃除してください。／ゴミを捨ててください。(덧붙이기)","a":"部屋を掃除してください。それと、ゴミを捨ててください。","hint":"두 문장 사이에 それと"},{"t":"fill","q":"コーヒーをください。（　）、サンドイッチも。","a":"それと","opts":["それと","それとも","それでも","それなのに"]}],"src":[],"vf":0,"u":34,"g":1,"gp":"gg_N3_08"},{"id":"g3_031","t":"～？それとも～？","ko":"~? 아니면 ~?","cat":"부사·접속사","conn":[{"w":"명사","f":"コーヒー？それとも紅茶？"},{"w":"동사","f":"行く？それとも行かない？"},{"w":"정중형","f":"肉にしますか。それとも魚にしますか。"}],"rule":["1. 첫 번째 선택지를 질문 형태로 말한다(～？ 또는 ～か。).","2. 그 뒤에 それとも를 놓는다.","3. 두 번째 선택지를 같은 질문 형태로 말한다."],"why":"","nu":"둘 중 하나를 고르게 하는 질문에서만 쓴다. 평서문에서 'A 또는 B'라고 할 때는 または·か를 쓴다. 회화와 정중한 말 모두에 쓸 수 있다.","cmp":[{"g":"または","d":"평서문·안내문의 '또는'(電話またはメールで連絡してください). それとも는 질문 전용."},{"g":"それと","d":"'그리고'로 덧붙이는 말. 선택이 아니다."}],"ex":[{"jp":"コーヒーにする？それとも紅茶[こうちゃ]にする？","ko":"커피로 할래? 아니면 홍차로 할래?"},{"jp":"今日[きょう]行[い]きますか。それとも明日[あした]にしますか。","ko":"오늘 가시겠어요? 아니면 내일로 하시겠어요?"},{"jp":"この服[ふく]、赤[あか]がいい？それとも青[あお]がいい？","ko":"이 옷, 빨강이 좋아? 아니면 파랑이 좋아?"}],"dr":[{"t":"make","q":"電車で行く？／バスで行く？(선택 질문으로 잇기)","a":"電車で行く？それともバスで行く？","hint":"질문 + それとも + 질문"},{"t":"make","q":"肉にしますか。／魚にしますか。(선택 질문으로 잇기)","a":"肉にしますか。それとも魚にしますか。","hint":"두 질문 사이에 それとも"},{"t":"fill","q":"休[やす]みの日[ひ]は家[いえ]にいる？（　）出[で]かける？","a":"それとも","opts":["それとも","それと","それから","だから"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%9D%E3%82%8C%E3%81%A8%E3%82%82"],"vf":1,"u":34,"g":1,"gp":"gg_N3_08"},{"id":"g3_045","t":"つまり","ko":"즉, 다시 말해","cat":"부사·접속사","conn":[{"w":"문장 + 문장","f":"Aだ。つまり、Bだ。"},{"w":"명사 + 명사","f":"母の姉、つまり伯母"},{"w":"결론 정리","f":"つまり、～ということだ"}],"rule":["1. 먼저 말하려는 내용 A를 말한다.","2. 그 뒤에 つまり를 놓는다.","3. A를 다른 말로 바꾸거나 한마디로 정리한 B를 말한다."],"why":"","nu":"회화와 글 모두 쓴다. 앞 내용을 바꿔 말하거나 결론으로 정리할 때 쓰며, 끝을 ～ということだ로 맺는 일이 많다. 원인과 결과를 잇는 だから와 혼동하지 않도록 주의.","cmp":[{"g":"すなわち","d":"같은 '즉'이지만 딱딱한 문어체."},{"g":"だから","d":"앞이 이유, 뒤가 결과. つまり는 같은 내용을 바꿔 말한다."}],"ex":[{"jp":"母[はは]の姉[あね]、つまり伯母[おば]が明日[あした]来[く]る。","ko":"엄마의 언니, 즉 이모가 내일 온다."},{"jp":"一年[いちねん]に二回[にかい]、つまり半年[はんとし]に一回[いっかい]検査[けんさ]を受[う]ける。","ko":"1년에 두 번, 즉 반년에 한 번 검사를 받는다."},{"jp":"つまり、今日[きょう]は行[い]けないということですか。","ko":"그러니까 오늘은 못 간다는 말씀이에요?"}],"dr":[{"t":"make","q":"父[ちち]の弟[おとうと]／おじ (つまり로 잇기)","a":"父の弟、つまりおじ","hint":"A + つまり + 바꿔 말한 B"},{"t":"make","q":"一週間[いっしゅうかん]に一回[いっかい]／月[つき]に四回[よんかい]くらい (つまり로 잇기)","a":"一週間に一回、つまり月に四回くらい","hint":"A + つまり + 바꿔 말한 B"},{"t":"fill","q":"彼[かれ]は私[わたし]の父[ちち]の兄[あに]の息子[むすこ]、（　）いとこです。","a":"つまり","opts":["つまり","しかし","それとも","ところで"]}],"src":["https://bunpro.jp/grammar_points/252","https://cotoacademy.com/tsumari-jlpt-n3-grammer-japanese-meaning-english/"],"vf":1,"u":35,"g":1,"gp":"gg_N3_08"},{"id":"g3_049","t":"ですから","ko":"그러니까, 그래서 (정중)","cat":"부사·접속사","conn":[{"w":"문장 첫머리","f":"雨です。ですから、傘を持っていきます。"},{"w":"정중체 문장 + から(참고)","f":"寒いです + から"}],"rule":["1. 이유가 되는 문장을 정중체로 끝낸다(雨です。).","2. 다음 문장 첫머리에 ですから를 놓는다.","3. 그 뒤에 결과·판단·부탁을 말한다(傘を持っていきます)."],"why":"보통체 접속사 だから의 だ를 정중한 です로 바꾼 말이다.","nu":"정중체 회화나 안내에서 쓴다. 같은 설명을 되풀이할 때(ですから、さっき申し上げたように…) 쓰면 답답함이나 짜증이 섞여 들릴 수 있다. 친구에게는 だから를 쓴다. 寒いですから처럼 문장 안에서는 정중체 + から의 형태가 된다.","cmp":[{"g":"だから","d":"같은 뜻의 보통체. 친한 사이의 회화에 쓴다."},{"g":"それで","d":"'그래서'. 일이 어떻게 이어졌는지 사실을 말할 때 주로 쓰며, 뒤에 부탁·권유는 잘 오지 않는다."}],"ex":[{"jp":"明日[あした]は祝日[しゅくじつ]です。ですから、銀行[ぎんこう]は休[やす]みです。","ko":"내일은 공휴일입니다. 그러니까 은행은 쉽니다."},{"jp":"道[みち]が混[こ]んでいます。ですから、電車[でんしゃ]で行[い]きましょう。","ko":"길이 막힙니다. 그러니까 전철로 갑시다."},{"jp":"今日[きょう]は寒[さむ]いですから、コートを着[き]てください。","ko":"오늘은 추우니까 코트를 입으세요."}],"dr":[{"t":"make","q":"雨です。／タクシーで行きます。(ですから로 잇기)","a":"雨です。ですから、タクシーで行きます。","hint":"이유 문장 + ですから + 결과 문장"},{"t":"make","q":"電車が止まりました。だから、遅れました。(정중하게)","a":"電車が止まりました。ですから、遅れました。","hint":"だから → ですから"},{"t":"fill","q":"この店[みせ]は人気[にんき]があります。（　）、いつも混[こ]んでいます。","a":"ですから","opts":["ですから","しかし","それとも","ところで"]}],"src":[],"vf":0,"u":35,"g":1,"gp":"gg_N3_08"},{"id":"g3_063","t":"ところが","ko":"그런데 (뜻밖에도), 그러나","cat":"부사·접속사","conn":[{"w":"문장과 문장 사이","f":"晴れだと思った。ところが、雨が降った。"}],"rule":["1. 앞 문장에서 예상하거나 기대한 일을 말한다(晴れ).","2. 문장 첫머리에 ところが를 놓는다.","3. 뒤 문장에 예상과 다른 실제 결과를 말한다(雨)."],"why":"","nu":"뒤에 오는 내용이 이미 일어난 사실이며 말하는 사람에게도 뜻밖일 때 쓴다. 그래서 뒤 문장에 의지·명령·의뢰(～しよう, ～してください)는 오지 않는다. 회화와 글 모두에 쓰며, 이야기를 할 때 반전을 끌어내는 말로 자주 쓴다.","cmp":[{"g":"しかし・でも","d":"일반적인 역접. 뜻밖이라는 느낌이 꼭 없어도 되고, 뒤에 의견도 올 수 있다."},{"g":"ところで","d":"화제를 바꾸는 '그런데'. 역접이 아니다."}],"ex":[{"jp":"天気予報[てんきよほう]は晴[は]れだった。ところが、午後[ごご]から雨[あめ]が降[ふ]り出[だ]した。","ko":"일기 예보는 맑음이었다. 그런데 오후부터 비가 내리기 시작했다."},{"jp":"簡単[かんたん]な試験[しけん]だと思[おも]っていた。ところが、全然[ぜんぜん]できなかった。","ko":"쉬운 시험이라고 생각했다. 그런데 전혀 못 풀었다."},{"jp":"店[みせ]に行[い]った。ところが、今日[きょう]は休[やす]みだった。","ko":"가게에 갔다. 그런데 오늘은 휴일이었다."}],"dr":[{"t":"make","q":"すぐ終わると思った。／三時間かかった。(뜻밖의 결과로 잇기)","a":"すぐ終わると思った。ところが、三時間かかった。","hint":"예상 。 + ところが + 뜻밖의 결과"},{"t":"make","q":"彼は来ると言った。／来なかった。(뜻밖의 결과로 잇기)","a":"彼は来ると言った。ところが、来なかった。","hint":"문장 첫머리에 ところが"},{"t":"fill","q":"急[いそ]いで駅[えき]に行[い]った。（　）、電車[でんしゃ]はもう出[で]た後[あと]だった。","a":"ところが","opts":["ところが","ところで","それとも","だから"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201109.html"],"vf":1,"u":35,"g":1,"gp":"gg_N3_08"},{"id":"g3_065","t":"ところで","ko":"그런데 (화제 전환)","cat":"부사·접속사","conn":[{"w":"문장 첫머리","f":"ところで、夕食は何にする？"}],"rule":["1. 지금까지 하던 이야기(화제1)를 마친다.","2. 새 문장 첫머리에 ところで를 놓는다.","3. 그 뒤에 새로운 화제나 질문(화제2)을 말한다."],"why":"","nu":"이야기의 흐름을 바꿔 다른 화제를 꺼낼 때 쓴다. 앞뒤 내용이 반대일 필요는 없으며 역접의 뜻은 없다. 회화와 편지글에 모두 쓴다. 동사 た형 + ところで(~해 봤자)는 다른 문법이니 혼동하지 않도록 한다.","cmp":[{"g":"ところが","d":"앞 내용과 다른 뜻밖의 결과를 잇는 역접. ところで는 화제만 바꾼다."},{"g":"さて","d":"화제를 바꾸거나 본론으로 들어갈 때 쓴다. 연설·편지 등에서 조금 더 격식 있게 들린다."}],"ex":[{"jp":"今日[きょう]はいい天気[てんき]ですね。ところで、夕食[ゆうしょく]は何[なに]にしますか。","ko":"오늘 날씨 좋네요. 그런데 저녁은 뭘로 할까요?"},{"jp":"ところで、昨日[きのう]の宿題[しゅくだい]はもう終[お]わった？","ko":"그런데 어제 숙제는 벌써 끝냈어?"},{"jp":"旅行[りょこう]、楽[たの]しかったよ。ところで、田中[たなか]さんは元気[げんき]？","ko":"여행 즐거웠어. 그런데 다나카 씨는 잘 지내?"}],"dr":[{"t":"make","q":"暑いですね。／明日は暇ですか。(화제를 바꾸며 잇기)","a":"暑いですね。ところで、明日は暇ですか。","hint":"화제1 。 + ところで + 화제2"},{"t":"make","q":"映画、面白かったね。／お腹すいてない？(화제를 바꾸며 잇기)","a":"映画、面白かったね。ところで、お腹すいてない？","hint":"새 문장 첫머리에 ところで"},{"t":"fill","q":"会議[かいぎ]はこれで終[お]わります。（　）、来週[らいしゅう]の飲[の]み会[かい]、来[き]ますか。","a":"ところで","opts":["ところで","ところが","だから","それに"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201109.html"],"vf":1,"u":36,"g":1,"gp":"gg_N3_09"},{"id":"g3_072","t":"なぜなら","ko":"왜냐하면","cat":"부사·접속사","conn":[{"w":"문장과 문장 사이","f":"試合は中止だ。なぜなら、雨だからだ。"}],"rule":["1. 먼저 결과·결론을 말한다(中止).","2. 다음 문장 첫머리에 なぜなら를 놓는다.","3. 이유를 말하고 끝을 からだ／からです로 맺는다(雨だからだ)."],"why":"なぜ(왜) + なら(~라면).","nu":"주로 글이나 연설·발표처럼 논리적으로 설명하는 장면에서 쓰는 다소 딱딱한 말. 일상 회화에서는 だって·というのは나 ～から만으로 말하는 편이 자연스럽다. 이유 문장 끝은 からだ·からです로 맺는 것이 일반적이다.","cmp":[{"g":"だって","d":"회화체 '왜냐면'. 변명이나 불만의 느낌이 들어가기 쉽다."},{"g":"だから","d":"'그래서'. 이유가 앞, 결과가 뒤로 순서가 반대다."}],"ex":[{"jp":"今日[きょう]の試合[しあい]は中止[ちゅうし]です。なぜなら、雨[あめ]が強[つよ]いからです。","ko":"오늘 시합은 취소입니다. 왜냐하면 비가 세기 때문입니다."},{"jp":"私[わたし]はこの町[まち]が好[す]きだ。なぜなら、人[ひと]が親切[しんせつ]だからだ。","ko":"나는 이 마을이 좋다. 왜냐하면 사람들이 친절하기 때문이다."},{"jp":"朝[あさ]ご飯[はん]は大切[たいせつ]だ。なぜなら、一日[いちにち]の元気[げんき]のもとになるからだ。","ko":"아침밥은 중요하다. 왜냐하면 하루 기운의 바탕이 되기 때문이다."}],"dr":[{"t":"make","q":"会議は延期だ。／部長が病気だ。(なぜなら로 이유 잇기)","a":"会議は延期だ。なぜなら、部長が病気だからだ。","hint":"결과 。 + なぜなら + 이유 + からだ"},{"t":"make","q":"今日は早く帰ります。／用事があります。(なぜなら로 이유 잇기)","a":"今日は早く帰ります。なぜなら、用事があるからです。","hint":"이유 끝은 からです"},{"t":"fill","q":"彼[かれ]は試験[しけん]に落[お]ちた。（　）、全然[ぜんぜん]勉強[べんきょう]しなかったからだ。","a":"なぜなら","opts":["なぜなら","だから","それとも","ところで"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AA%E3%81%9C%E3%81%AA%E3%82%89-%E3%81%8B%E3%82%89"],"vf":1,"u":36,"g":1,"gp":"gg_N3_09"},{"id":"g3_098","t":"まったく～ない","ko":"전혀 ~하지 않다","cat":"부사·접속사","conn":[{"w":"동사 ない형","f":"まったく + わからない"},{"w":"い형용사","f":"まったく + 寒くない"},{"w":"な형용사","f":"まったく + 上手じゃない"},{"w":"명사(+ない)","f":"まったく + 関係ない"}],"rule":["1. 동사는 ない형으로 바꾼다. 1그룹은 어미 う단을 あ단으로 바꾸고 ない(わかる→わからない), 2그룹은 る를 떼고 ない.","2. い형용사는 い를 くない로(寒い→寒くない), な형용사·명사는 じゃない/ではない.","3. 그 앞에 まったく를 놓아 부정을 강조한다(まったくわからない)."],"why":"","nu":"부정을 강하게 만드는 부사로, 全然과 비슷하지만 조금 더 딱딱하다. 긍정문에서는 '완전히, 정말로'의 뜻(まったく同じだ, まったくその通りだ)이 되고, 단독으로 'まったく、もう'라고 하면 불만·어이없음을 나타낸다.","cmp":[{"g":"全然～ない","d":"같은 뜻으로 더 회화적."},{"g":"あまり～ない","d":"'그다지 ~않다'로 부정의 정도가 약하다."}],"ex":[{"jp":"彼[かれ]の話[はなし]はまったくわからなかった。","ko":"그의 이야기는 전혀 이해가 안 됐다."},{"jp":"この部屋[へや]はまったく寒[さむ]くない。","ko":"이 방은 전혀 춥지 않다."},{"jp":"私[わたし]はその事件[じけん]とまったく関係[かんけい]ない。","ko":"나는 그 사건과 전혀 관계없다."}],"dr":[{"t":"make","q":"わかる → まったく～ない","a":"まったくわからない","hint":"る를 ら로 바꾸고 ない, 앞에 まったく"},{"t":"make","q":"寒い → まったく～ない","a":"まったく寒くない","hint":"い를 くない로, 앞에 まったく"},{"t":"fill","q":"この漢字[かんじ]はまったく読[よ]め（　）。","a":"ない","opts":["ない","る","ます","た"]}],"src":["https://bunpro.jp/ja/grammar_points/%E5%85%A8%E3%81%8F-%E3%81%AA%E3%81%84","https://jlptsensei.com/learn-japanese-grammar/全く～ない-mattakunai-meaning"],"vf":1,"u":36,"g":1,"gp":"gg_N3_09"},{"id":"g3_104","t":"めったに～ない","ko":"좀처럼 ~하지 않다","cat":"부사·접속사","conn":[{"w":"1그룹 동사","f":"めったに + 行かない"},{"w":"2그룹 동사","f":"めったに + 食べない"},{"w":"する","f":"めったに + しない"},{"w":"来る","f":"めったに + 来ない"}],"rule":["1. 동사를 ない형으로 바꾼다. 1그룹은 어미 う단을 あ단으로(行く→行かない), 2그룹은 る를 떼고 ない, する→しない, 来る→来ない.","2. 그 앞에 めったに를 놓는다(めったに行かない).","3. めったに 뒤에 긍정형은 쓰지 않는다."],"why":"","nu":"빈도가 아주 낮음(거의 ~하지 않음)을 나타내며, 주로 동사 부정형과 함께 쓴다. あまり～ない보다 빈도가 낮다. 정중형은 めったに～ません.","cmp":[{"g":"あまり～ない","d":"'그다지 ~않다'. 정도에도 빈도에도 쓰며 めったに보다 약하다."}],"ex":[{"jp":"父[ちち]はめったに怒[おこ]らない。","ko":"아버지는 좀처럼 화내지 않는다."},{"jp":"この町[まち]では雪[ゆき]がめったに降[ふ]らない。","ko":"이 마을에서는 눈이 좀처럼 내리지 않는다."},{"jp":"忙[いそが]しくて、映画館[えいがかん]にはめったに行[い]きません。","ko":"바빠서 영화관에는 좀처럼 가지 않습니다."}],"dr":[{"t":"make","q":"行く → めったに～ない","a":"めったに行かない","hint":"く를 か로 + ない, 앞에 めったに"},{"t":"make","q":"来る → めったに～ない","a":"めったに来ない","hint":"来る는 불규칙: 来ない"},{"t":"fill","q":"兄[あに]は（　）電話[でんわ]をくれない。","a":"めったに","opts":["めったに","よく","ときどき","いつも"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%82%81%E3%81%A3%E3%81%9F%E3%81%AB-%E3%81%AA%E3%81%84","https://jlptsensei.com/learn-japanese-grammar/めったに～ない-metta-ni-nai-meaning/"],"vf":1,"u":37,"g":1,"gp":"gg_N3_09"},{"id":"g3_132","t":"決して～ない","ko":"결코 ~하지 않다","cat":"부사·접속사","conn":[{"w":"동사 ない형","f":"決して + 言わない"},{"w":"동사 정중 부정","f":"決して + 忘れません"},{"w":"い형용사 부정","f":"決して + 安くない"},{"w":"な형용사·명사 부정","f":"決して + 簡単ではない"},{"w":"금지","f":"決して + 開けないでください"}],"rule":["1. 동사를 ない형으로 바꾼다. 2그룹은 る를 ない로 바꾸고(諦める → 諦めない), 1그룹은 어미 う단을 あ단으로 바꿔 ない를 붙인다(言う → 言わない).","2. 부정 술어 앞에 부사 決して를 넣는다(決して諦めない).","3. 형용사·명사도 부정형(安くない, 簡単ではない)과 함께 쓴다."],"why":"","nu":"강한 부정이나 굳은 결심을 나타내며 약간 딱딱한 말투다. 決して는 반드시 부정 표현과 함께 쓰고 긍정문에는 쓸 수 없다(決して行く ×). '決して～ないでください'로 강한 금지·부탁도 나타낸다.","cmp":[{"g":"絶対に","d":"絶対に는 긍정문(絶対に行く)에도 부정문에도 쓰고 회화적이다. 決して는 부정문에만 쓴다."}],"ex":[{"jp":"最後[さいご]まで決[けっ]して諦[あきら]めない。","ko":"마지막까지 결코 포기하지 않겠다."},{"jp":"この秘密[ひみつ]は決[けっ]して誰[だれ]にも言[い]いません。","ko":"이 비밀은 결코 누구에게도 말하지 않겠습니다."},{"jp":"この問題[もんだい]は決[けっ]して簡単[かんたん]ではない。","ko":"이 문제는 결코 쉽지 않다."}],"dr":[{"t":"make","q":"諦める → 決して～ない","a":"決して諦めない","hint":"る를 ない로 바꾸고 앞에 決して"},{"t":"make","q":"言う → 決して～ない","a":"決して言わない","hint":"う를 わ로 바꿔 ない, 앞에 決して"},{"t":"fill","q":"この約束[やくそく]は（　）忘[わす]れません。","a":"決して","opts":["決して","ぜひ","ちょうど","もうすぐ"]}],"src":[],"vf":0,"u":37,"g":1,"gp":"gg_N3_09"},{"id":"g3_009","t":"～かわりに","ko":"~대신에","cat":"기타","conn":[{"w":"명사","f":"はしの + かわりに"},{"w":"동사 보통형","f":"映画を見る + かわりに"},{"w":"い형용사","f":"安い + かわりに"},{"w":"な형용사","f":"不便な + かわりに"}],"rule":["1. 글자가 바뀌는 활용은 없고, 명사를 꾸미는 꼴 뒤에 かわりに를 붙인다.","2. 명사는 の를 넣는다(はしのかわりに). な형용사는 な를 넣는다(不便なかわりに).","3. 동사·い형용사는 보통형 그대로 붙인다(見るかわりに, 安いかわりに)."],"why":"동사 代わる(대신하다)의 ます형 명사꼴 代わり + に로, '~을 대신해서'라는 뜻이다.","nu":"① 대신(다른 것·사람으로 바꿈): 先生の代わりに. ② 교환·보상(~하는 대신에): 手伝う代わりに、ご飯をおごって. ③ 장단점의 맞바꿈: 不便な代わりに自然が多い. 한자 표기 代わりに도 흔하다. な형용사·명사에 だ를 넣은 だかわりに는 틀린 꼴.","cmp":[{"g":"～に代わって","d":"に代わって는 사람·조직이 역할을 대신할 때 쓰는 딱딱한 표현(社長に代わって). 동사·형용사에는 붙지 않는다."}],"ex":[{"jp":"はしの代[か]わりにフォークで食[た]べた。","ko":"젓가락 대신 포크로 먹었다."},{"jp":"映画[えいが]を見[み]る代[か]わりに、家[いえ]で本[ほん]を読[よ]んだ。","ko":"영화를 보는 대신 집에서 책을 읽었다."},{"jp":"この町[まち]は不便[ふべん]な代[か]わりに、自然[しぜん]が多[おお]い。","ko":"이 마을은 불편한 대신에 자연이 많다."}],"dr":[{"t":"make","q":"コーヒー → ～かわりに","a":"コーヒーのかわりに","hint":"명사 뒤에는 の를 넣는다"},{"t":"make","q":"静かだ → ～かわりに","a":"静かなかわりに","hint":"な형용사는 だ를 な로 바꾼다"},{"t":"fill","q":"今日[きょう]は母[はは]の（　）、私[わたし]が料理[りょうり]を作[つく]ります。","a":"かわりに","opts":["かわりに","うちに","ほどに","ばかりに"]}],"src":["https://www.mlcjapanese.co.jp/n3_04_14.html","https://nihongokyoshi-net.com/2018/04/24/jlptn3-grammar-kawarini/"],"vf":1,"u":37,"g":1,"gp":"gg_N3_09"},{"id":"g3_043","t":"～でいっぱい","ko":"~로 가득하다","cat":"기타","conn":[{"w":"명사","f":"人で + いっぱい"},{"w":"명사(장소가 주어)","f":"箱がおもちゃで + いっぱいだ"},{"w":"명사(관용)","f":"おなかが + いっぱい"}],"rule":["1. 가득 찬 장소나 물건을 が(は)로 말한다(箱が).","2. 그 안을 채운 것을 명사 + で로 말한다(おもちゃで).","3. 끝에 いっぱいだ／いっぱいです를 붙인다(箱がおもちゃでいっぱいだ)."],"why":"","nu":"회화와 글 모두 쓴다. 채우는 것에는 조사 で를 쓰며, 한국어 '~로'에 끌려 に나 から를 쓰는 실수에 주의한다. 마음이나 머리가 무엇으로 가득한 것(頭の中が試験のことでいっぱい)에도 쓴다. いっぱい만 쓰면 '많이'(いっぱい食べた)라는 부사도 된다.","cmp":[{"g":"～がいっぱい","d":"人がいっぱいいる처럼 '많다'는 것 자체를 말한다. ～でいっぱい는 어떤 장소가 그것으로 꽉 찼다는 데 초점."}],"ex":[{"jp":"駅[えき]は人[ひと]でいっぱいだった。","ko":"역은 사람들로 가득했다."},{"jp":"箱[はこ]がおもちゃでいっぱいです。","ko":"상자가 장난감으로 가득합니다."},{"jp":"頭[あたま]の中[なか]が明日[あした]の試験[しけん]のことでいっぱいだ。","ko":"머릿속이 내일 시험 생각으로 가득하다."}],"dr":[{"t":"make","q":"部屋[へや]・荷物[にもつ] → ～でいっぱいだ","a":"部屋は荷物でいっぱいだ","hint":"장소 + は, 채우는 것 + で + いっぱいだ"},{"t":"make","q":"店[みせ]・客[きゃく] → ～でいっぱいだ","a":"店は客でいっぱいだ","hint":"장소 + は, 채우는 것 + で + いっぱいだ"},{"t":"fill","q":"日曜日[にちようび]の公園[こうえん]は子供[こども]（　）いっぱいだ。","a":"で","opts":["で","を","へ","より"]}],"src":[],"vf":0,"u":38,"g":1,"gp":"gg_N3_09"},{"id":"g3_056","t":"～というと","ko":"~라고 하면, ~하면 (떠오르는 것)","cat":"기타","conn":[{"w":"명사","f":"夏 + というと"},{"w":"보통형(되물을 때)","f":"行けない + というと"}],"rule":["1. 화제로 삼을 명사를 그대로 둔다(夏).","2. 그 뒤에 というと를 붙인다.","3. 뒤에는 그 말에서 바로 떠오르는 대표적인 것을 말한다(海)."],"why":"","nu":"어떤 말을 듣고 가장 먼저 연상되는 것을 말할 때 쓴다. 비슷한 뜻의 といえば·といったら보다 약간 차분한 말투다. 상대의 말을 받아 '~라고 하면 (무슨 뜻이죠?)'처럼 되묻는 용법도 있다(行けないというと？). 뒤에 명령·의뢰는 오지 않는다.","cmp":[{"g":"～といえば","d":"연상 용법은 거의 같다. といえば는 대화 중 나온 말을 받아 화제를 바꿀 때도 자주 쓴다."},{"g":"～というのは","d":"말의 뜻·정의를 설명한다. というと는 정의가 아니라 떠오르는 것을 말한다."}],"ex":[{"jp":"夏[なつ]というと、やっぱり海[うみ]ですね。","ko":"여름 하면 역시 바다죠."},{"jp":"京都[きょうと]というと、古[ふる]いお寺[てら]を思[おも]い出[だ]す。","ko":"교토라고 하면 오래된 절이 생각난다."},{"jp":"「明日[あした]は行[い]けない」というと、何[なに]かあったんですか。","ko":"'내일은 못 간다'고 하시면, 무슨 일 있으세요?"}],"dr":[{"t":"make","q":"冬 → ～というと (눈이 떠오른다)","a":"冬というと、雪だ","hint":"명사 + というと + 떠오르는 것"},{"t":"make","q":"日本の料理 → ～というと","a":"日本の料理というと","hint":"명사 뒤에 그대로 というと"},{"t":"fill","q":"北海道[ほっかいどう]（　）、やっぱりラーメンが有名[ゆうめい]だ。","a":"というと","opts":["というと","というより","といっても","として"]}],"src":["https://bunpro.jp/grammar_points/240"],"vf":1,"u":38,"g":1,"gp":"gg_N3_09"},{"id":"g3_061","t":"～とおり(に)","ko":"~대로, ~한 그대로","cat":"기타","conn":[{"w":"동사 사전형","f":"言う + とおり"},{"w":"동사 た형","f":"言った + とおり"},{"w":"명사","f":"説明の + とおり / 予定 + どおり"}],"rule":["1. 동사는 사전형이나 た형에 붙인다. 言う는 1그룹이므로 어미 う를 った로 바꿔 た형 言った를 만든다.","2. 그 뒤에 とおり를 붙인다(言ったとおり).","3. 명사는 の를 넣어 のとおり로 붙이거나, の 없이 바로 붙여 どおり로 읽는다(予定どおり).","4. 뒤에 동사가 이어질 때는 とおりに, 명사가 이어질 때는 とおりの를 쓴다."],"why":"通[とお]り(길, 지나감)에서 온 말로, '그 길을 따라 똑같이'라는 뜻이 된다.","nu":"보거나 듣거나 정해진 것과 똑같이 한다는 뜻. 회화와 글 모두에 쓴다. 명사에 바로 붙을 때는 연탁하여 どおり가 된다(予定どおり, 計画どおり). て형에 붙이는 것은 틀린 형태이니 주의(×言ってとおり).","cmp":[{"g":"～ように","d":"言われたように도 '~처럼, ~대로'지만 とおり가 '정확히 똑같이'라는 느낌이 더 강하다."}],"ex":[{"jp":"先生[せんせい]が言[い]ったとおりに書[か]いてください。","ko":"선생님이 말한 대로 써 주세요."},{"jp":"地図[ちず]のとおりに行[い]ったら、すぐ駅[えき]に着[つ]いた。","ko":"지도대로 갔더니 금방 역에 도착했다."},{"jp":"電車[でんしゃ]は予定[よてい]どおり出発[しゅっぱつ]した。","ko":"전철은 예정대로 출발했다."}],"dr":[{"t":"make","q":"言う → ～とおりに (た형으로)","a":"言ったとおりに","hint":"う → った + とおりに"},{"t":"make","q":"説明 → ～とおりに","a":"説明のとおりに","hint":"명사 + の + とおりに"},{"t":"fill","q":"レシピに書[か]いてある（　）作[つく]ったら、おいしくできた。","a":"とおりに","opts":["とおりに","ところに","ために","くせに"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%8A%E3%82%8A"],"vf":1,"u":38,"g":1,"gp":"gg_N3_09"},{"id":"g3_067","t":"～として","ko":"~로서 (자격·역할·입장)","cat":"기타","conn":[{"w":"명사","f":"医者 + として"},{"w":"명사 + 명사 수식","f":"医者 + としての + 仕事"}],"rule":["1. 자격·역할을 나타내는 명사를 그대로 둔다(医者).","2. 그 뒤에 として를 붙인다(医者として).","3. 뒤에 그 자격으로 하는 동작이나 평가를 말한다(働く).","4. 명사를 꾸밀 때는 としての, 주제로 삼을 때는 としては를 쓴다."],"why":"","nu":"회화와 글 모두에 쓴다. 명사 뒤에만 붙는다(동사·형용사에 바로 붙지 않는다). 한국어 '~로서/~로써'를 구별하듯, として는 자격·역할('~로서')에 쓰고, 도구·수단('~로써')에는 で를 쓴다.","cmp":[{"g":"～にとって","d":"'~에게 있어서'. 판단·평가를 하는 사람의 입장을 나타낸다(私にとって大切だ). として는 자격·역할."}],"ex":[{"jp":"姉[あね]は医者[いしゃ]として病院[びょういん]で働[はたら]いている。","ko":"누나는 의사로서 병원에서 일하고 있다."},{"jp":"留学生[りゅうがくせい]として日本[にほん]に来[き]ました。","ko":"유학생으로서 일본에 왔습니다."},{"jp":"これは親[おや]としての責任[せきにん]です。","ko":"이것은 부모로서의 책임입니다."}],"dr":[{"t":"make","q":"通訳 → ～として働く","a":"通訳として働く","hint":"명사 + として"},{"t":"make","q":"社会人 → ～としてのマナー","a":"社会人としてのマナー","hint":"명사를 꾸밀 때는 としての"},{"t":"fill","q":"彼[かれ]はチームのリーダー（　）みんなをまとめた。","a":"として","opts":["として","にとって","について","によって"]}],"src":["https://nihongokyoshi-net.com/2020/01/06/jlptn3-grammar-toshite/"],"vf":1,"u":39,"g":1,"gp":"gg_N3_09"},{"id":"g3_070","t":"～ないことはない","ko":"~하지 않는 것은 아니다 (하기는 한다)","cat":"기타","conn":[{"w":"동사 ない형","f":"食べない + ことはない"},{"w":"가능동사","f":"できない + ことはない"},{"w":"い형용사","f":"おいしくない + ことはない"},{"w":"な형용사·명사","f":"好きじゃない + ことはない"}],"rule":["1. 동사를 ない형으로 바꾼다. 食べる는 2그룹이므로 る를 떼고 ない를 붙인다(食べない).","2. い형용사는 い를 くない로, な형용사·명사는 じゃない(ではない)로 바꾼다.","3. 그 뒤에 ことはない를 붙여 부정을 다시 부정한다(食べないことはない)."],"why":"ない(부정) + ことはない(~하는 일은 없다). 부정을 한 번 더 부정하는 구조.","nu":"'완전히 안 되는 것은 아니다, 어느 정도는 한다'라고 소극적으로 긍정할 때 쓴다. 적극적인 긍정이 아니라서 뒤에 が·けど로 이어 조건이나 망설임을 덧붙이는 경우가 많다. 동사 사전형 + ことはない('~할 필요는 없다')와 헷갈리지 않도록 주의.","cmp":[{"g":"～ないこともない","d":"뜻은 거의 같고 조금 더 부드럽고 완곡하다."},{"g":"동사 사전형 + ことはない","d":"'~할 필요는 없다'(心配することはない). ない형에 붙는 것과 뜻이 전혀 다르다."}],"ex":[{"jp":"ピーマンは食[た]べないことはないけど、あまり好[す]きじゃない。","ko":"피망은 안 먹는 건 아니지만 별로 안 좋아한다."},{"jp":"急[いそ]げば、間[ま]に合[あ]わないことはない。","ko":"서두르면 못 맞출 것도 없다."},{"jp":"この料理[りょうり]、おいしくないことはないが、少[すこ]し辛[から]い。","ko":"이 요리, 맛없는 건 아니지만 조금 맵다."}],"dr":[{"t":"make","q":"行く → ～ないことはない","a":"行かないことはない","hint":"く → か + ない + ことはない"},{"t":"make","q":"できる → ～ないことはない","a":"できないことはない","hint":"る를 떼고 ない + ことはない"},{"t":"fill","q":"お酒[さけ]は飲[の]め（　）けど、すぐ顔[かお]が赤[あか]くなる。","a":"ないことはない","opts":["ないことはない","ることはない","ないことにする","ないわけだ"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AA%E3%81%84%E3%81%93%E3%81%A8%E3%81%AF%E3%81%AA%E3%81%84"],"vf":1,"u":39,"g":1,"gp":"gg_N3_09"},{"id":"g3_075","t":"～において","ko":"~에서, ~에 있어서","cat":"기타","conn":[{"w":"명사(장소·시대·분야)","f":"東京 + において"},{"w":"명사 수식","f":"東京 + における + 会議"}],"rule":["1. 장소·시대·분야를 나타내는 명사 뒤에 において를 붙인다.","2. 뒤의 명사를 꾸밀 때는 における 형태로 바꾼다(現代における問題).","3. 강조나 대비에는 において は・においても를 쓴다."],"why":"","nu":"딱딱한 문어체·격식체로 뉴스, 안내문, 논문, 공식 행사 등에 쓴다. 일상 회화의 '~에서'는 で가 자연스럽다. 행사·회의 같은 일이 열리는 곳이나 분야를 말할 때 쓰며, 사람이나 물건이 '있는' 장소(部屋において猫がいる)에는 쓰지 않는다.","cmp":[{"g":"～で","d":"일상적인 장소 표시. において는 같은 뜻의 격식체."},{"g":"～にとって","d":"'~의 입장에서'라는 평가의 기준. において는 장소·분야."}],"ex":[{"jp":"会議[かいぎ]は東京[とうきょう]において行[おこな]われた。","ko":"회의는 도쿄에서 열렸다."},{"jp":"現代[げんだい]における大[おお]きな問題[もんだい]の一[ひと]つです。","ko":"현대에 있어서 큰 문제 중 하나입니다."},{"jp":"この分野[ぶんや]において、彼[かれ]は有名[ゆうめい]な研究者[けんきゅうしゃ]だ。","ko":"이 분야에서 그는 유명한 연구자다."}],"dr":[{"t":"make","q":"大阪で行われる（격식체로）","a":"大阪において行われる","hint":"で 대신 において"},{"t":"make","q":"日本 + ～ + 問題（명사 수식）","a":"日本における問題","hint":"명사 수식은 における"},{"t":"fill","q":"式[しき]は本社[ほんしゃ]の会議室[かいぎしつ]（　）行[おこな]われます。","a":"において","opts":["において","にとって","について","に対して"]}],"src":["https://bunpro.jp/ja/grammar_points/287"],"vf":1,"u":39,"g":1,"gp":"gg_N3_09"},{"id":"g3_076","t":"～にかわって","ko":"~을 대신하여","cat":"기타","conn":[{"w":"명사(사람)","f":"母 + にかわって"},{"w":"명사(사물)","f":"手紙 + にかわって"},{"w":"명사 수식","f":"手紙 + にかわる + 連絡方法"}],"rule":["1. 대신하는 대상인 명사 뒤에 にかわって(に代わって)를 붙인다.","2. 뒤에 실제로 그 일을 하는 사람이나 새 것이 온다(母にかわって私が作る).","3. 문어체에서는 にかわり, 명사를 꾸밀 때는 にかわる + 명사를 쓴다."],"why":"に + 代[か]わる(대신하다, 바뀌다)의 て형 代わって가 결합한 형태다.","nu":"두 가지로 쓴다. ① 사람 대신 다른 사람이 일을 함(社長にかわってあいさつする). ② 예전 것이 새 것으로 바뀜(手紙にかわってメールが使われる). 다소 격식 있는 말이며, 회화에서는 ～のかわりに가 흔하다.","cmp":[{"g":"～のかわりに","d":"회화에서 흔히 쓰는 '~ 대신에'. 교환·보상(手伝うかわりに)의 뜻도 있다."}],"ex":[{"jp":"母[はは]にかわって私[わたし]が料理[りょうり]を作[つく]った。","ko":"어머니를 대신해서 내가 요리를 했다."},{"jp":"社長[しゃちょう]にかわって、部長[ぶちょう]があいさつをした。","ko":"사장님을 대신해서 부장님이 인사를 했다."},{"jp":"最近[さいきん]は手紙[てがみ]にかわってメールが使[つか]われている。","ko":"요즘은 편지 대신 이메일이 쓰이고 있다."}],"dr":[{"t":"make","q":"父 → ～私が行きます","a":"父にかわって私が行きます","hint":"명사 + にかわって"},{"t":"make","q":"人間 + ～ + ロボット（명사 수식）","a":"人間にかわるロボット","hint":"명사 수식은 にかわる"},{"t":"fill","q":"病気[びょうき]の田中[たなか]さん（　）、私[わたし]が説明[せつめい]します。","a":"にかわって","opts":["にかわって","によって","にとって","において"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%AB%E4%BB%A3%E3%82%8F%E3%81%A3%E3%81%A6"],"vf":1,"u":40,"g":1,"gp":"gg_N3_10"},{"id":"g3_079","t":"～について","ko":"~에 대해(서)","cat":"기타","conn":[{"w":"명사","f":"日本 + について"},{"w":"명사 수식","f":"日本 + についての + 本"}],"rule":["1. 화제가 되는 명사 뒤에 について를 붙인다.","2. 뒤에는 話す・調べる・考える・書く 같은 말·생각에 관한 동사가 온다.","3. 명사를 꾸밀 때는 についての + 명사, 화제를 강조할 때는 については를 쓴다."],"why":"","nu":"회화와 문장 모두에 쓰는 기본 표현이다. '무엇을 다루는지(화제)'를 나타내며, 행동이 향하는 상대(先生について怒る ×)에는 に対して를 쓴다. 더 딱딱하게는 に関して를 쓴다.","cmp":[{"g":"～に関して","d":"뜻은 거의 같지만 더 격식 있고 문어적이다."},{"g":"～に対して","d":"행동·감정이 향하는 상대. について는 다루는 화제."}],"ex":[{"jp":"日本[にほん]の文化[ぶんか]について話[はな]しましょう。","ko":"일본 문화에 대해 이야기합시다."},{"jp":"この町[まち]の歴史[れきし]について調[しら]べています。","ko":"이 마을의 역사에 대해 조사하고 있습니다."},{"jp":"環境[かんきょう]についての本[ほん]を読[よ]んだ。","ko":"환경에 대한 책을 읽었다."}],"dr":[{"t":"make","q":"将来 → ～考える","a":"将来について考える","hint":"명사 + について"},{"t":"make","q":"旅行 + ～ + 話（명사 수식）","a":"旅行についての話","hint":"명사 수식은 についての"},{"t":"fill","q":"明日[あした]の試験[しけん]（　）質問[しつもん]があります。","a":"について","opts":["について","にとって","によって","において"]}],"src":["https://nihongokyoshi-net.com/2018/05/03/jlptn3-grammar-nitsuite/","https://bunpro.jp/grammar_points/225"],"vf":1,"u":40,"g":1,"gp":"gg_N3_10"},{"id":"g3_080","t":"～にとって","ko":"~에게(있어서), ~의 입장에서","cat":"기타","conn":[{"w":"명사(사람·조직)","f":"私 + にとって"},{"w":"명사 수식","f":"子ども + にとっての + 幸せ"}],"rule":["1. 입장이 되는 사람·조직 명사 뒤에 にとって를 붙인다.","2. 뒤에는 大切だ・難しい・大きな問題だ 같은 평가·판단 표현이 온다.","3. 강조·대비는 にとっては・にとっても, 명사 수식은 にとっての를 쓴다."],"why":"","nu":"회화와 문장 모두에 쓴다. 뒤에는 평가가 오며, 동작(私にとって行く ×)이나 찬성·반대 같은 태도(私にとって賛成だ ×)는 오지 않는다. 태도에는 ～としては나 ～に対して를 쓴다. 한국어 '~에게'를 그대로 に로 옮기면 뜻이 달라지는 경우가 많다.","cmp":[{"g":"～としては","d":"'~의 입장으로서는'으로 의견·태도를 말할 때. にとって는 평가."},{"g":"～に対して","d":"행동·감정이 향하는 상대."}],"ex":[{"jp":"私[わたし]にとって、家族[かぞく]は一番[いちばん]大切[たいせつ]だ。","ko":"나에게 가족은 가장 소중하다."},{"jp":"この問題[もんだい]は子[こ]どもにとって難[むずか]しい。","ko":"이 문제는 아이에게 어렵다."},{"jp":"留学生[りゅうがくせい]にとっては、漢字[かんじ]が一番[いちばん]大変[たいへん]です。","ko":"유학생에게는 한자가 가장 힘듭니다."}],"dr":[{"t":"make","q":"学生 → ～時間は大切だ","a":"学生にとって時間は大切だ","hint":"명사 + にとって + 평가"},{"t":"make","q":"会社 + ～ + 問題（명사 수식）","a":"会社にとっての問題","hint":"명사 수식은 にとっての"},{"t":"fill","q":"この写真[しゃしん]は私[わたし]（　）宝物[たからもの]です。","a":"にとって","opts":["にとって","について","によって","において"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/にとって-ni-totte-meaning"],"vf":1,"u":40,"g":1,"gp":"gg_N3_10"},{"id":"g3_083","t":"～に対して","ko":"~에 대해(서), ~에게, ~와 대조적으로","cat":"기타","conn":[{"w":"명사(대상)","f":"質問 + に対して"},{"w":"명사 수식","f":"客 + に対する + 態度"},{"w":"문장 보통형(대비)","f":"兄は背が高い + のに対して"},{"w":"な형용사·명사(대비)","f":"静かな / 学生な + のに対して"}],"rule":["1. 행동·감정이 향하는 상대 명사 뒤에 に対して를 붙인다(質問に対して答える).","2. 명사를 꾸밀 때는 に対する + 명사를 쓴다.","3. 두 사실을 대비할 때는 문장 보통형 뒤에 の를 넣어 のに対して로 잇는다. な형용사·명사 서술은 な를 넣는다(静かなのに対して).","4. 동사 뒤에 바로 に対して를 붙이지 않는다(成功したに対して ×, 成功したのに対して ○)."],"why":"","nu":"회화와 문장 모두에 쓰지만 대비의 뜻(のに対して)은 문어적이다. 화제를 다루는 について와 혼동하기 쉽다: 先生に対して失礼だ(선생님께 무례하다)는 상대, 先生について話す(선생님에 대해 이야기하다)는 화제다.","cmp":[{"g":"～について","d":"다루는 화제. に対して는 행동·감정이 향하는 상대."},{"g":"～にとって","d":"평가하는 입장. に対して는 상대·대비."}],"ex":[{"jp":"先生[せんせい]は学生[がくせい]の質問[しつもん]に対して丁寧[ていねい]に答[こた]えた。","ko":"선생님은 학생의 질문에 대해 정성껏 대답했다."},{"jp":"お客様[きゃくさま]に対する態度[たいど]が悪[わる]い。","ko":"손님에 대한 태도가 나쁘다."},{"jp":"兄[あに]は背[せ]が高[たか]いのに対して、弟[おとうと]は低[ひく]い。","ko":"형은 키가 큰 데 비해 남동생은 작다."}],"dr":[{"t":"make","q":"親 → ～文句を言う","a":"親に対して文句を言う","hint":"상대 명사 + に対して"},{"t":"make","q":"姉は料理が上手だ／妹は下手だ（대비로 잇기）","a":"姉は料理が上手なのに対して、妹は下手だ","hint":"な형용사 → な + のに対して"},{"t":"fill","q":"彼[かれ]は目上[めうえ]の人[ひと]（　）、いつも丁寧[ていねい]に話[はな]す。","a":"に対して","opts":["に対して","について","によれば","にしては"]}],"src":["https://mlcjapanese.co.jp/n2_04_31.html","https://bunpro.jp/ja/grammar_points/%E3%81%AB%E5%AF%BE%E3%81%97%E3%81%A6"],"vf":1,"u":41,"g":1,"gp":"gg_N3_10"},{"id":"g3_085","t":"～に関して","ko":"~에 관해(서)","cat":"기타","conn":[{"w":"명사","f":"事故 + に関して"},{"w":"명사 수식","f":"事故 + に関する + 説明"}],"rule":["1. 화제가 되는 명사 뒤에 に関して를 붙인다.","2. 뒤의 명사를 꾸밀 때는 に関する + 명사(또는 に関しての + 명사)를 쓴다.","3. 화제를 강조할 때는 に関しては를 쓴다."],"why":"","nu":"について와 뜻은 거의 같지만 더 딱딱하고 격식 있는 말로, 회의·안내·보도·문서에서 많이 쓴다. 친구끼리의 일상 대화에는 について가 자연스럽다. 행동이 향하는 상대(先生に関して怒る ×)에는 쓰지 않는다.","cmp":[{"g":"～について","d":"같은 뜻의 일반적인 표현. に関して가 더 격식체."},{"g":"～に対して","d":"행동·감정이 향하는 상대. に関して는 화제."}],"ex":[{"jp":"事故[じこ]に関して、会社[かいしゃ]が説明[せつめい]した。","ko":"사고에 관해 회사가 설명했다."},{"jp":"この件[けん]に関しては、私[わたし]が担当[たんとう]します。","ko":"이 건에 관해서는 제가 담당합니다."},{"jp":"健康[けんこう]に関する本[ほん]がよく売[う]れている。","ko":"건강에 관한 책이 잘 팔리고 있다."}],"dr":[{"t":"make","q":"新しい規則 → ～質問がある","a":"新しい規則に関して質問がある","hint":"명사 + に関して"},{"t":"make","q":"環境 + ～ + 問題（명사 수식）","a":"環境に関する問題","hint":"명사 수식은 に関する"},{"t":"fill","q":"会議[かいぎ]の日程[にってい]（　）、メールでお知[し]らせします。","a":"に関して","opts":["に関して","にとって","にかわって","にしては"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/に関する-に関して-ni-kan-suru-ni-kan-shite-meaning/","https://bunpro.jp/ja/grammar_points/%E3%81%AB%E9%96%A2%E3%81%99%E3%82%8B-%E3%81%AB%E9%96%A2%E3%81%97%E3%81%A6"],"vf":1,"u":41,"g":1,"gp":"gg_N3_10"},{"id":"g3_100","t":"～まま","ko":"~한 채로, ~그대로","cat":"기타","conn":[{"w":"동사 た형","f":"開けた + まま"},{"w":"동사 ない형","f":"洗わない + まま"},{"w":"い형용사","f":"若い + まま"},{"w":"な형용사","f":"きれいな + まま"},{"w":"명사","f":"昔の + まま"},{"w":"この·その","f":"この + まま"}],"rule":["1. 동사는 た형으로 바꾼다. 2그룹은 る를 た로(開ける→開けた), 1그룹은 음편(かぶる→かぶった).","2. た형 뒤에 まま를 붙인다(開けたまま).","3. な형용사는 な, 명사는 の를 붙인다(きれいなまま, 昔のまま).","4. 뒤에 다른 동작을 이을 때는 まま 또는 ままで를 쓴다(開けたまま寝た)."],"why":"","nu":"어떤 상태가 바뀌지 않고 이어지는 가운데 다른 일이 일어남을 나타내며, 그 상태가 보통과 다를 때 많이 쓴다. ます형에는 붙지 않는다. '그대로 두다'는 ままにする.","cmp":[{"g":"～っぱなし","d":"치우거나 끝내야 할 것을 방치했다는 부정적 뉘앙스가 강하다(開けっぱなし)."},{"g":"～ながら","d":"두 동작을 동시에 하는 것. 상태 유지가 아니다."}],"ex":[{"jp":"窓[まど]を開[あ]けたまま寝[ね]てしまった。","ko":"창문을 연 채로 자 버렸다."},{"jp":"靴[くつ]をはいたまま部屋[へや]に入[はい]らないでください。","ko":"신발을 신은 채로 방에 들어오지 마세요."},{"jp":"この町[まち]は昔[むかし]のままだ。","ko":"이 마을은 옛날 그대로다."}],"dr":[{"t":"make","q":"開ける → ～まま","a":"開けたまま","hint":"る를 た로 + まま"},{"t":"make","q":"帽子をかぶる → ～まま","a":"帽子をかぶったまま","hint":"1그룹 る는 った + まま"},{"t":"fill","q":"テレビをつけた（　）寝[ね]てしまった。","a":"まま","opts":["まま","ながら","ために","まで"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%BE%E3%81%BE"],"vf":1,"u":41,"g":1,"gp":"gg_N3_10"},{"id":"g3_102","t":"～てみる","ko":"~해 보다","cat":"기타","conn":[{"w":"1그룹 동사","f":"書いて + みる"},{"w":"2그룹 동사","f":"食べて + みる"},{"w":"する","f":"して + みる"},{"w":"来る","f":"来て + みる"}],"rule":["1. 동사를 て형으로 바꾼다. 1그룹: く→いて, ぐ→いで, う·つ·る→って, む·ぶ·ぬ→んで, す→して(行く→行って는 예외).","2. 2그룹은 る를 て로(食べる→食べて), する→して, 来る→来て.","3. て형 뒤에 みる를 붙인다(食べてみる). みる는 2그룹 동사처럼 활용한다(みた, みたい, みよう)."],"why":"見る(보다)가 보조동사로 쓰여 '해 보고 결과를 보다'라는 뜻이 되었다.","nu":"결과가 어떤지 알기 위해 시험 삼아 해 보는 것. 한국어 '해 보다'와 달리 '~해 본 적이 있다'는 경험은 たことがある로 말한다. 권유 てみてください, 희망 てみたい 형태로 자주 쓴다.","cmp":[{"g":"～たことがある","d":"과거 경험이 있는지를 말한다. 시도의 뜻이 아니다."}],"ex":[{"jp":"この服[ふく]、着[き]てみてもいいですか。","ko":"이 옷 입어 봐도 되나요?"},{"jp":"新[あたら]しい店[みせ]のラーメンを食[た]べてみた。","ko":"새 가게의 라멘을 먹어 봤다."},{"jp":"一度[いちど]、富士山[ふじさん]に登[のぼ]ってみたい。","ko":"한 번 후지산에 올라 보고 싶다."}],"dr":[{"t":"make","q":"書く → ～てみる","a":"書いてみる","hint":"く를 いて로 + みる"},{"t":"make","q":"使う → ～てみる","a":"使ってみる","hint":"う를 って로 + みる"},{"t":"fill","q":"わからなかったら、先生[せんせい]に聞[き]いて（　）ください。","a":"みて","opts":["みて","ある","いる","しまう"]}],"src":["https://www.tofugu.com/japanese-grammar/temiru/"],"vf":1,"u":42,"g":1,"gp":"gg_N3_10"},{"id":"g3_105","t":"めったにない","ko":"좀처럼 없다, 드물다","cat":"기타","conn":[{"w":"명사 수식","f":"めったにない + チャンス"},{"w":"명사 + は","f":"こんな機会は + めったにない"},{"w":"동사 사전형","f":"見ることは + めったにない"}],"rule":["1. 동사는 사전형에 こと를 붙여 명사로 만들고 は를 붙인다(見る→見ることは).","2. 그 뒤에 めったにない를 붙인다(見ることはめったにない).","3. 명사를 꾸밀 때는 めったにない를 명사 앞에 그대로 놓는다(めったにないチャンス)."],"why":"부사 めったに(좀처럼) + ない(없다)로, '좀처럼 없다'는 뜻이 된다.","nu":"めったに～ない의 동사 자리에 ない(없다) 자체가 온 형태. 동사에 바로 붙이지 않고 반드시 こと로 명사화한다(見るはめったにない는 틀림). 'めったにない機会·経験'처럼 귀한 일을 강조할 때 많이 쓴다.","cmp":[{"g":"めったに～ない","d":"동사 부정형과 함께 '좀처럼 ~하지 않다'(めったに行かない)."}],"ex":[{"jp":"こんなチャンスはめったにない。","ko":"이런 기회는 좀처럼 없다."},{"jp":"彼[かれ]が約束[やくそく]に遅[おく]れることはめったにない。","ko":"그가 약속에 늦는 일은 좀처럼 없다."},{"jp":"これはめったにない経験[けいけん]だった。","ko":"이것은 좀처럼 없는 경험이었다."}],"dr":[{"t":"make","q":"遅れる → ～ことはめったにない","a":"遅れることはめったにない","hint":"사전형 + ことは + めったにない"},{"t":"make","q":"チャンス → めったにない～","a":"めったにないチャンス","hint":"めったにない + 명사"},{"t":"fill","q":"このあたりで雪[ゆき]が降[ふ]ることは（　）ない。","a":"めったに","opts":["めったに","いつも","ときどき","たまに"]}],"src":["https://kotobank.jp/jeword/%E6%BB%85%E5%A4%9A","https://bunpro.jp/ja/grammar_points/%E3%82%81%E3%81%A3%E3%81%9F%E3%81%AB-%E3%81%AA%E3%81%84"],"vf":1,"u":42,"g":1,"gp":"gg_N3_10"},{"id":"g3_114","t":"～ように (제시)","ko":"~대로, ~듯이","cat":"기타","conn":[{"w":"동사 보통형","f":"言った + ように"},{"w":"명사","f":"図 + の + ように"},{"w":"연체사","f":"次 + の + ように / この + ように"}],"rule":["1. 동사는 보통형(주로 과거형)으로 만든다(言う → 言った: う를 った로).","2. 그 뒤에 ように를 붙인다(言ったように).","3. 명사는 の를 넣어 のように를 붙인다(図のように).","4. 뒤에 그 내용과 같은 방식의 행동·설명이 온다."],"why":"","nu":"앞에서 말한 것, 보여 준 것, 모두가 알고 있는 것을 그대로 가리킬 때 쓴다. 前にも言ったように, ご存じのように, 次のように처럼 정해진 표현이 많고 설명·발표에서 자주 쓴다.","cmp":[{"g":"～とおり(に)","d":"言ったとおりにする처럼 내용과 똑같이 일치한다는 뜻이 더 강하다."}],"ex":[{"jp":"前[まえ]にも言[い]ったように、明日[あした]の会議[かいぎ]は十時[じゅうじ]からです。","ko":"전에도 말했듯이 내일 회의는 10시부터입니다."},{"jp":"図[ず]のように、紙[かみ]を半分[はんぶん]に折[お]ってください。","ko":"그림과 같이 종이를 반으로 접어 주세요."},{"jp":"皆[みな]さんも知[し]っているように、この町[まち]は桜[さくら]で有名[ゆうめい]です。","ko":"여러분도 알고 있듯이 이 마을은 벚꽃으로 유명합니다."}],"dr":[{"t":"make","q":"説明する → 과거형 + ように","a":"説明したように","hint":"する를 した로 + ように"},{"t":"make","q":"次 → ～のように","a":"次のように","hint":"명사 + の + ように"},{"t":"fill","q":"先生[せんせい]が言[い]った（　）、やってみてください。","a":"ように","opts":["ように","ために","せいで","くせに"]}],"src":[],"vf":0,"u":42,"g":1,"gp":"gg_N3_10"},{"id":"g3_117","t":"～ように言う","ko":"~하라고 말하다","cat":"기타","conn":[{"w":"동사 사전형","f":"待つ + ように言う"},{"w":"동사 ない형","f":"遅れない + ように言う"}],"rule":["1. 직접 하는 부탁·명령 「～て」를 동사 사전형으로 바꾼다(待って → 待つ).","2. 하지 말라는 내용 「～ないで」는 ない형으로 바꾼다(遅れないで → 遅れない).","3. 그 뒤에 ように와 言う(과거 言った)를 붙인다.","4. 말을 들은 사람은 に로 나타낸다(弟に待つように言った)."],"why":"","nu":"다른 사람의 지시·부탁을 간접적으로 전할 때 쓴다. 言う 대신 頼む·注意する·伝える 등도 쓴다. 자신이 지시를 받은 경우에는 수동형 ように言われた로 많이 말한다.","cmp":[{"g":"「～て」と言う","d":"직접 인용. 말한 그대로를 옮긴다(「待って」と言った)."}],"ex":[{"jp":"先生[せんせい]は私[わたし]にもっと勉強[べんきょう]するように言[い]った。","ko":"선생님은 나에게 더 공부하라고 말했다."},{"jp":"母[はは]に部屋[へや]を片付[かたづ]けるように言[い]われた。","ko":"엄마에게 방을 치우라는 말을 들었다."},{"jp":"医者[いしゃ]は父[ちち]にお酒[さけ]を飲[の]まないように言[い]いました。","ko":"의사는 아버지에게 술을 마시지 말라고 말했습니다."}],"dr":[{"t":"make","q":"「待って」 → ～ように言った","a":"待つように言った","hint":"て형을 사전형으로 + ように言った"},{"t":"make","q":"「遅れないで」 → ～ように言った","a":"遅れないように言った","hint":"ないで를 ない로 + ように言った"},{"t":"fill","q":"部長[ぶちょう]は私[わたし]に資料[しりょう]をコピーする（　）言[い]った。","a":"ように","opts":["ように","ばかり","ほど","まま"]}],"src":[],"vf":0,"u":43,"g":1,"gp":"gg_N3_10"},{"id":"g3_122","t":"～わけだ","ko":"(그래서) ~인 것이다, ~인 셈이다","cat":"기타","conn":[{"w":"동사 보통형","f":"疲れる + わけだ"},{"w":"い형용사","f":"寒い + わけだ"},{"w":"な형용사","f":"静かな + わけだ"},{"w":"명사","f":"休み + という + わけだ"}],"rule":["1. 동사·い형용사는 보통형 그대로 わけだ를 붙인다(寒いわけだ).","2. な형용사는 だ를 な로 바꾸고 わけだ를 붙인다(静かだ → 静かなわけだ).","3. 명사는 という를 넣어 말하는 경우가 많다(休みというわけだ)."],"why":"","nu":"어떤 사실이나 이유를 알고 나서 '그래서 그렇구나' 하고 납득할 때, 또는 앞 내용을 바꿔 말해 '결국 ~라는 것이다'라고 결론지을 때 쓴다. 납득의 뜻으로는 どうりで와 잘 어울린다. 정중하게는 わけです.","cmp":[{"g":"～はずだ","d":"근거에서 당연히 그럴 것이라고 판단할 때 쓴다. 납득의 뜻으로는 わけだ와 바꿔 쓸 수 있는 경우도 있다."}],"ex":[{"jp":"十時間[じゅうじかん]も歩[ある]いたのか。疲[つか]れるわけだ。","ko":"10시간이나 걸었구나. 피곤할 만도 하다."},{"jp":"窓[まど]が開[あ]いていたんだ。どうりで寒[さむ]いわけだ。","ko":"창문이 열려 있었구나. 어쩐지 춥더라."},{"jp":"今日[きょう]は日曜日[にちようび]か。道[みち]が静[しず]かなわけだ。","ko":"오늘이 일요일이구나. 길이 조용한 것도 당연하다."}],"dr":[{"t":"make","q":"静かだ → ～わけだ","a":"静かなわけだ","hint":"だ를 な로 + わけだ"},{"t":"make","q":"上手だ → どうりで～わけだ","a":"どうりで上手なわけだ","hint":"だ를 な로 + わけだ"},{"t":"fill","q":"彼[かれ]は十年[じゅうねん]アメリカに住[す]んでいたそうだ。英語[えいご]が上手[じょうず]な（　）。","a":"わけだ","opts":["わけだ","ところだ","ばかりだ","ことだ"]}],"src":[],"vf":0,"u":43,"g":1,"gp":"gg_N3_10"},{"id":"g3_123","t":"～わけではない","ko":"~하는 것은 아니다","cat":"기타","conn":[{"w":"동사 보통형","f":"全部わかる + わけではない"},{"w":"い형용사","f":"高い + わけではない"},{"w":"な형용사","f":"嫌いな + わけではない"},{"w":"명사","f":"学生 + という + わけではない"}],"rule":["1. 동사·い형용사는 보통형 그대로 わけではない를 붙인다.","2. な형용사는 だ를 な로 바꾸고 わけではない를 붙인다(嫌いだ → 嫌いなわけではない).","3. 명사는 という를 넣어 말하는 경우가 많다.","4. 회화에서는 わけじゃない라고 한다."],"why":"","nu":"상대가 당연히 그렇다고 생각할 만한 것을 '꼭 그런 것은 아니다'라고 부분적으로 부정한다. だからといって·からといって와 자주 함께 쓴다. 완전히 부정하는 わけがない와 혼동하기 쉽다.","cmp":[{"g":"～わけがない","d":"'~일 리가 없다'는 강한 완전 부정."}],"ex":[{"jp":"肉[にく]が嫌[きら]いなわけではないが、あまり食[た]べない。","ko":"고기를 싫어하는 건 아니지만 별로 먹지 않는다."},{"jp":"高[たか]い服[ふく]がいつもいいわけではない。","ko":"비싼 옷이 항상 좋은 것은 아니다."},{"jp":"日本[にほん]に住[す]んでいるからといって、日本語[にほんご]が話[はな]せるわけではない。","ko":"일본에 산다고 해서 일본어를 할 수 있는 것은 아니다."}],"dr":[{"t":"make","q":"嫌いだ → ～わけではない","a":"嫌いなわけではない","hint":"だ를 な로 + わけではない"},{"t":"make","q":"全部わかる → ～わけではない","a":"全部わかるわけではない","hint":"동사 보통형 + わけではない"},{"t":"fill","q":"料理[りょうり]が好[す]きだからといって、毎日[まいにち]作[つく]る（　）。","a":"わけではない","opts":["わけではない","わけだ","ようにする","ところだ"]}],"src":[],"vf":0,"u":43,"g":1,"gp":"gg_N3_10"}];
